// 周/天/任务/讲义/资源 数据 (由旧版HTML自动提取 + 多轮补充讲义)
export const weeksData = [{"id": "w1", "badge": "W1", "title": "原理与规格：DRAM基础 + DDR4/DDR5 + 时序 + 命名", "sub": "阶段 P1 · 用一周建立\"内存是怎么回事\"的底层认知", "accept": "能口述D4/D5差异（电压/速率/架构），解释CL/tRCD/tRP/tRAS对稳定性与性能的影响。", "tools": "JEDEC规范、产品Datasheet、CPU-Z", "phase": "P1", "weekend": "周末加油站：把 D4 vs D5 对比表贴在工位；用 CPU-Z 看家里/公司所有电脑的内存并做记录；预习下周一《产品硬件结构》拆解视频。 可选：找一条坏内存/旧内存备用下周拆解", "days": [{"id": "d1", "title": "DRAM 工作原理与产品线认知", "date": "Day 1 · 周一", "dot": "1", "tasks": ["DRAM基本结构：1T1C单元、Bank/Rank/行列、刷新原理（为什么内存要刷新）", "浏览公司产品线：DDR4/DDR5 的 UDIMM/SODIMM/RDIMM 区别、SSD/PSSD/嵌入式 eMMC/UFS/LPDDR/eMCP/uMCP", "读 1 份 HOGE 产品 Datasheet，找出容量/速率/电压/时序关键页", "安装 CPU-Z，看懂 Memory 和 SPD 页布局"], "tools": "JESD79-4 前言、公司产品规格书、CPU-Z", "resources": [{"type": "vid", "url": "https://www.bilibili.com/video/BV1Htr8YhELV", "label": "▶ 用最好的动画为你讲解--内存的原理（Redknot-乔红 · 343.7万播放）"}, {"type": "vid", "url": "https://www.bilibili.com/video/BV19v4y1P7Cv", "label": "▶ 一条视频了解内存条·如何挑选（宅机侠 · 37.8万播放）"}, {"type": "vid", "url": "https://www.bilibili.com/video/BV1yqTuzeEKC", "label": "▶ 内存？显存？缓存？4分钟解释存储（超极氪 · 3.1万播放）"}, {"type": "off", "url": "https://en.wikipedia.org/wiki/Dynamic_random-access_memory", "label": "📄 维基百科·DRAM详解"}, {"type": "off", "url": "https://www.hogestorage.com/", "label": "📄 汇钜存储官网"}], "lectures": [{"title": "DRAM 工作原理（1T1C、Bank/Rank、刷新）", "html": "<h5>1. 基本存储单元：1T1C</h5>\n<p>每个 bit 由 <b>1 个晶体管 + 1 个电容</b>（1T1C）组成：电容存电荷代表 1/0，晶体管负责读写控制。相比 SRAM（6 个晶体管），1T1C 密度高、成本低、功耗相对高，所以必须<b>周期性刷新</b>——因为电容会漏电，电荷慢慢消失。</p>\n<h5>2. 层级结构：Channel → DIMM → Rank → Chip → Bank</h5>\n<ul><li><b>Channel（通道）</b>：CPU 内存控制器到内存条的数据通路。双通道 = 两条 64bit 通路并行。</li>\n<li><b>Rank（秩）</b>：内存条上一组颗粒组成的 64bit（ECC 为 72bit）数据位宽。单面 1Rank、双面 2Rank（1Rx8=单面8颗粒，2Rx8=双面16颗粒）。</li>\n<li><b>Chip（颗粒）</b>：单颗 DRAM 芯片，有 x4/x8/x16 位宽之分。</li>\n<li><b>Bank（库）</b>：颗粒内部划分的存储阵列，Bank 多 → 并行度高。</li></ul>\n<h5>3. 读写流程（为什么需要那么多时序）</h5>\n<ol><li><b>激活（ACT）</b>：选中一行（Row），把整行复制到 Sense Amplifier（感应放大器）。</li>\n<li><b>列读写</b>：在激活的行中按列（Column）读/写数据。</li>\n<li><b>预充电（PRE）</b>：写回并关闭该行，为下次访问准备。</li></ol>\n<p>这三个动作对应时序：<code>tRCD</code>（激活到读）、<code>CL</code>（读到数据）、<code>tRP</code>（预充电）、<code>tRAS</code>（激活保持最小时间）。</p>\n<h5>4. 刷新（Refresh）</h5>\n<p>因为电容漏电，必须每 64ms（高温更频繁）把每行重写一遍。刷新期间该 Bank 不能正常读写，这就是 <code>tRFC</code>/<code>tREFI</code> 的来源。DDR5 支持 per-bank 刷新，刷新干扰更小。</p>\n<div class=\"tip\">💡 FAE 理解重点：所有内存\"玄学\"故障的根源都在这里——时序太紧 → 数据没写稳 → 偶发错误；温度高 → 漏电快 → 同样参数更容易出错。</div>"}, {"title": "产品线认知：UDIMM/SODIMM/RDIMM + 存储全家桶", "html": "<h5>1. 内存模组四大形态（FAE 必须一眼分清）</h5>\n<table><tr><th>形态</th><th>全称</th><th>用在哪儿</th><th>特点</th></tr>\n<tr><td><b>UDIMM</b></td><td>Unbuffered DIMM 无缓冲</td><td>台式机</td><td>最常见；288pin（D4/D5）</td></tr>\n<tr><td><b>SODIMM</b></td><td>Small Outline DIMM 小型</td><td>笔记本/迷你主机</td><td>小尺寸；DDR4=260pin、DDR5=262pin</td></tr>\n<tr><td><b>RDIMM</b></td><td>Registered DIMM 带寄存器</td><td>服务器</td><td>有RCD芯片，可挂更多Rank/更大容量，需服务器主板</td></tr>\n<tr><td><b>LRDIMM</b></td><td>Load Reduced DIMM</td><td>高端服务器</td><td>带数据缓冲，容量更大</td></tr></table>\n<p>注意：<b>RDIMM 外观和 UDIMM 不一样</b>（PCB 上有 RCD 芯片），插到普通台式机主板上不识别——这是常见客诉场景之一。</p>\n<h5>2. 存储产品全家桶（汇钜业务全景）</h5>\n<ul><li><b>SSD 固态硬盘</b>：M.2 SATA / M.2 PCIe / 2.5寸 SATA / mSATA——按接口和协议分，速度差异大；</li>\n<li><b>PSSD 移动固态</b>：Type-C 接口便携硬盘；</li>\n<li><b>嵌入式存储</b>：\n  <ul><li><b>eMMC</b>：手机/平板的闪存，焊在主板上；</li>\n  <li><b>UFS</b>：新一代手机闪存，比 eMMC 快；</li>\n  <li><b>LPDDR4X/5X</b>：低功耗内存，手机平板用；</li>\n  <li><b>eMCP</b>：eMMC（闪存）+ LPDDR（内存）融合封装在一个芯片里；</li>\n  <li><b>uMCP</b>：UFS + LPDDR 融合封装版本。</li></ul></li></ul>\n<h5>3. FAE 为什么要知道产品全貌</h5>\n<p>客户可能从一条内存问到整套存储方案。你能讲清楚\"UDIMM 和 RDIMM 的区别、SSD 和 UFS 是什么\"，客户才会信任你在内存问题上也专业。</p>\n<div class=\"tip\">💡 记忆口诀：DIMM 按\"缓冲\"分 UDIMM（无）/RDIMM（有）；按\"大小\"分 DIMM（台式）/SODIMM（笔记本）；嵌入式看接口（eMMC/UFS）和融合（eMCP/uMCP）。</div>"}, {"title": "CPU-Z：Memory 页和 SPD 页怎么看", "html": "<h5>1. CPU-Z 是什么</h5>\n<p>CPUID 出的免费硬件检测工具，能读出 CPU/主板/内存的详细信息。FAE 用它做三件事：<b>核实内存身份、核实时序、确认频率</b>。</p>\n<h5>2. Memory 页（看\"实际运行状态\"）</h5>\n<ul><li><b>Type</b>：DDR4 还是 DDR5；</li>\n<li><b>Channel #</b>：Single/Dual/Quad——单通道还是双通道（性能差一倍）；</li>\n<li><b>DRAM Frequency</b>：实际运行频率（注意：DDR 显示的是时钟频率，实际带宽=×2，如显示 3000 = DDR4-6000？不——CPU-Z 显示的 DRAM Frequency 是实际时钟，DDR4-3200 显示 1600MHz）；</li>\n<li><b>FSB:DRAM</b>：内存与总线比例；</li>\n<li><b>CL/tRCD/tRP/tRAS</b>：当前实际时序（开了 XMP 会显示 XMP 档时序）。</li></ul>\n<h5>3. SPD 页（看\"条子身份\"）</h5>\n<ul><li><b>Memory Slot Selection</b>：选中插槽，看该条 SPD；</li>\n<li><b>Module Size</b>：容量；<b>Max Bandwidth</b>：标称最高带宽（如 DDR4-3200 = PC4-25600）；</li>\n<li><b>Manufacturer / Part Number</b>：厂商和型号——对比标签；</li>\n<li><b>Timings Table</b>：频率档位对应的时序矩阵（JEDEC 档 + XMP 档）；</li>\n<li><b>XMP/EXPO 档</b>：如果有额外 Profile 会显示更高频率及时序。</li></ul>\n<h5>4. FAE 实操四步（今天完成）</h5>\n<ol><li>下载安装 CPU-Z（官网 cpuid.com）；</li>\n<li>打开 Memory 页，截图当前频率/通道/时序；</li>\n<li>打开 SPD 页，截图条子容量/型号/时序矩阵；</li>\n<li>对照答：我的条子标称多少？实际跑多少？开没开 XMP？</li></ol>\n<div class=\"warn\">⚠️ 常见坑：客户报\"内存频率只有 1600\"——其实是 CPU-Z 显示的时钟频率（1600MHz=DDR4-3200 等效）。看频率时先确认是不是忘了 ×2。</div>"}, {"title": "读 HOGE 产品 Datasheet：找到 4 个关键页", "html": "<h5>1. 拿到 Datasheet 先看什么（FAE 焦点）</h5>\n<p>一份模组 Datasheet 几十页，FAE 只需要快速锁定 4 类关键信息：<b>容量、速率、电压、时序</b>。</p>\n<h5>2. 四个关键页速查</h5>\n<table><tr><th>关键信息</th><th>通常在哪个章节</th><th>FAE 怎么用</th></tr>\n<tr><td><b>容量/配置</b></td><td>Product Description / Ordering</td><td>核对客户订单型号=多少GB、1R/2R、x8/x16</td></tr>\n<tr><td><b>速率档位</b></td><td>Speed Grades 表</td><td>确认支持 DDR5-4800/5600/6000 哪几档</td></tr>\n<tr><td><b>电压</b></td><td>Electrical Characteristics</td><td>DDR5 1.1V / VPP 1.8V；漏标电压会误判供电问题</td></tr>\n<tr><td><b>时序表</b></td><td>Timing Parameters</td><td>各速率档对应的 CL/tRCD/tRP/tRAS 参考值</td></tr></table>\n<h5>3. 实操动作（今天就要做）</h5>\n<ol><li>从公司知识库下载 1 份 HOGE 内存 Datasheet；</li>\n<li>用 Ctrl+F 搜 \"Speed\"、\"Voltage\"、\"Timing\" 定位章节；</li>\n<li>把\"型号→容量→速率档→电压→时序\"抄成一张速查卡；</li>\n<li>对照一条实物/标签验证：标签上的型号能否在 Datasheet 找到对应参数。</li></ol>\n<h5>4. 读时序表的技巧</h5>\n<p>时序表通常是\"速率档 × 时序参数\"的矩阵：行=频率（4800/5200/5600…），列=CL/tRCD/tRP/tRAS/tRFC。查\"标称档位的时序\"用来对照 CPU-Z 实测——实测时序比表格紧说明开了 XMP，比表格松说明降频了。</p>\n<div class=\"tip\">💡 FAE 面试/考核经典题：\"拿一根条子你能说出它的规格吗？\"答案就在 Datasheet 四个关键页里。</div>"}], "out": "\"内存原理一页纸\"笔记 + CPU-Z 截图归档"}, {"id": "d2", "title": "DDR4 vs DDR5 系统对比", "date": "Day 2 · 周二", "dot": "2", "tasks": ["电压：DDR4 1.2V vs DDR5 1.1V，功耗差异与信号裕量", "速率：DDR4-2133~3200 vs DDR5-4800~6400（JEDEC标准），超过JEDEC的如7200/8000多为XMP/EXPO超频表现；预取16n vs 8n、BL16", "信道架构：DDR5 单条=2个32bit通道（非ECC），DDR4 单条=1个64bit通道", "架构升级点：DDR5 突发长度 BL16（D4=BL8）、Bank Groups 8组（D4=4组）、片内ECC（ODECC，注意≠服务器RDIMM的ECC）", "Gear1 / Gear2：内存控制器与内存频率比值（Gear1=1:1 低延迟；Gear2=2:1 可冲高频；DDR5 平台常用 Gear2）", "向同事/导师口述一遍 D4/D5 三大差异"], "tools": "JEDEC JESD79-4/JESD79-5 对比、产品规格书", "resources": [{"type": "vid", "url": "https://www.bilibili.com/video/BV1V8411o7XA", "label": "▶ DDR4和DDR5内存能混用吗？（电脑装机馆 · 4.1万播放）"}, {"type": "vid", "url": "https://www.bilibili.com/video/BV1ue12YKENw", "label": "▶ 笔记本DDR4和DDR5有什么区别（海滨稻香 · 7100播放）"}, {"type": "off", "url": "https://en.wikipedia.org/wiki/DDR5_SDRAM", "label": "📄 维基百科·DDR5 SDRAM"}, {"type": "off", "url": "https://en.wikipedia.org/wiki/DDR4_SDRAM", "label": "📄 维基百科·DDR4 SDRAM"}], "lectures": [{"title": "DDR4 vs DDR5 全面对比", "html": "<h5>1. 核心参数对比表</h5>\n<table><tr><th>项目</th><th>DDR4</th><th>DDR5</th></tr>\n<tr><td>标准电压 VDD</td><td>1.2V</td><td>1.1V</td></tr>\n<tr><td>速率（JEDEC）</td><td>2133~3200 MT/s</td><td>4800~6400 MT/s（XMP 可 7200+）</td></tr>\n<tr><td>预取长度</td><td>8n（BL8）</td><td>16n（BL16）</td></tr>\n<tr><td>Bank Groups</td><td>4 组</td><td>8 组（每 2 个 bank group 对应一个 32bit 通道）</td></tr>\n<tr><td>通道架构</td><td>单条 1×64bit</td><td>单条 2×32bit（非ECC）</td></tr>\n<tr><td>电源管理</td><td>主板 VRM 控制</td><td>PMIC 上板（模组自管理 VDD/VDDQ/VPP）</td></tr>\n<tr><td>SPD</td><td>EEPROM（I²C，串行）</td><td>SPD Hub（I3C，速率更高、可级联）</td></tr>\n<tr><td>片内 ECC</td><td>无</td><td>有 on-die ECC（纠颗粒内部偶发位错，≠服务器 RDIMM ECC）</td></tr>\n</table>\n<h5>2. 为什么 DDR5 更快</h5>\n<ul><li>预取 16n 一次拿 16 个数据 → 在相同 I/O 频率下吞吐翻倍；</li>\n<li>BL16 每次突发传输 16 字节（64bit 通道一次突发 16×64bit）；</li>\n<li>片内 ECC 允许内部纠错，为更高频率提供余量。</li></ul>\n<h5>3. 关键架构差异</h5>\n<ul><li><b>PMIC 上板</b>：DDR5 模组自带电源管理芯片，主板不再统一调内存电压；PMIC 坏了 → 整条不工作。</li>\n<li><b>SPD Hub</b>：I3C 总线，支持更高带宽 SPD 读取和温度轮询，也支持多设备连接。</li>\n<li><b>双 32bit 通道</b>：一条 DDR5 相当于内部\"两条通道\"，信道效率更高。</li></ul>\n<div class=\"warn\">⚠️ 注意：DDR5 的\"ECC\"是 on-die ECC，纠的是颗粒内部错误；服务器内存条的 ECC 是系统级纠错（RDIMM），两者不是一回事，别混淆。</div>"}, {"title": "Gear 模式与 XMP/EXPO 补充", "html": "<h5>1. Gear 模式是什么（Intel 内存时钟比）</h5>\n<p>Gear 模式 = 内存控制器频率（MC）与内存频率之间的<b>比例</b>：</p>\n<ul><li><b>Gear 1（1:1）</b>：MC = 内存频率 → 延迟低，适合高频追求性能；对 IMC 体质要求高；</li>\n<li><b>Gear 2（1:2）</b>：MC = 内存频率的一半 → 延迟略高，但对 IMC 压力小，容易跑高频；</li>\n<li><b>Gear 4（1:4，DDR5）</b>：MC 更低，用于超高频率（DDR5 高频时出现）。</li></ul>\n<h5>2. FAE 为什么要懂 Gear</h5>\n<ul><li>客诉“内存跑不到标称”：先查是否 Gear 没选对——<b>高频条默认 Gear 2 是正常设计</b>，别误判为故障；</li>\n<li>性能类客诉“延迟偏高”：Gear 1 vs Gear 2 延迟差明显——客户要性能可试 Gear 1（前提 IMC 体质够）；</li>\n<li>稳定性优化：高频率不稳定时降一档 Gear 往往就能稳——这是排查的一个有效支点。</li></ul>\n<h5>3. XMP/EXPO 与 Gear 的关系</h5>\n<p>XMP/EXPO Profile 里通常包含了推荐的 Gear 设置（厂商调好的）。开启 Profile 后 Gear 一般自动适配；手动超频时才需要自己选。所以排查顺序：<b>先确认 Profile 开启 → 再看 Gear → 再谈手动微调</b>。</p>\n<h5>4. 排查动作参考</h5>\n<table><tr><th>现象</th><th>查 Gear 的方式</th></tr>\n<tr><td>频率跑不到标称</td><td>BIOS 看当前 Gear，试 Gear 1/2 切换</td></tr>\n<tr><td>高频不稳定</td><td>降 Gear（2→1 或反之）观察稳定性</td></tr>\n<tr><td>延迟异常高</td><td>确认是否 Gear 2，Gear 1 能否稳定</td></tr></table>\n<div class=\"tip\">💡 记忆锚点：Gear 越低延迟越好但越难稳；超频不上就降档，稳定优先再谈性能。别让客户为“降档”恐慌——这是正常工程折中，不是故障。</div>"}], "out": "《D4 vs D5 对比表》（电压/速率/架构/功耗/用途）"}, {"id": "d3", "title": "时序参数：CL/tRCD/tRP/tRAS", "date": "Day 3 · 周三", "dot": "3", "tasks": ["理解 CL（CAS延迟）：读命令发出到数据返回的时钟数，越小延迟越低", "理解 tRCD/tRP/tRAS 三个时序的完整过程（激活→读→预充电）", "理解时序与稳定性关系：时序太紧→不良率上升；时序太松→性能下降", "用 CPU-Z 读本机内存时序，对照 Datasheet 标称值", "常见频率对应时序档位记忆：DDR4-3200 CL16/18/22，DDR5-5600 CL46 等"], "tools": "JEDEC 时序定义、产品Datasheet、CPU-Z Memory页", "resources": [{"type": "vid", "url": "https://www.bilibili.com/video/BV1Zd4y1377s", "label": "▶ DDR4时序的作用pt.3: tRP/tRAS（Tacoma213 · 2592播放）"}, {"type": "vid", "url": "https://www.bilibili.com/video/BV19h4y1c75g", "label": "▶ Uclk分频·内存时序控制详解（羽人过境 · 4025播放）"}, {"type": "off", "url": "https://en.wikipedia.org/wiki/Memory_timing", "label": "📄 维基百科·Memory Timings"}], "lectures": [{"title": "时序参数 CL/tRCD/tRP/tRAS 详解", "html": "<h5>1. 五大时序速查</h5>\n<table><tr><th>时序</th><th>全称</th><th>含义</th><th>大小对性能的影响</th></tr>\n<tr><td><code>CL</code></td><td>CAS Latency</td><td>列选通到数据返回的延时（读命令发出→数据出来）</td><td>越小延迟越低，越激进</td></tr>\n<tr><td><code>tRCD</code></td><td>RAS to CAS Delay</td><td>行激活（ACT）到列读（READ）的间隔</td><td>越小越好</td></tr>\n<tr><td><code>tRP</code></td><td>Row Precharge</td><td>预充电时间（关闭当前行）</td><td>越小越快换行</td></tr>\n<tr><td><code>tRAS</code></td><td>Active to Precharge</td><td>行激活后最少保持时间</td><td><b>不能太小</b>，太小数据来不及写回</td></tr>\n<tr><td><code>tRFC</code></td><td>Refresh Cycle</td><td>一次刷新所需时间</td><td>越大刷新越慢 → 压带宽</td></tr>\n</table>\n<h5>2. 怎么记忆</h5>\n<p>一次完整读操作：<code>ACT 激活行 → 等 tRCD → 发 READ → 等 CL → 数据返回 → 等 tRAS 结束 → PRE 预充电 → 等 tRP → 下一行</code></p>\n<div class=\"tip\">💡 一句话：CL/tRCD/tRP 越小越好但太紧会不稳；tRAS 有下限（约 tRCD+CL），设太小会丢数据；tRFC 影响刷新效率。</div>\n<h5>3. 对稳定性的意义（FAE 必考）</h5>\n<ul><li>时序越紧 → 留给信号建立/保持的时间窗口越小 → 颗粒体质/温度稍差就出错；</li>\n<li>速查卡：CL16-18-18-38 这种\"4 个数字\"常见于 DDR4-3200 高配；JEDEC 默认 DDR4-3200 通常是 CL22。</li></ul>"}, {"title": "CPU-Z：Memory 页和 SPD 页怎么看", "html": "<h5>1. CPU-Z 是什么</h5>\n<p>CPUID 出的免费硬件检测工具，能读出 CPU/主板/内存的详细信息。FAE 用它做三件事：<b>核实内存身份、核实时序、确认频率</b>。</p>\n<h5>2. Memory 页（看\"实际运行状态\"）</h5>\n<ul><li><b>Type</b>：DDR4 还是 DDR5；</li>\n<li><b>Channel #</b>：Single/Dual/Quad——单通道还是双通道（性能差一倍）；</li>\n<li><b>DRAM Frequency</b>：实际运行频率（注意：DDR 显示的是时钟频率，实际带宽=×2，如显示 3000 = DDR4-6000？不——CPU-Z 显示的 DRAM Frequency 是实际时钟，DDR4-3200 显示 1600MHz）；</li>\n<li><b>FSB:DRAM</b>：内存与总线比例；</li>\n<li><b>CL/tRCD/tRP/tRAS</b>：当前实际时序（开了 XMP 会显示 XMP 档时序）。</li></ul>\n<h5>3. SPD 页（看\"条子身份\"）</h5>\n<ul><li><b>Memory Slot Selection</b>：选中插槽，看该条 SPD；</li>\n<li><b>Module Size</b>：容量；<b>Max Bandwidth</b>：标称最高带宽（如 DDR4-3200 = PC4-25600）；</li>\n<li><b>Manufacturer / Part Number</b>：厂商和型号——对比标签；</li>\n<li><b>Timings Table</b>：频率档位对应的时序矩阵（JEDEC 档 + XMP 档）；</li>\n<li><b>XMP/EXPO 档</b>：如果有额外 Profile 会显示更高频率及时序。</li></ul>\n<h5>4. FAE 实操四步（今天完成）</h5>\n<ol><li>下载安装 CPU-Z（官网 cpuid.com）；</li>\n<li>打开 Memory 页，截图当前频率/通道/时序；</li>\n<li>打开 SPD 页，截图条子容量/型号/时序矩阵；</li>\n<li>对照答：我的条子标称多少？实际跑多少？开没开 XMP？</li></ol>\n<div class=\"warn\">⚠️ 常见坑：客户报\"内存频率只有 1600\"——其实是 CPU-Z 显示的时钟频率（1600MHz=DDR4-3200 等效）。看频率时先确认是不是忘了 ×2。</div>"}, {"title": "读 HOGE 产品 Datasheet：找到 4 个关键页", "html": "<h5>1. 拿到 Datasheet 先看什么（FAE 焦点）</h5>\n<p>一份模组 Datasheet 几十页，FAE 只需要快速锁定 4 类关键信息：<b>容量、速率、电压、时序</b>。</p>\n<h5>2. 四个关键页速查</h5>\n<table><tr><th>关键信息</th><th>通常在哪个章节</th><th>FAE 怎么用</th></tr>\n<tr><td><b>容量/配置</b></td><td>Product Description / Ordering</td><td>核对客户订单型号=多少GB、1R/2R、x8/x16</td></tr>\n<tr><td><b>速率档位</b></td><td>Speed Grades 表</td><td>确认支持 DDR5-4800/5600/6000 哪几档</td></tr>\n<tr><td><b>电压</b></td><td>Electrical Characteristics</td><td>DDR5 1.1V / VPP 1.8V；漏标电压会误判供电问题</td></tr>\n<tr><td><b>时序表</b></td><td>Timing Parameters</td><td>各速率档对应的 CL/tRCD/tRP/tRAS 参考值</td></tr></table>\n<h5>3. 实操动作（今天就要做）</h5>\n<ol><li>从公司知识库下载 1 份 HOGE 内存 Datasheet；</li>\n<li>用 Ctrl+F 搜 \"Speed\"、\"Voltage\"、\"Timing\" 定位章节；</li>\n<li>把\"型号→容量→速率档→电压→时序\"抄成一张速查卡；</li>\n<li>对照一条实物/标签验证：标签上的型号能否在 Datasheet 找到对应参数。</li></ol>\n<h5>4. 读时序表的技巧</h5>\n<p>时序表通常是\"速率档 × 时序参数\"的矩阵：行=频率（4800/5200/5600…），列=CL/tRCD/tRP/tRAS/tRFC。查\"标称档位的时序\"用来对照 CPU-Z 实测——实测时序比表格紧说明开了 XMP，比表格松说明降频了。</p>\n<div class=\"tip\">💡 FAE 面试/考核经典题：\"拿一根条子你能说出它的规格吗？\"答案就在 Datasheet 四个关键页里。</div>"}], "out": "时序参数速查卡（含每个时序一句话解释）"}, {"id": "d4", "title": "产品命名规则 + 颗粒规格", "date": "Day 4 · 周四", "dot": "4", "tasks": ["学习 HOGE 模组命名规则：前缀/容量/频率/电压/温度等级/颗粒厂商编码（⚠️ 以公司《产品命名规则》最新版为准）", "学习 DRAM 颗粒命名（⚠️ 型号前缀务必以厂商最新Datasheet为准）：三星 K4A=DDR4（DDR5为K4M/K4R等）、美光 MT40A=DDR4（DDR5为MT60B等）、SK海力士 H5AN=DDR4（DDR5为H5CG等）", "区分 x4/x8/x16 颗粒位宽、单面/双面、1R/2R 的意义", "读懂一条真实模组标签：PN/SN/容量/频率/序列号"], "tools": "公司《产品命名规则》、颗粒厂商Datasheet目录", "resources": [{"type": "vid", "url": "https://www.bilibili.com/video/BV1DT421S7Yj", "label": "▶ 内存颗粒有哪些？你用的是哪个级别（陈墨啥都玩 · 29.3万播放）"}, {"type": "vid", "url": "https://www.bilibili.com/video/BV1PNPTetEak", "label": "▶ 如何快速鉴别自己的内存颗粒（人民的帧数优化师 · 19.0万播放）"}, {"type": "vid", "url": "https://www.bilibili.com/video/BV1GD6iBxE9d", "label": "▶ 颗粒厂不同也能通用吗（二哈是个拆家能手 · 2.0万播放）"}, {"type": "off", "url": "https://www.samsung.com/semiconductor/products/dram/", "label": "📄 三星 DRAM 产品页（官方）"}, {"type": "off", "url": "https://www.micron.com/", "label": "📄 美光 DRAM 产品页（官方）"}, {"type": "off", "url": "https://www.skhynix.com/business/products/dram.jsp", "label": "📄 SK海力士 DRAM 产品页（官方）"}], "lectures": [{"title": "HOOE 模组命名 + 三大厂颗粒命名", "html": "<h5>1. DRAM 颗粒命名（三大厂）</h5>\n<p>（⚠️ 具体型号前缀以厂商最新 Datasheet 为准，以下为规律）</p>\n<table><tr><th>厂商</th><th>DDR4 前缀</th><th>DDR5 前缀</th><th>示例解读</th></tr>\n<tr><td>三星 Samsung</td><td>K4A…</td><td>K4M/K4R…</td><td>K4A8G165WC：K4A=DDR4，8G=8Gbit，165=x16，WC=版本</td></tr>\n<tr><td>美光 Micron</td><td>MT40A…</td><td>MT60B…</td><td>MT40A2G4WE：40=DDR4，2G=2Gbit，4=x4</td></tr>\n<tr><td>海力士 SK hynix</td><td>H5AN…</td><td>H5CG…</td><td>H5AN8G6NDJR：H5AN=DDR4，8G=8Gbit，6=x16</td></tr>\n</table>\n<h5>2. 颗粒规格位</h5>\n<ul><li><b>位宽 x4/x8/x16</b>：x8 颗粒 ×8 颗 = 64bit（1Rank）；x16 颗粒 ×4 颗 = 64bit。x4 多用于 RDIMM/服务器。</li>\n<li><b>1R vs 2R</b>：1Rx8 = 8 颗 ×8bit；2Rx8 = 16 颗 ×8bit 分两面。2R 并行度高但 IMC 负载重。</li></ul>\n<h5>3. HOGE 模组命名（⚠️ 以公司《产品命名规则》为准）</h5>\n<p>一般包含：品牌 + 系列 + 容量 + 频率 + 电压等级 + 温级 + 颗粒厂商代码。例如某条 <code>HG 16GB DDR5-5600 UDIMM</code>，字段逐一解析。入职第一周务必向导师要到命名规则文档背熟。</p>\n<div class=\"warn\">⚠️ 命名规则是 FAE 的\"身份证阅读器\"——客户报一个型号，你要能立刻说出容量/频率/颗粒。背不熟会显得很不专业。</div><h5>7. 命名解析实战（FAE 拿到一条条子怎么读）</h5><ol><li>看模组标签 → 拆 HOOE 命名：前缀/容量/频率/电压/温度/颗粒编码；</li><li>看颗粒丝印 → 拆颗粒命名：厂商前缀（三星 K4A/美光 MT40A/海力士 H5AN）+ 密度 + 位宽 + 速率档；</li><li>对照 Datasheet 验证：频率/时序/电压档位是否匹配标签；</li><li>不一致 → 怀疑标签错误/改标条/返修条 → 深查来源（这是客诉高发点）。</li></ol><p>命名解析是 FAE 的基本功：客户发一张标签照片，你能 30 秒读出规格，专业感直接拉满。</p>"}, {"title": "读 HOGE 产品 Datasheet：找到 4 个关键页", "html": "<h5>1. 拿到 Datasheet 先看什么（FAE 焦点）</h5>\n<p>一份模组 Datasheet 几十页，FAE 只需要快速锁定 4 类关键信息：<b>容量、速率、电压、时序</b>。</p>\n<h5>2. 四个关键页速查</h5>\n<table><tr><th>关键信息</th><th>通常在哪个章节</th><th>FAE 怎么用</th></tr>\n<tr><td><b>容量/配置</b></td><td>Product Description / Ordering</td><td>核对客户订单型号=多少GB、1R/2R、x8/x16</td></tr>\n<tr><td><b>速率档位</b></td><td>Speed Grades 表</td><td>确认支持 DDR5-4800/5600/6000 哪几档</td></tr>\n<tr><td><b>电压</b></td><td>Electrical Characteristics</td><td>DDR5 1.1V / VPP 1.8V；漏标电压会误判供电问题</td></tr>\n<tr><td><b>时序表</b></td><td>Timing Parameters</td><td>各速率档对应的 CL/tRCD/tRP/tRAS 参考值</td></tr></table>\n<h5>3. 实操动作（今天就要做）</h5>\n<ol><li>从公司知识库下载 1 份 HOGE 内存 Datasheet；</li>\n<li>用 Ctrl+F 搜 \"Speed\"、\"Voltage\"、\"Timing\" 定位章节；</li>\n<li>把\"型号→容量→速率档→电压→时序\"抄成一张速查卡；</li>\n<li>对照一条实物/标签验证：标签上的型号能否在 Datasheet 找到对应参数。</li></ol>\n<h5>4. 读时序表的技巧</h5>\n<p>时序表通常是\"速率档 × 时序参数\"的矩阵：行=频率（4800/5200/5600…），列=CL/tRCD/tRP/tRAS/tRFC。查\"标称档位的时序\"用来对照 CPU-Z 实测——实测时序比表格紧说明开了 XMP，比表格松说明降频了。</p>\n<div class=\"tip\">💡 FAE 面试/考核经典题：\"拿一根条子你能说出它的规格吗？\"答案就在 Datasheet 四个关键页里。</div>"}], "out": "命名规则速查卡（模组+颗粒两套规则）"}, {"id": "d5", "title": "周复盘 + 口述自测", "date": "Day 5 · 周五", "dot": "5", "tasks": ["整理本周全部笔记，归档到案例库/知识库目录", "口述自测：D4/D5差异 + 时序4个参数 + 命名规则（录音复盘）", "用\"讲授法\"：把本周内容讲给导师/同事听，收集盲点", "完成《12周计划》W1格子的验收点打勾"], "tools": "本周笔记、《00_发展规划》W1验收点", "resources": [], "lectures": [{"title": "周复盘方法论：把一周学到的变成自己的", "html": "<h5>1. 为什么每周五必须复盘</h5>\n<p>学习的本质是\"输入→加工→输出\"。周五复盘的三个动作缺一不可：<b>整理归档（防止遗忘）→ 口述讲解（检验是否真懂）→ 查漏补缺（确定下周方向）</b>。没有复盘的学习，一周后只剩 30%——你辛苦学一周，不复盘等于白学了大半。</p>\n<h5>2. 周复盘四步法（35 分钟，固定时间）</h5>\n<ol><li><b>整理（10 分钟）</b>：把本周所有笔记/截图/产出物归入知识库对应目录，编号命名——杂乱=找不到=等于没记；</li>\n<li><b>口述（15 分钟）</b>：对着大纲讲给导师/同事听，重点讲\"为什么\"而不是\"是什么\"；用<b>讲授法</b>——能讲明白才算学会，讲不通就是没懂；</li>\n<li><b>自查（5 分钟）</b>：对照《12周计划》本周验收点逐个打勾，标出\"以为会了其实不会\"的知识点；</li>\n<li><b>计划（5 分钟）</b>：写下本周 3 个最大收获 + 下周最想突破的 1 件事——目标要小到下周真的能做成。</li></ol>\n<h5>3. 口述自测清单（W1 版示例）</h5>\n<ul><li>DDR4 vs DDR5 差异能讲出 ≥5 条；</li>\n<li>CL/tRCD/tRP/tRAS 各自含义能一句话讲清；</li>\n<li>一眼看懂一条内存标签的容量/频率/时序。</li></ul>\n<p>每周末换一批题目（跟着本周内容走），这是\"检验真懂\"最直接的方式。</p>\n<h5>4. 复盘的常见误区</h5>\n<ul><li>只整理不口述 → 知识没内化；</li>\n<li>只总结不查漏 → 不知道自己不会什么；</li>\n<li>复盘拖到周日晚上 → 周五的记忆已经模糊，效果减半；</li>\n<li>写成\"流水账\" → 复盘价值在\"结论\"不在\"记录\"。</li></ul>\n<div class=\"tip\">💡 口述时手机录音，回放你会发现自己\"以为懂其实讲不通\"的地方——这就是下周要补的。这是全书最有用的一个技巧。</div><h5>5. 让复盘“上瘾”的小技巧</h5><ul><li>固定时间（周五下班前 30 分钟）和固定模板（四步法表格）；</li><li>复盘后给自己一个小奖励（下馆子/买奶茶），形成正反馈；</li><li>把“下周 1 件事”贴在最显眼处（桌面/便签），执行才不落空；</li><li>月度回顾：4 次周复盘串起来看，你会惊讶自己进步速度。</li></ul>"}, {"title": "案例库：让每一单客诉都变成资产", "html": "<h5>1. 案例库是什么（FAE 最值钱的个人资产）</h5>\n<p>案例库 = 把每一单客诉的\"现象/根因/对策/验证\"沉淀成可检索的记录。它是 FAE 最值钱的个人资产：<b>案例越多，排查越快，答辩越有底气</b>。面试/晋升时，「你处理过哪些案例、怎么处理的」比任何证书都有说服力。</p>\n<h5>2. 每例 <200 字的推荐格式（精简到可复用）</h5>\n<pre>\n案例编号：FAE-2026-XXX\n现象：一句话（客户视角）\n平台：主板/CPU/OS/内存型号\n根因：一句话（可验证）\n证据：日志/截图路径\n对策：临时 + 永久\n状态：已闭环/复核中\n</pre>\n<h5>3. 什么案例值得记（不是所有都记）</h5>\n<ul><li>第一次遇到的故障类型（新增认知）；</li>\n<li>排查过程走弯路的（<b>教训最值钱</b>——把\"当时差点往错误方向走\"写进去）；</li>\n<li>证据链完整、能当培训材料的（可分享给新人）；</li>\n<li>客户高频问题（同问必记——直接进 FAQ）。</li></ul>\n<h5>4. 归档节奏（别攒，顺手就记）</h5>\n<ul><li>客诉闭环当天顺手记一例（30 秒的事，趁热写细节才清楚）；</li>\n<li>月底统一补标签和索引（现象/平台/方法三类标签）；</li>\n<li>目标：<b>12 周 ≥10 例，一年 ≥30 例</b>——数字不到就说明你复盘不够；</li>\n<li>定期回访：哪些案例被反复问到？说明 FAQ 没覆盖；哪些过时了？更新或下架。</li></ul>\n<div class=\"tip\">💡 考核要求\"建立案例库 ≥10 例\"——现在每天闭环一单就入库，到 W12 自然达标。写案例时问自己：\"如果我失忆了，靠这条能恢复这个经验吗？\"</div><h5>5. 案例库的进阶用法（从记录到武器库）</h5><ul><li><b>检索标签体系</b>：现象关键词 + 平台 + 内存型号 + 方法——3 个月后还能搜到才是好归档；</li><li><b>案例反哺</b>：同类型案例 ≥3 个 → 提炼成 FAQ/排查手册章节；</li><li><b>年度盘点</b>：年底挑 TOP 案例做内部分享/晋升素材；</li><li><b>新人培训</b>：给新人读 3 个案例再讲出来，比讲 3 小时 PPT 有效。</li></ul>"}], "out": "W1周复盘记录 + 笔记归档完成"}]}, {"id": "w2", "badge": "W2", "title": "产品硬件结构：物理拆解 + 器件认知 + 制程瑕疵", "sub": "阶段 P1 · 把知识焊到实物上", "accept": "能对着实物指出各器件并说明作用，识别金手指/颗粒外观不良。", "tools": "实物拆解、颗粒Datasheet、PCB叠层资料", "phase": "P1", "weekend": "周末加油站：观察家里电脑内存插拔方向与锁定结构；阅读《JEDEC DDR4 模组外形规范》金手指部分； 可选：学习 RDIMM 上 RCD（寄存器）的用途，为后续服务器场景打底", "days": [{"id": "d6", "title": "内存条拆解总览", "date": "Day 6 · 周一", "dot": "1", "tasks": ["实物拆解：找到 DRAM 颗粒、SPD EEPROM/SPD Hub、PMIC、金手指、热敏电阻、标签", "对照 Datasheet 认识 PCB 上的主要走线区域（数据、地址、电源）", "拍摄拆解照片并标注每个器件名称与作用（存档）", "学习金手指引脚：UDIMM/RDIMM 都是 288pin（DDR4/DDR5）；SODIMM 是 DDR4=260pin、DDR5=262pin，注意缺口位置防插错"], "tools": "实物内存条、拆解视频、产品规格书", "resources": [{"type": "vid", "url": "https://www.bilibili.com/video/BV18t421L7oa", "label": "▶ 笔记本加内存条·拆装方法（想想3c数码 · 18.7万播放）"}, {"type": "vid", "url": "https://www.bilibili.com/video/BV1zp411f7h2", "label": "▶ 内存条的拆装（KOTIN京天售后 · 4.3万播放）"}, {"type": "vid", "url": "https://www.bilibili.com/video/BV1G2dhBmESw", "label": "▶ 学会看内存条出厂日期（政雨Rich · 2.8万播放）"}, {"type": "off", "url": "https://en.wikipedia.org/wiki/DIMM", "label": "📄 维基百科·DIMM"}], "lectures": [{"title": "内存条拆解与器件识别", "html": "<h5>1. 拆解的价值（把知识焊到实物上）</h5>\n<p>内存条上元件不多但都关键：<b>颗粒、SPD/SPD Hub、PMIC（DDR5）、电容电阻、热敏电阻、金手指</b>。拆解/观察是为了建立“实物感”——客户拍一张照片你就能看出哪里异常。</p>\n<h5>2. 器件识别清单（逐个会认）</h5>\n<ul><li><b>DRAM 颗粒</b>：方形小芯片，一面若干颗；数颗数 → 推容量配置（8 颗 x8 = 8GB 单面 等）；</li>\n<li><b>SPD</b>：DDR4 是 8-pin EEPROM（I2C）；DDR5 是 SPD Hub（I3C，带安全功能）；</li>\n<li><b>PMIC（DDR5）</b>：模组中部的小电源芯片，产生 VDD/VDDQ/VPP；</li>\n<li><b>电容/电阻</b>：0402/0603 等小封装，供电滤波与 ODT 端接；</li>\n<li><b>热敏电阻（DDR5）</b>：温度采样点，多在模组边缘；</li>\n<li><b>金手指</b>：镀金触点，注意缺口位置（防呆）。</li></ul>\n<h5>3. 拆解/观察的正确姿势</h5>\n<ul><li>先拍照（原貌存档）→ 再动手；</li>\n<li>戴防静电手套/手环（颗粒怕静电）；</li>\n<li>小螺丝刀撬卡扣、别硬掰 PCB（会伤金手指）；</li>\n<li>观察重点：颗粒型号丝印、批次码、SPD 位置、焊点外观。</li></ul>\n<h5>4. 从识别到判断（FAE 思维）</h5>\n<ul><li>识别 → 对照 Datasheet（这个颗粒是什么规格？）；</li>\n<li>判断 → 模组配置是否合理（8 颗 x8 还是 16 颗 x8？单双面？）；</li>\n<li>异常 → 焊点/丝印/批次可疑点拍照进案例库；</li>\n<li>复用 → 以后客户拍照发来，你秒认元件位置。</li></ul>\n<div class=\"tip\">💡 一口诀：“颗粒存数据、SPD 报身份、PMIC 供电压、TS 量温度、金手指练通信”——五个器件一句背完，实物指认稳。</div><h5>5. 拆解与识别考核的常见追问</h5><ul><li>“这颗颗粒是 x8 还是 x16？”→ 看丝印/查 Datasheet；</li><li>“8 颗颗粒为什么是 8GB 不是 16GB？”→ 位宽组合计算（8 颗×8bit=64bit=1 Rank）；</li><li>“DDR5 为什么颗粒旁边有 PMIC？”→ 板载供电架构；</li><li>“这颗电容是干嘛的？”→ 电压滤波/信号去耦——位置不同作用不同。</li></ul><p>能答对追问，说明不是背器件名，是真懂结构。</p>"}, {"title": "读 HOGE 产品 Datasheet：找到 4 个关键页", "html": "<h5>1. 拿到 Datasheet 先看什么（FAE 焦点）</h5>\n<p>一份模组 Datasheet 几十页，FAE 只需要快速锁定 4 类关键信息：<b>容量、速率、电压、时序</b>。</p>\n<h5>2. 四个关键页速查</h5>\n<table><tr><th>关键信息</th><th>通常在哪个章节</th><th>FAE 怎么用</th></tr>\n<tr><td><b>容量/配置</b></td><td>Product Description / Ordering</td><td>核对客户订单型号=多少GB、1R/2R、x8/x16</td></tr>\n<tr><td><b>速率档位</b></td><td>Speed Grades 表</td><td>确认支持 DDR5-4800/5600/6000 哪几档</td></tr>\n<tr><td><b>电压</b></td><td>Electrical Characteristics</td><td>DDR5 1.1V / VPP 1.8V；漏标电压会误判供电问题</td></tr>\n<tr><td><b>时序表</b></td><td>Timing Parameters</td><td>各速率档对应的 CL/tRCD/tRP/tRAS 参考值</td></tr></table>\n<h5>3. 实操动作（今天就要做）</h5>\n<ol><li>从公司知识库下载 1 份 HOGE 内存 Datasheet；</li>\n<li>用 Ctrl+F 搜 \"Speed\"、\"Voltage\"、\"Timing\" 定位章节；</li>\n<li>把\"型号→容量→速率档→电压→时序\"抄成一张速查卡；</li>\n<li>对照一条实物/标签验证：标签上的型号能否在 Datasheet 找到对应参数。</li></ol>\n<h5>4. 读时序表的技巧</h5>\n<p>时序表通常是\"速率档 × 时序参数\"的矩阵：行=频率（4800/5200/5600…），列=CL/tRCD/tRP/tRAS/tRFC。查\"标称档位的时序\"用来对照 CPU-Z 实测——实测时序比表格紧说明开了 XMP，比表格松说明降频了。</p>\n<div class=\"tip\">💡 FAE 面试/考核经典题：\"拿一根条子你能说出它的规格吗？\"答案就在 Datasheet 四个关键页里。</div>"}], "out": "标注版拆解照片（器件名称+作用）"}, {"id": "d7", "title": "DRAM 颗粒特性（三星/美光/海力士）", "date": "Day 7 · 周二", "dot": "2", "tasks": ["学习三大颗粒厂产品线：DDR4/DDR5 各自主流颗粒型号、速率档", "读懂颗粒 Datasheet 中的时序表、ODT 配置、刷新参数", "认识颗粒等级：商业级/工业级/车规级温度范围差异", "实战：认出一根真实模组上的颗粒厂商与型号，解析规格"], "tools": "三星/美光/海力士 Datasheet、颗粒实物照片", "resources": [], "lectures": [{"title": "三大厂 DRAM 颗粒深度对比", "html": "<h5>1. 为什么我们必须懂颗粒</h5>\n<p>内存条的核心就是颗粒。FAE 看一条条子的第一件事：<b>什么颗粒？几代？什么速度等级？</b>颗粒决定了条子的上限体质，也决定了超频能力和故障模式。</p>\n<h5>2. 三大厂主流颗粒谱系</h5>\n<table><tr><th>厂商</th><th>DDR4 代表</th><th>DDR5 代表</th><th>特性</th></tr>\n<tr><td>三星 Samsung</td><td>K4A8G165WC（8Gb x16）</td><td>K4M/K4R 系列（16Gb 起）</td><td>密度高、兼容性好</td></tr>\n<tr><td>美光 Micron</td><td>MT40A2G4（2Gb x4）等</td><td>MT60B 系列（16/24Gb）</td><td>低功耗表现好</td></tr>\n<tr><td>海力士 SK hynix</td><td>H5AN8G6NDJR（8Gb x16）</td><td>H5CG 系列（16Gb 起）</td><td>超频体质常更好</td></tr></table>\n<p>（⚠️ 型号前缀以厂商最新 Datasheet 为准；上面用于建立手感）</p>\n<h5>3. 颗粒规格位怎么读</h5>\n<ul><li><b>容量</b>：8Gbit / 16Gbit 指单颗容量，16Gb 颗 ×8 颗 = 16GB（1Rx8 非ECC）</li>\n<li><b>位宽 x4/x8/x16</b>：x8 颗粒×8颗=64bit 一 Rank；x16 颗粒×4颗=64bit（笔记本常见）</li>\n<li><b>速率档/时序表</b>：Datasheet 里查对应频率下的 CL/tRCD/tRP 参考值，是超频/稳定性判断基准</li></ul>\n<h5>4. 颗粒等级与温度范围</h5>\n<p>商业级（0~85℃ 结温）/ 工业级（-40~95℃）/ 车规级（-40~105℃+）。客诉\"高温死机\"先查用的是哪个等级颗粒、环境温度有没有超规格。</p>\n<div class=\"tip\">💡 颗粒 Datasheet 是 FAE 的工具书，学会查\"时序表+温度范围\"这两页，客诉 80% 的场景都能用上。</div><h5>6. 颗粒对比的实战意义（不止背书）</h5><ul><li><b>兼容性预判</b>：同一模组厂不同颗粒批次，平台兼容行为可能不同；</li><li><b>客诉判断</b>：客户报某颗粒型号的问题，先横向对比同平台其他颗粒是否复现；</li><li><b>选型支持</b>：为项目推荐颗粒时，按温度特性/超频余量/供货稳定性排序；</li><li><b>防掉包识别</b>：标签颗粒与实际丝印不符 = 改标/返修嫌疑条（客诉高发点）。</li></ul><p>能把三大厂颗粒特点讲成“选型建议+排查线索”，而不只是背型号表，才体现 FAE 的颗粒功底。</p>"}, {"title": "读 HOGE 产品 Datasheet：找到 4 个关键页", "html": "<h5>1. 拿到 Datasheet 先看什么（FAE 焦点）</h5>\n<p>一份模组 Datasheet 几十页，FAE 只需要快速锁定 4 类关键信息：<b>容量、速率、电压、时序</b>。</p>\n<h5>2. 四个关键页速查</h5>\n<table><tr><th>关键信息</th><th>通常在哪个章节</th><th>FAE 怎么用</th></tr>\n<tr><td><b>容量/配置</b></td><td>Product Description / Ordering</td><td>核对客户订单型号=多少GB、1R/2R、x8/x16</td></tr>\n<tr><td><b>速率档位</b></td><td>Speed Grades 表</td><td>确认支持 DDR5-4800/5600/6000 哪几档</td></tr>\n<tr><td><b>电压</b></td><td>Electrical Characteristics</td><td>DDR5 1.1V / VPP 1.8V；漏标电压会误判供电问题</td></tr>\n<tr><td><b>时序表</b></td><td>Timing Parameters</td><td>各速率档对应的 CL/tRCD/tRP/tRAS 参考值</td></tr></table>\n<h5>3. 实操动作（今天就要做）</h5>\n<ol><li>从公司知识库下载 1 份 HOGE 内存 Datasheet；</li>\n<li>用 Ctrl+F 搜 \"Speed\"、\"Voltage\"、\"Timing\" 定位章节；</li>\n<li>把\"型号→容量→速率档→电压→时序\"抄成一张速查卡；</li>\n<li>对照一条实物/标签验证：标签上的型号能否在 Datasheet 找到对应参数。</li></ol>\n<h5>4. 读时序表的技巧</h5>\n<p>时序表通常是\"速率档 × 时序参数\"的矩阵：行=频率（4800/5200/5600…），列=CL/tRCD/tRP/tRAS/tRFC。查\"标称档位的时序\"用来对照 CPU-Z 实测——实测时序比表格紧说明开了 XMP，比表格松说明降频了。</p>\n<div class=\"tip\">💡 FAE 面试/考核经典题：\"拿一根条子你能说出它的规格吗？\"答案就在 Datasheet 四个关键页里。</div>"}, {"title": "ODT 端接电阻带来的信号质量", "html": "<h5>1. ODT（On-Die Termination）是什么</h5>\n<p>ODT 是<b>做在颗粒内部的端接电阻</b>（终结电阻），用来吸收信号在传输线末端的反射、保持信号完整性。传统方案要在主板上布一排终结电阻，DDR4/DDR5 直接内置到 Die 里，还支持动态开关——这就是名字里 \"On-Die\" 的含义。</p>\n<h5>2. ODT 的三个参数（BIOS 里常缩写 RTT_*）</h5>\n<table><tr><th>参数</th><th>全称含义</th><th>作用</th></tr>\n<tr><td>RTT_NOM</td><td>正常运行时的端接阻值</td><td>读写数据时匹配总线阻抗，吸收反射</td></tr>\n<tr><td>RTT_WR</td><td>写入期间的动态端接</td><td>写操作瞬间切换的阻值（动态模式）</td></tr>\n<tr><td>RTT_PARK</td><td>空闲（Park）时端接</td><td>颗粒不工作时的保持阻值，防浮动</td></tr></table>\n<p>阻值档位一般是 34Ω/40Ω/48Ω/60Ω/80Ω/120Ω/240Ω 等（DDR5 还新增基于训练的自适应）——选错档 = 阻抗失配 = 反射变差。</p>\n<h5>3. 为什么 FAE 必须知道 ODT</h5>\n<ul><li>ODT 阻值需要与<b>主板板级阻抗 + 颗粒特性 + 频率</b>匹配，BIOS 通常自动配置，但排障时要能想到它；</li>\n<li>配置不对的典型表现：<b>低频没事、高频偶尔错</b>（反射在高速下才致命）、单条稳定 vs 多插不稳（动态端接数量变化）；</li>\n<li>颗粒 Datasheet 有 ODT 推荐表：同型号颗粒在不同 Rank 组合下的建议 RTT，查表可核对 BIOS 是否给歪了。</li></ul>\n<h5>4. 排障实战：什么时候怀疑 ODT</h5>\n<p>同一规格条子在 A 主板稳定、B 主板偶发错误 → 除 IMC/散热/BIOS 微码外，<b>ODT 训练结果差异</b>也是方向。排查动作：</p>\n<ol><li>先看 BIOS 是否\"Auto ODT\"/\"Memory Training\"——先恢复默认/开启自动训练再测；</li><li>用 BIOS 手动项对比（RTT_NOM/PARK 各尝试一档）看是否变化；</li><li>记录平台差异：Intel/AMD 对 ODT 的默认策略不同，AMD EXPO 与 Intel XMP 加载的参数也不同；</li><li>同条子在两台机器 A/B 交叉复测，确认是\"条子 vs 平台配合\"问题而非单条损坏。</li></ol>\n<div class=\"tip\">💡 一句话定位：ODT 问题通常\"换平台就好、复测偶发、与频率强相关\"——别一上来就说条子坏，先排除平台侧训练/端接差异。</div>"}], "out": "三大厂颗粒型号速查表"}, {"id": "d8", "title": "SPD EEPROM / SPD Hub / PMIC", "date": "Day 8 · 周三", "dot": "3", "tasks": ["理解 SPD 作用：存储容量/频率/时序/厂商信息，主板开机第一步读取", "DDR4 EEPROM（I2C） vs DDR5 SPD Hub（I3C）：总线与安全升级", "理解 PMIC 作用（DDR5 板载）：VDD/VDDQ/VPP 供电，主板上不再统一管理", "认识热敏电阻（TS）：DDR5 温控的基础，过热降频依据", "用 CPU-Z SPD 页读取一根条子的 SPD 内容并解读"], "tools": "JEDEC SPD 规范、CPU-Z SPD页、实物照片", "resources": [{"type": "vid", "url": "https://www.bilibili.com/video/BV113411i7eS", "label": "▶ 简谈内存SPD、刷写XMP（吗吗哈哈 · 8625播放）"}, {"type": "vid", "url": "https://www.bilibili.com/video/BV1r8zTBWExD", "label": "▶ DIMM？CUDIMM？类型区别（TFLASH-DIY · 7975播放）"}, {"type": "off", "url": "https://en.wikipedia.org/wiki/Serial_presence_detect", "label": "📄 维基百科·SPD"}, {"type": "off", "url": "https://www.jedec.org/standards-documents", "label": "📄 JEDEC 标准检索（官方）"}], "lectures": [{"title": "SPD / EEPROM / SPD Hub / PMIC 详解", "html": "<h5>1. SPD 是什么（内存的“身份证”）</h5>\n<p>SPD（Serial Presence Detect）是模组上保存内存“身份证”的存储区：<b>容量、频率、时序表、厂商、SN、XMP/EXPO 档</b>。主板开机第一步读 SPD 才知道怎么配置内存——SPD 错 = 识别错 = 一系列荒谬现象。</p>\n<h5>2. DDR4 vs DDR5 的 SPD 实现（大不同）</h5>\n<table><tr><th>维度</th><th>DDR4</th><th>DDR5</th></tr>\n<tr><td>器件</td><td>EEPROM（独立小芯片）</td><td>SPD Hub（集成控制器）</td></tr>\n<tr><td>总线</td><td>I2C（慢、简单）</td><td>I3C（快、双向、可校验）</td></tr>\n<tr><td>安全</td><td>基本无</td><td>带安全功能（防伪造/防止恶意改写）</td></tr>\n<tr><td>扩展</td><td>固定字段</td><td>动态、可远程管理</td></tr></table>\n<h5>3. PMIC 的作用（DDR5 改变供电架构）</h5>\n<ul><li>DDR5 模组自带 <b>PMIC（电源管理芯片）</b>，在模组上产生 <code>VDD=1.1V</code>（核心）、<code>VDDQ=1.1V</code>（I/O）、<code>VPP=1.8V</code>（字线）；</li>\n<li>不再由主板统一管理 → 每根条子独立供电、互不干扰；</li>\n<li>PMIC 坏 → 供电异常 → 整条不识别/不稳定；</li>\n<li>排查：万用表量 VDD/VDDQ/VPP 是否在规格内——PMIC 故障是 DDR5 客诉的重要方向。</li></ul>\n<h5>4. SPD 相关客诉与排查</h5>\n<ul><li><b>“容量/频率识别错”</b> → CPU-Z SPD 页读原始数据对照标签；</li>\n<li><b>“标签型号与 SPD 不符”</b> → 刷写失败/伪造/返修条 → 深查来源；</li>\n<li><b>“XMP 开启就黑屏”</b> → SPD 的 XMP 档参数可能超边 → 手动放宽/降档；</li>\n<li>判定要导出 SPD 二进制数据（CPU-Z/Thaiphoon 可导出）作为证据。</li></ul>\n<h5>5. FAE 要能回答的“为什么”</h5>\n<ul><li>为什么 DDR5 要 SPD Hub？→ 频率更高、数据量更大、安全要求更高；</li>\n<li>为什么 DDR5 要 PMIC？→ 高频供电精度要求高，板端难以统一满足；</li>\n<li>SPD 能改吗？→ 可以（工具刷写），但改错 = 条子废/识别异常，且 DDR5 有防改写。</li></ul>\n<div class=\"tip\">💡 一句记牢：“SPD 说身份、PMIC 管供电、Hub 传数据”——DDR5 三件套搞懂，SPD 类客诉不再神秘。</div>"}, {"title": "CPU-Z：Memory 页和 SPD 页怎么看", "html": "<h5>1. CPU-Z 是什么</h5>\n<p>CPUID 出的免费硬件检测工具，能读出 CPU/主板/内存的详细信息。FAE 用它做三件事：<b>核实内存身份、核实时序、确认频率</b>。</p>\n<h5>2. Memory 页（看\"实际运行状态\"）</h5>\n<ul><li><b>Type</b>：DDR4 还是 DDR5；</li>\n<li><b>Channel #</b>：Single/Dual/Quad——单通道还是双通道（性能差一倍）；</li>\n<li><b>DRAM Frequency</b>：实际运行频率（注意：DDR 显示的是时钟频率，实际带宽=×2，如显示 3000 = DDR4-6000？不——CPU-Z 显示的 DRAM Frequency 是实际时钟，DDR4-3200 显示 1600MHz）；</li>\n<li><b>FSB:DRAM</b>：内存与总线比例；</li>\n<li><b>CL/tRCD/tRP/tRAS</b>：当前实际时序（开了 XMP 会显示 XMP 档时序）。</li></ul>\n<h5>3. SPD 页（看\"条子身份\"）</h5>\n<ul><li><b>Memory Slot Selection</b>：选中插槽，看该条 SPD；</li>\n<li><b>Module Size</b>：容量；<b>Max Bandwidth</b>：标称最高带宽（如 DDR4-3200 = PC4-25600）；</li>\n<li><b>Manufacturer / Part Number</b>：厂商和型号——对比标签；</li>\n<li><b>Timings Table</b>：频率档位对应的时序矩阵（JEDEC 档 + XMP 档）；</li>\n<li><b>XMP/EXPO 档</b>：如果有额外 Profile 会显示更高频率及时序。</li></ul>\n<h5>4. FAE 实操四步（今天完成）</h5>\n<ol><li>下载安装 CPU-Z（官网 cpuid.com）；</li>\n<li>打开 Memory 页，截图当前频率/通道/时序；</li>\n<li>打开 SPD 页，截图条子容量/型号/时序矩阵；</li>\n<li>对照答：我的条子标称多少？实际跑多少？开没开 XMP？</li></ol>\n<div class=\"warn\">⚠️ 常见坑：客户报\"内存频率只有 1600\"——其实是 CPU-Z 显示的时钟频率（1600MHz=DDR4-3200 等效）。看频率时先确认是不是忘了 ×2。</div>"}, {"title": "热敏电阻 TS：DDR5 温控的\"体温计\"", "html": "<h5>1. 热敏电阻（TS / Thermal Sensor）作用</h5>\n<p>DDR5 模组上有一颗（或多颗）<b>温度传感器 TS（Thermal Sensor）</b>，通过 I3C/SPD Hub 向系统上报颗粒温度，是<b>温控降频（Thermal Throttling）的依据</b>——温度逼近阈值时，系统可主动降低内存频率/放宽时序保护芯片。</p>\n<h5>2. 能读到哪些数据（HWiNFO64 实操）</h5>\n<ul><li>打开 HWiNFO64 → Sensors 面板 → 找 <b>DIMM Thermal Sensor / Memory Module Temperature</b>；</li>\n<li>每条 DIMM 通常独立一个读数，部分还带 <b>累计工作时间（TS 自带计时器）</b>；</li>\n<li>同一位置可对比：待机 vs 满载（AIDA64 Cache&Memory / 压力测试）温度差，正常 10~25℃。</li></ul>\n<h5>3. 温度阈值参考（DDR5 商用级颗粒）</h5>\n<table><tr><th>区间</th><th>含义</th><th>建议动作</th></tr>\n<tr><td>&lt; 70℃</td><td>正常</td><td>无需处理</td></tr>\n<tr><td>70~85℃</td><td>偏高</td><td>检查风道/马甲贴合，记录趋势</td></tr>\n<tr><td>85~95℃</td><td>警戒</td><td>降频/停机风险，查散热贴装</td></tr>\n<tr><td>&gt; 95℃</td><td>危险</td><td>可能触发降频/不稳定，立即排查</td></tr></table>\n<p>⚠️ 具体上限以颗粒 Datasheet 的 Tj（结温）规格为准（商业级一般 0~85℃，工业级更高），不同颗粒/密度有差异，别拿一张表套所有型号。</p>\n<h5>4. 客诉价值：“高温死机/降速”怎么接</h5>\n<ul><li>客户报高温死机 → 要求 HWiNFO64 抓 DIMM 温度曲线 + 故障时间点；</li>\n<li><b>散热片（马甲）贴装不良 / 导热垫缺失 / 贴歪</b> → TS 读数异常偏高（同负载比其他条高 15℃+）；</li>\n<li>降频保护被触发 → 性能异常——要能区分“主动降频（温度高）”与“颗粒异常发热（电流大/早期失效）”；</li>\n<li>TS 曲线也是 NTF 偶发问题的重要环境证据：录下 30 分钟曲线，故障点温度是否超限一目了然。</li></ul>\n<h5>5. 判断动作清单</h5>\n<p>①查 Datasheet 温度范围 → ②对比故障时间点温度曲线 → ③检查散热贴装（马甲/导热垫/厚度） → ④必要时做高低温箱复现（55℃/85℃ 温区看差异）。</p>\n<div class=\"tip\">💡 考核点：能在 HWiNFO 里 10 秒内找到 DIMM 温度并读得懂的人，才配聊“高温客诉”。</div>"}], "out": "SPD/PMIC 工作原理笔记 + CPU-Z SPD 截图"}, {"id": "d9", "title": "PCB 层数与走线", "date": "Day 9 · 周四", "dot": "4", "tasks": ["学习 PCB 层数概念：常见 8/10/16 层，层数对信号完整性影响", "认识走线：等长走线保证 DQS/DQ 同步、蛇形线补偿", "学习生产工艺：贴片、回流焊、点胶、测试流程、常见制程瑕疵", "认识常见外观不良：金手指氧化/划伤、颗粒崩角/鼓包、虚焊、PCB翘曲"], "tools": "PCB叠层资料、生产工艺流程图、不良品图库", "resources": [{"type": "vid", "url": "https://www.bilibili.com/video/BV1mM4y1e72g", "label": "▶ PCB走线的串扰很难理解吗（JT硬件乐趣 · 9.2万播放）"}, {"type": "vid", "url": "https://www.bilibili.com/video/BV1d1421X7yd", "label": "▶ 高速信号如何走线·规则（凡亿教育 · 2.0万播放）"}], "lectures": [{"title": "PCB 层数 / 走线 / 制程瑕疵", "html": "<h5>1. 为什么 PCB 层数重要</h5>\n<p>内存条 PCB 常见 8/10/16 层。层数多 → 信号层/电源层分离好 → 信号完整性（SI）更好，能支持更高频率。DDR5-6400+ 的条子普遍层数更多——<b>层数决定频率上限</b>，这是选型时看规格表背后的物理原因。</p>\n<h5>2. 走线概念（FAE 听懂参数背后的含义）</h5>\n<ul><li><b>等长走线</b>：DQ/DQS 等信号要走同样长，保证同组信号同时到达 → 蛇形线补偿（一眼看 PCB 上蛇形走线就知道是等长设计）；</li>\n<li><b>差分对</b>：DQS（数据选通）等差分信号两条线并行走，抗干扰强（两条线靠得近、等长）；</li>\n<li><b>电源层/地层</b>：完整平面，减少噪声与串扰（层数够才有完整电源平面）；</li>\n<li><b>相邻层走线方向</b>：尽量垂直（减少层间串扰）。</li></ul>\n<h5>3. 制程瑕疵（外观检查常考点）</h5>\n<ul><li><b>虚焊</b>：引脚未完全润湿 → 偶发不稳定、温度敏感；</li>\n<li><b>桥连</b>：相邻脚锡连 → 短路；</li>\n<li><b>立碑/偏移</b>：贴装偏移 → 开路；</li>\n<li><b>锡球</b>：锡膏污染 → 短路风险；</li>\n<li><b>PCB 翘曲</b>：插槽接触不均 → 特定角度正常、按一下故障。</li></ul>\n<h5>4. 层数与频率的关系（客诉话术）</h5>\n<p>客户问“为什么 DDR5-6400 比 4800 贵”——除了颗粒体质，PCB 层数和走线成本也在里面：高频条为了满足信号完整性地层更多、走线更讲究。这不是玄学，是物理。</p>\n<div class=\"tip\">💡 拿一条内存看 PCB 边缘层的铜箔层数，能数出大概层数——面试亮这一手，考官会高看你一眼。</div><h5>5. 制程瑕疵与客诉的对应关系（FAE 速查）</h5><table><tr><th>瑕疵</th><th>典型客诉</th><th>证据</th></tr><tr><td>虚焊</td><td>偶发不稳定、温变触发</td><td>振动测试 + X-ray</td></tr><tr><td>桥连</td><td>短路、不开机</td><td>外观 + 万用表</td></tr><tr><td>PCB 翘曲</td><td>特定角度正常、按压故障</td><td>对光 + 插拔复现</td></tr><tr><td>颗粒崩角</td><td>识别/测试异常</td><td>微距照片</td></tr></table><p>拿到可疑条子：先拍照 → 再测 → 对照表定位 → 证据入案例库。</p>"}, {"title": "生产工艺与回流焊常见问题", "html": "<h5>1. 内存条生产主要工序（知道每步会出什么不良）</h5>\n<p>来料检验 → 烘烤除湿 → 锡膏印刷 → 贴片（SMT 贴颗粒/电容/SPD/PMIC）→ <b>回流焊</b>（加热熔锡固定）→ AOI 光学检测 → X-ray（必要时）→ 点胶加固 → 分板 → 功能测试（ATE/老化）→ 贴标签包装。</p>\n<h5>2. 回流焊温区曲线（FAE 至少要懂概念）</h5>\n<p>典型无铅曲线分四段：<b>预热（升温）→ 保温（活化助焊剂）→ 回流（峰值 235~250℃，熔锡润湿）→ 冷却</b>。曲线偏差是很多焊接类不良的根源：峰值不足→虚焊；升温过陡→冷焊/立碑；冷却过快→焊点应力裂纹。</p>\n<h5>3. 焊接类不良对照表（成因 → 现场特征）</h5>\n<table><tr><th>不良</th><th>机理</th><th>现场/测试特征</th></tr>\n<tr><td><b>虚焊</b></td><td>锡膏不足/曲线不佳，引脚未完全润湿</td><td>偶发不稳定、敲击/晃动触发、温度升高变差、换槽可能好转</td></tr>\n<tr><td><b>桥连</b></td><td>相邻引脚锡连</td><td>短路：上电异常、发热、直接不开机</td></tr>\n<tr><td><b>立碑/偏移</b></td><td>贴装偏移、回流应力不平衡</td><td>开路/接触不良，外观可见</td></tr>\n<tr><td><b>冷焊</b></td><td>回流温度不足/时间太短</td><td>焊点灰暗无光泽，振动后可能失效</td></tr>\n<tr><td><b>锡球</b></td><td>锡膏喷溅/污染</td><td>潜在短路风险，X-ray 可见</td></tr>\n<tr><td><b>焊点空洞</b></td><td>助焊剂排气残留</td><td>高功率下过热，可靠性隐患，X-ray 可见</td></tr></table>\n<h5>4. X-ray 与 AOI 检查（FAE 怎么用）</h5>\n<p>AOI 看表面（缺件/偏移/桥连），<b>X-ray 看内部</b>（BGA 焊球空洞、虚焊）。FAE 遇到疑焊接不良时：先请客户拍外观微距，必要时内部用 X-ray 复查——\"焊点空洞 X% 以内\"有行业标准可对照。</p>\n<h5>5. 与客诉的关联（FAE 判定链）</h5>\n<p>虚焊类不良的<b>三连特征</b>：<b>敲击/晃动可能触发、温度升高变差、特定插槽/特定位置复现</b>。对于这类案件：请客户录制触发过程（手机拍晃动+现象），内部复现时用\"振动+高低温\"组合测试，确证后返修/换料，并把位置、批次、生产记录对齐。</p>\n<div class=\"tip\">💡 这是\"制程问题\"与\"颗粒问题\"的判别关键：焊接不良=位置相关+机械敏感；颗粒失效=地址相关+概率出现。判断错方向，白查一周。</div>"}], "out": "制程瑕疵图鉴（每种瑕疵配图+成因）"}, {"id": "d10", "title": "实物指认考核 + 周复盘", "date": "Day 10 · 周五", "dot": "5", "tasks": ["导师考核：对着实物 30 秒内指出颗粒/SPD/PMIC/金手指并说明作用", "外观不良识别考核：给出5张图判断正常/异常并说明理由", "整理归档：本周照片+笔记入案例库/知识库", "完成《12周计划》W2 验收点打勾"], "tools": "实物、不良品图库、验收清单", "resources": [], "lectures": [{"title": "实物指认：对着内存条把器件讲一遍", "html": "<h5>1. 考核标准（对着实物 30 秒指认）</h5>\n<p>30 秒内指认：<b>DRAM 颗粒、SPD（DDR4 EEPROM / DDR5 SPD Hub）、PMIC（DDR5）、金手指、标签、热敏电阻（如有）</b>，并说清各自作用。外观不良图 5 张判断正常/异常并给理由——不光认得出，还要讲得清。</p>\n<h5>2. 指认话术模板（背熟，边说边指）</h5>\n<ul><li>\"这是 <b>DRAM 颗粒</b>，存数据的地方，x8 位宽共 N 颗组成一 Rank\"——数颗粒个数 → 判断容量/单双面；</li>\n<li>\"这是 <b>SPD</b>，存容量/频率/时序的身份信息，主板开机第一步读它\"（DDR4 是 EEPROM，I2C；DDR5 升级为 SPD Hub，I3C）；</li>\n<li>\"这是 <b>PMIC</b>（DDR5 特有），给颗粒供 VDD/VDDQ/VPP，坏了整条瘫痪\"——DDR5 不再由主板统一供电；</li>\n<li>\"这是 <b>金手指</b>，和插槽通信的触点，氧化/划伤会导致接触不良\"；</li>\n<li>\"这是 <b>热敏电阻 TS</b>（DDR5 有），给系统上报温度，是降频依据\"。</li></ul>\n<h5>3. 外观不良速认（对着图判断）</h5>\n<ul><li>金手指氧化（发暗/发绿）→ 接触不良 → 重插多次可改善；</li>\n<li>颗粒鼓包/崩角 → 存储失效风险 → 视觉异常必须深查；</li>\n<li>PCB 翘曲 → 插槽接触不均 → 特定角度正常按一下故障；</li>\n<li>标签印刷模糊/型号不明 → 物料身份存疑 → 查批次/来源；</li>\n<li>虚焊/桥连（需焊点放大看）→ 制造缺陷 → 温变/振动触发。</li></ul>\n<h5>4. 考核技巧（不只背，要练）</h5>\n<ul><li>拿自己的条子练<b>“闭眼盲摸+指认”</b>：摸到位置就能报出器件名；</li>\n<li>考官问“这里是什么”先报名字、再补一句作用——结构化的回答拿分；</li>\n<li>被问“这颗颗粒是几 x 几”？——看脚位数/标签/查 Datasheet，别猜；</li>\n<li>准备 1-2 个“为什么”进阶回答（为什么 DDR5 要 PMIC？SPD 为什么改成 Hub？）。</li></ul>\n<div class=\"tip\">💡 复盘时把 W2 的知识（引脚数、SPD 总线、PMIC 电压）和实物对一遍，形成“看得见摸得着”的记忆。会指 + 会说原理 = 稳。</div>"}, {"title": "案例库：让每一单客诉都变成资产", "html": "<h5>1. 案例库是什么（FAE 最值钱的个人资产）</h5>\n<p>案例库 = 把每一单客诉的\"现象/根因/对策/验证\"沉淀成可检索的记录。它是 FAE 最值钱的个人资产：<b>案例越多，排查越快，答辩越有底气</b>。面试/晋升时，「你处理过哪些案例、怎么处理的」比任何证书都有说服力。</p>\n<h5>2. 每例 <200 字的推荐格式（精简到可复用）</h5>\n<pre>\n案例编号：FAE-2026-XXX\n现象：一句话（客户视角）\n平台：主板/CPU/OS/内存型号\n根因：一句话（可验证）\n证据：日志/截图路径\n对策：临时 + 永久\n状态：已闭环/复核中\n</pre>\n<h5>3. 什么案例值得记（不是所有都记）</h5>\n<ul><li>第一次遇到的故障类型（新增认知）；</li>\n<li>排查过程走弯路的（<b>教训最值钱</b>——把\"当时差点往错误方向走\"写进去）；</li>\n<li>证据链完整、能当培训材料的（可分享给新人）；</li>\n<li>客户高频问题（同问必记——直接进 FAQ）。</li></ul>\n<h5>4. 归档节奏（别攒，顺手就记）</h5>\n<ul><li>客诉闭环当天顺手记一例（30 秒的事，趁热写细节才清楚）；</li>\n<li>月底统一补标签和索引（现象/平台/方法三类标签）；</li>\n<li>目标：<b>12 周 ≥10 例，一年 ≥30 例</b>——数字不到就说明你复盘不够；</li>\n<li>定期回访：哪些案例被反复问到？说明 FAQ 没覆盖；哪些过时了？更新或下架。</li></ul>\n<div class=\"tip\">💡 考核要求\"建立案例库 ≥10 例\"——现在每天闭环一单就入库，到 W12 自然达标。写案例时问自己：\"如果我失忆了，靠这条能恢复这个经验吗？\"</div><h5>5. 案例库的进阶用法（从记录到武器库）</h5><ul><li><b>检索标签体系</b>：现象关键词 + 平台 + 内存型号 + 方法——3 个月后还能搜到才是好归档；</li><li><b>案例反哺</b>：同类型案例 ≥3 个 → 提炼成 FAQ/排查手册章节；</li><li><b>年度盘点</b>：年底挑 TOP 案例做内部分享/晋升素材；</li><li><b>新人培训</b>：给新人读 3 个案例再讲出来，比讲 3 小时 PPT 有效。</li></ul>"}], "out": "W2 考核通过记录 + 周复盘"}]}, {"id": "w3", "badge": "W3", "title": "平台适配与BIOS：Intel/AMD + QVL + XMP/EXPO", "sub": "阶段 P1 · 理解\"内存装进电脑后发生什么\"", "accept": "能针对不同平台给出推荐频率/时序/电压组合；会恢复BIOS默认并开XMP/EXPO。", "tools": "主板QVL、BIOS手册、HWiNFO64", "phase": "P1", "weekend": "周末加油站：预习 W4 测试工具的官方文档；收集 3 个\"客户常见的兼容性问题\"提问并预习答案。 可选：学习 \"MemTest86 为什么是行业标准\" 维基页", "days": [{"id": "d11", "title": "Intel 12/13/14代内存规则", "date": "Day 11 · 周一", "dot": "1", "tasks": ["学习 Intel 官方内存支持：DDR4/DDR5 各代 IMC 上限频率表", "理解 Intel Gear1/Gear2 对高频的影响（D4 高频 Gear2 是常态）", "学习\"同频不同代\"平台差异：12代支持D4+D5、13/14代D5为主", "记录 2 个典型 Intel 平台的推荐内存配置并背诵"], "tools": "Intel ARK/规格页、主板内存支持页、BIOS手册", "resources": [{"type": "vid", "url": "https://www.bilibili.com/video/BV1br4y1E7jv", "label": "▶ 保姆级教程·老主板调内存频率（宇轩tech科技 · 2.8万播放）"}, {"type": "vid", "url": "https://www.bilibili.com/video/BV11N4y1q733", "label": "▶ 阿斯加特内存超频教程（张师傅电脑 · 7991播放）"}, {"type": "off", "url": "https://ark.intel.com/content/www/us/en/ark.html", "label": "📄 Intel ARK 规格库"}], "lectures": [{"title": "Intel 12/13/14代平台内存规则", "html": "<h5>1. Intel 平台内存规则的框架（先看代际再谈频率）</h5>\n<p>Intel 各代 CPU 的 IMC（内存控制器）上限不同，<b>同一个条子在 12 代和 14 代表现可能完全不同</b>。FAE 处理 Intel 平台客诉第一步：确认 CPU 代际 → 查官方支持频率 → 再看条子标称。</p>\n<h5>2. 代际概览（官方规格速查）</h5>\n<table><tr><th>代际</th><th>内存支持</th><th>关键点</th></tr>\n<tr><td>12 代（Alder Lake）</td><td>DDR4/DDR5 双支持</td><td>D4 上限 3200；D5 上限 4800（官方 JEDEC）；IMC 体质看脸</td></tr>\n<tr><td>13 代（Raptor Lake）</td><td>DDR4/DDR5</td><td>D5 上限 5600（官方）；部分 UDIMM 可更高</td></tr>\n<tr><td>14 代（Raptor Lake Refresh）</td><td>DDR5 为主</td><td>D5 上限 5600-6400（看 SKU）；更新 BIOS 支持更佳</td></tr>\n<tr><td>Core Ultra 200S（Arrow Lake）</td><td>DDR5-only</td><td>CUDIMM 支持、D5-6400+</td></tr></table>\n<p>⚠️ 官方上限是“JEDEC 保证值”，XMP/EXPO 比它高属超频，不保证——这是客诉口径的关键。</p>\n<h5>3. Gear 模式（Intel 特有）</h5>\n<ul><li>Gear 1（1:1）：MC=内存频率，延迟低，高频难稳；</li>\n<li>Gear 2（1:2）：MC 为一半，延迟略高，容易跑高频；</li>\n<li>DDR5 高频通常 Gear 2 默认——客户说“延迟高”先看 Gear。</li></ul>\n<h5>4. 频率上限的判定逻辑（客诉“跑不到标称”）</h5>\n<ol><li>查 CPU 官方支持页（Intel ARK 输入型号查 Max Memory Speed）；</li>\n<li>对比条子标称：条子标称 6000 但 CPU 官方只有 5600 → 说明 6000 靠超频，不保证；</li>\n<li>看 BIOS：是否已更新到支持该内存版本；</li>\n<li>看插槽：A2+B2 双通道是否插对；</li>\n<li>解释口径：“内存没问题，是平台上限 + 体质问题，我们建议按官方支持频率运行或换规格”。</li></ol>\n<h5>5. 常见 Intel 平台客诉</h5>\n<ul><li>“为什么 12 代跑不了 6000” → 官方 4800/5600，6000 靠 IMC 体质，随缘；</li>\n<li>“同款别人能跑 6400” → 每颗 CPU IMC 体质不同，不是条子差异；</li>\n<li>“开了 XMP 重启黑屏” → 降频/清 CMOS 恢复，换 Gear 或手动放宽时序。</li></ul>\n<div class=\"tip\">💡 记忆锚点：Intel 平台 = 先查 ARK 官方上限 → 再谈条子标称 → 分期 JEDEC vs XMP → 口径“平台上限+体质≠条子故障”。</div>"}], "out": "Intel 平台内存规则速查卡"}, {"id": "d12", "title": "AMD 平台内存规则", "date": "Day 12 · 周二", "dot": "2", "tasks": ["学习 AMD AM4/AM5 内存支持：Ryzen 5000(D4)/7000(D5) 上限", "理解 FCLK/内存频率关系、Infinity Fabric 同步/异步影响", "认识 AMD EXPO（扩展内存配置）与 Intel XMP 的异同", "对比记录：同规格条子在 Intel vs AMD 平台的推荐设置差异"], "tools": "AMD 规格页、主板 QVL、BIOS手册", "resources": [{"type": "vid", "url": "https://www.bilibili.com/video/BV1CXAzeDEZ3", "label": "▶ AMD正确配置FCLK降低延迟（陈墨啥都玩 · 7.5万播放）"}, {"type": "vid", "url": "https://www.bilibili.com/video/BV1L8411N7mZ", "label": "▶ 全网最强AMD DDR4内存超频（安油果 · 53.7万播放）"}, {"type": "off", "url": "https://www.amd.com/en/products/processors", "label": "📄 AMD 处理器官网"}], "lectures": [{"title": "AMD 平台内存规则（AM4/AM5 + EXPO）", "html": "<h5>1. AMD 平台内存规则的框架（先看 CPU 代际 + EXPO）</h5>\n<p>AMD 平台内存客诉的核心变量：<b>CPU 代际（IMC 位置/能力）+ 是否开 EXPO + FCLK 同步比</b>。AMD 的内存性能与 Infinity Fabric 频率（FCLK）紧密相关，这是 Intel 没有的维度。</p>\n<h5>2. 代际概览（官方规格速查）</h5>\n<table><tr><th>代际</th><th>内存支持</th><th>关键点</th></tr>\n<tr><td>Ryzen 5000（AM4）</td><td>DDR4</td><td>DDR4-3200 官方；FCLK 1800 常见</td></tr>\n<tr><td>Ryzen 7000（AM5）</td><td>DDR5</td><td>D5-5200 官方；EXPO 支持；FCLK 2000</td></tr>\n<tr><td>Ryzen 9000（AM5）</td><td>DDR5</td><td>D5-5600 官方；EXPO 更成熟</td></tr></table>\n<h5>3. EXPO（AMD 的超频 Profile）</h5>\n<ul><li>EXPO = AMD 版 XMP，存在 SPD 里，BIOS 开启即按高频档跑；</li>\n<li>客诉“频率只有 4800” → 大概率 EXPO 没开（D5 默认 JEDEC 4800 正常）；</li>\n<li>EXPO 开启后不稳定 → 关 EXPO 用 JEDEC 对比，确认是条子还是平台问题。</li></ul>\n<h5>4. FCLK/Infinity Fabric 与内存的同步关系</h5>\n<ul><li>FCLK（Infinity Fabric 时钟）与内存频率最好<b>同步或呈友好比例</b>（1:1 或 2:1 等）；</li>\n<li>FCLK 过高不稳定 → 内存带宽高但延迟乱、偶发错——客诉“跑分高但卡顿/蓝屏”要查这里；</li>\n<li>排查动作：BIOS 里看 FCLK 设置（Auto/手动），尝试降到安全值（如 2000）对比；</li>\n<li>AMD 平台超内存，FCLK 稳定比频率本身更重要。</li></ul>\n<h5>5. 判定逻辑（AMD 客诉“跑不到标称”）</h5>\n<ol><li>查 CPU 官方支持页（AMD 官网产品页查 Max Memory Speed）；</li>\n<li>确认 EXPO 是否开启（没开 = 按 JEDEC 跑，正常）；</li>\n<li>查看/调整 FCLK 同步（同步比不对性能差但能开机）；</li>\n<li>BIOS 更新 + 插槽 A2/B2；</li>\n<li>口径同 Intel：“平台上限 + 体质，建议官方规格或换更高 SKU”。</li></ol>\n<div class=\"tip\">💡 记忆锚点：AMD = EXPO 开关 + FCLK 同步 + 代际上限三查；FCLK 不稳定的表现是“性能怪+偶发错”，别只看频率数字。</div>"}], "out": "Intel vs AMD 平台适配对照表"}, {"id": "d13", "title": "QVL 解读实操", "date": "Day 13 · 周三", "dot": "3", "tasks": ["学习 QVL 表格各列含义：厂商/颗粒/容量/频率/时序/测试状态", "实操：在 2 块主板官网下载 QVL，检索 HOGE 型号或主流型号", "理解\"QVL 之外不一定不兼容，QVL 之内不一定绝对兼容\"边界", "记录 QVL 检索步骤，形成标准动作（客户问兼容性时怎么查）"], "tools": "华硕/微星/技嘉 QVL 文件", "resources": [{"type": "vid", "url": "https://www.bilibili.com/video/BV1VhnF6yEDQ", "label": "▶ 爆肝测试100套组合·内存不兼容原因（和微论件 · 11.2万播放）"}, {"type": "vid", "url": "https://www.bilibili.com/video/BV1ua411L78Y", "label": "▶ 内存条兼容性·玄学问题（ZoveyChen · 11.8万播放）"}, {"type": "off", "url": "https://www.asus.com/support/", "label": "📄 华硕内存支持(QVL)"}, {"type": "off", "url": "https://www.msi.com/support", "label": "📄 微星内存支持列表"}], "lectures": [{"title": "QVL 解读：怎么查、怎么看、边界在哪", "html": "<h5>1. QVL 是什么（内存合格供应商清单）</h5>\n<p>QVL（Qualified Vendor List）＝主板厂商测试认证过的内存型号清单，通常以 Excel/网页形式提供，按型号/颗粒/容量/频率/状态列出。<b>QVL 是兼容性客诉的第一参考</b>：客户买的条子不在 QVL 里，就要解释“没认证≠不能用，但风险更高”。</p>\n<h5>2. QVL 表格各列怎么读</h5>\n<table><tr><th>列</th><th>含义</th><th>FAE 看什么</th></tr>\n<tr><td>Vendor/厂商</td><td>内存品牌/模组厂</td><td>是否常在合作名录</td></tr>\n<tr><td>Part Number</td><td>模组型号（PN）</td><td>与客户条子标签完全一致</td></tr>\n<tr><td>Capacity/容量</td><td>单条容量</td><td>8/16/32 是否匹配</td></tr>\n<tr><td>Frequency/速率</td><td>标称频率档（含 XMP）</td><td>注意 JEDEC vs XMP 档</td></tr>\n<tr><td>Timing/时序</td><td>标称时序</td><td>对比客户实际跑的</td></tr>\n<tr><td>Status/状态</td><td>Verified/Tested 等</td><td>“已验证” vs “待验证”差异</td></tr></table>\n<h5>3. 怎么查 QVL（三个入口）</h5>\n<ul><li>主板官网支持页 → 内存/兼容性列表；</li>\n<li>华硕：ASUS 官网按主板型号搜 “Memory QVL”；</li>\n<li>微星：MSI 官网 → 支持 → 兼容性报告；</li>\n<li>整机厂（联想/戴尔等）→ 服务支持 → 内存兼容列表（整机指定型号更严）。</li></ul>\n<h5>4. 边界与话术（不在 QVL ≠ 不能用）</h5>\n<p>QVL 是主板厂<b>测过的样本</b>，不是“唯一可用清单”：新出的条子可能还没测到。FAE 话术：</p>\n<ul><li>“该型号暂未在 QVL 中，属于未验证状态，建议先做一轮兼容性测试”</li>\n<li>“QVL 内型号更稳，若量产建议选 QVL 型号降低风险”</li>\n<li>“不在 QVL ≠ 不兼容，但出了问题风险自担，我们可协助测试验证”</li></ul>\n<h5>5. QVL 的三个坑</h5>\n<ul><li>只看容量不看颗粒/版本（同 PN 不同颗粒批次可能行为不同）；</li>\n<li>把 XMP 档当成 JEDEC 保证（XMP 超频不保证）；</li>\n<li>拿别的厂商 QVL 当本厂（每家的测试条件不同）。</li></ul>\n<div class=\"tip\">💡 QVL 客诉三连问：条子在不在名单？在 → 按名单配置核对；不在 → 未验证风险说明 + 协助测试；在但有问题 → 走兼容性深入排查。</div>"}], "out": "QVL 检索 SOP（含截图演示）"}, {"id": "d14", "title": "BIOS 内存项 + XMP/EXPO 机制", "date": "Day 14 · 周四", "dot": "4", "tasks": ["学习 BIOS 内存菜单：频率选择、时序设置、电压（VDDQ/SA）、Gear 模式", "理解 XMP/EXPO 原理：SPD 扩展区预设的额外Profile，一键超频", "理解 XMP 失败常见原因：IMC体质、电压不足、散热、兼容性", "学习\"恢复 BIOS 默认\"的正确路径（清CMOS/默认设置）"], "tools": "BIOS手册、主板说明书", "resources": [{"type": "vid", "url": "https://www.bilibili.com/video/BV1b1BKB8EdX", "label": "▶ 保姆级XMP/EXPO开启教程（无敌电脑大王 · 2.9万播放）"}, {"type": "vid", "url": "https://www.bilibili.com/video/BV113411i7eS", "label": "▶ 简谈内存SPD、刷写XMP（吗吗哈哈 · 8625播放）"}, {"type": "off", "url": "https://en.wikipedia.org/wiki/Intel_Extreme_Memory_Profile", "label": "📄 维基百科·Intel XMP"}], "lectures": [{"title": "BIOS 内存项 + XMP/EXPO 机制", "html": "<h5>1. BIOS 内存菜单常见项</h5>\n<ul><li><b>Memory Frequency/比率</b>：手动频率或自动（Auto/By SPD）；</li>\n<li><b>XMP/EXPO Profile</b>：一键载入超频配置；</li>\n<li><b>DRAM 电压</b>：DDR5 标准 VDD/VDDQ=1.1V，XMP/EXPO 档常见 1.1~1.25V（部分高频条 1.35V+）；DDR4 XMP 常用 1.35V，加电压提高稳定性但升温；</li>\n<li><b>Gear Mode（Intel）</b>：Gear1/Gear2 选择；</li>\n<li><b>Memory Training / 重新训练</b>：开机训练记忆参数，老主板换条后建议清内存训练。</li></ul>\n<h5>2. XMP/EXPO 原理</h5>\n<p>SPD 里除了 JEDEC 标准档，还有一个（或多个）<b>超频 Profile</b>：指定了更高频率+时序+电压。BIOS 开启后按 Profile 跑，而不是按 JEDEC 保守档。</p>\n<h5>3. XMP 开启后不稳定的常见原因</h5>\n<ol><li>IMC 体质不够（CPU 不行）；</li>\n<li>电压不足（需要手动微增 VDDQ/SA）；</li>\n<li>散热不足（高温降频/不稳）；</li>\n<li>主板 BIOS 兼容性差（需更新）；</li>\n<li>混插不同频率/不同颗粒条子。</li></ol>\n<h5>4. 恢复 BIOS 默认的正确做法</h5>\n<p>进 BIOS → Load Defaults / 恢复默认设置 → 保存重启；必要时短接 CMOS 跳线或拔电池 30 秒。恢复默认后内存回到 JEDEC 档，用来排除\"超频设置导致的故障\"。</p>\n<div class=\"tip\">💡 排查客诉\"一开 XMP 就重启\"：先恢复默认确认 JEDEC 档稳定 → 再逐步开 XMP → 最后微调电压/降频定位边界。</div><h5>6. XMP/EXPO 开启后不稳定的排查顺序</h5><ol><li>恢复默认（JEDEC）对比：默认稳 = 超频相关问题，默认也不稳 = 硬件/接触问题；</li><li>确认插槽 A2+B2（双通道最优，插错影响频率与稳定性）；</li><li>更新 BIOS（新版本常改善内存兼容）；</li><li>手动微调：放宽时序一档或加电压 0.05V（记录每次变化）；</li><li>仍不稳 → 怀疑颗粒体质/散热/IMC → 按映射表深入。</li></ol><p>BIOS 内存项操作原则：<b>一次改一项、每项都记录、改完必复测</b>——这是超频排障的纪律。</p>"}], "out": "BIOS 内存项名词表（含中英文对照）"}, {"id": "d15", "title": "实操：开 XMP + 恢复默认 + 周复盘", "date": "Day 15 · 周五", "dot": "5", "tasks": ["实操：进 BIOS → 开启 XMP/EXPO → 重启验证频率时序生效", "实操：恢复 BIOS 默认 → 验证内存回到 JEDEC 标称频率", "用 HWiNFO64 对比 XMP 开/关的时序、电压、温度差异", "完成《12周计划》W3 验收点打勾 + 周复盘"], "tools": "测试平台、HWiNFO64、BIOS手册", "resources": [{"type": "vid", "url": "https://www.bilibili.com/video/BV1b1BKB8EdX", "label": "▶ 保姆级XMP/EXPO开启教程（无敌电脑大王 · 2.9万播放）"}, {"type": "vid", "url": "https://www.bilibili.com/video/BV113411i7eS", "label": "▶ 简谈内存SPD、刷写XMP（吗吗哈哈 · 8625播放）"}, {"type": "off", "url": "https://en.wikipedia.org/wiki/Intel_Extreme_Memory_Profile", "label": "📄 维基百科·Intel XMP"}], "lectures": [{"title": "BIOS 内存项 + XMP/EXPO 机制", "html": "<h5>1. BIOS 内存菜单常见项</h5>\n<ul><li><b>Memory Frequency/比率</b>：手动频率或自动（Auto/By SPD）；</li>\n<li><b>XMP/EXPO Profile</b>：一键载入超频配置；</li>\n<li><b>DRAM 电压</b>：DDR5 标准 VDD/VDDQ=1.1V，XMP/EXPO 档常见 1.1~1.25V（部分高频条 1.35V+）；DDR4 XMP 常用 1.35V，加电压提高稳定性但升温；</li>\n<li><b>Gear Mode（Intel）</b>：Gear1/Gear2 选择；</li>\n<li><b>Memory Training / 重新训练</b>：开机训练记忆参数，老主板换条后建议清内存训练。</li></ul>\n<h5>2. XMP/EXPO 原理</h5>\n<p>SPD 里除了 JEDEC 标准档，还有一个（或多个）<b>超频 Profile</b>：指定了更高频率+时序+电压。BIOS 开启后按 Profile 跑，而不是按 JEDEC 保守档。</p>\n<h5>3. XMP 开启后不稳定的常见原因</h5>\n<ol><li>IMC 体质不够（CPU 不行）；</li>\n<li>电压不足（需要手动微增 VDDQ/SA）；</li>\n<li>散热不足（高温降频/不稳）；</li>\n<li>主板 BIOS 兼容性差（需更新）；</li>\n<li>混插不同频率/不同颗粒条子。</li></ol>\n<h5>4. 恢复 BIOS 默认的正确做法</h5>\n<p>进 BIOS → Load Defaults / 恢复默认设置 → 保存重启；必要时短接 CMOS 跳线或拔电池 30 秒。恢复默认后内存回到 JEDEC 档，用来排除\"超频设置导致的故障\"。</p>\n<div class=\"tip\">💡 排查客诉\"一开 XMP 就重启\"：先恢复默认确认 JEDEC 档稳定 → 再逐步开 XMP → 最后微调电压/降频定位边界。</div><h5>6. XMP/EXPO 开启后不稳定的排查顺序</h5><ol><li>恢复默认（JEDEC）对比：默认稳 = 超频相关问题，默认也不稳 = 硬件/接触问题；</li><li>确认插槽 A2+B2（双通道最优，插错影响频率与稳定性）；</li><li>更新 BIOS（新版本常改善内存兼容）；</li><li>手动微调：放宽时序一档或加电压 0.05V（记录每次变化）；</li><li>仍不稳 → 怀疑颗粒体质/散热/IMC → 按映射表深入。</li></ol><p>BIOS 内存项操作原则：<b>一次改一项、每项都记录、改完必复测</b>——这是超频排障的纪律。</p>"}, {"title": "HWiNFO64 使用详解：温压监控 + 日志", "html": "<h5>1. HWiNFO64 的定位（免费的传感器显微镜）</h5>\n<p>HWiNFO64 是免费的硬件信息与传感器监控工具（官网 hwinfo.com）。FAE 用它看<b>温度、电压、频率</b>，判断稳定性问题的环境因素——很多“偶发死机”的答案就藏在抓到的温度/电压曲线里。<b>偶发问题的破解 = 抓环境数据</b>，HWiNFO 就是抓手。</p>\n<h5>2. 关键界面（先记这三个）</h5>\n<ul><li>启动时选 <b>Sensors-only（仅传感器）</b> 模式；</li>\n<li>找 <b>DIMM/内存温度</b>：DDR5 条子通常带温度传感器（TS）；</li>\n<li>看 <b>VDDQ / VDD 电压</b>：是否稳定在标准档附近（DDR5=1.1V；DDR4 XMP=1.35V）；</li>\n<li>看 <b>CPU/主板供电温度</b>：过热会影响内存稳定性（闷箱机案例）。</li></ul>\n<h5>3. 抓日志（重要！偶发问题的破案关键）</h5>\n<ol><li>Sensors 窗口 → 工具栏点击 <b>Logging（日志）</b> 按钮；</li>\n<li>设置间隔（如 1 秒）与保存路径（CSV）；</li>\n<li>开始记录 → 去跑压力测试/复现故障场景；</li>\n<li>故障发生后停止日志 → Excel 打开 CSV 看“崩溃前温度/电压发生了什么”。</li></ol>\n<h5>4. 与故障窗口关联（NTF 场景怎么用）</h5>\n<ul><li>只抓故障后没意义：要抓<b>故障发生前后</b>的数据（先开日志再复现）；</li>\n<li>看趋势：温度爬到 95℃ 才蓝屏？电压 1.08V 瞬时跌落？——这就是线索；</li>\n<li>日志时间线对齐 dump/事件记录（几点几分崩溃，日志里那个点前后什么样）；</li>\n<li>取证：CSV + 截图存档进案例（FA 报告证据）。</li></ul>\n<h5>5. 常用判读</h5>\n<table><tr><th>指标</th><th>正常</th><th>异常提示</th></tr>\n<tr><td>DIMM 温度</td><td>&lt; 85℃</td><td>超限 → 散热/降频检查</td></tr>\n<tr><td>VDD/VDDQ</td><td>±3% 内稳定</td><td>跌落大 → 供电/PMIC 问题</td></tr>\n<tr><td>频率实时值</td><td>与设置一致</td><td>骤降 → 降频/BIOS 自动调整</td></tr></table>\n<div class=\"tip\">💡 HWiNFO 是“环境证据”制造机：会抓日志 + 会对齐时间线 + 会看趋势，你就有能力把偶发问题从“玄学”变成“数据”。</div>"}], "out": "XMP 开/关对比记录表（频率/时序/电压/温度）"}]}, {"id": "w4", "badge": "W4", "title": "测试标准与工具：MT86 + MonitorMemtest + BurnInTest + 电气测量", "sub": "阶段 P1 · 建立\"用数据说话\"的测试能力", "accept": "独立完成一轮完整测试并判读日志，给出PASS/FAIL结论与依据。", "tools": "MT86、BurnInTest、老化箱、万用表/示波器、测试规范", "phase": "P1", "weekend": "周末加油站：P1 阶段知识自测；预习 W5 故障场景；整理 P1 阶段笔记成\"打底知识包\"（后续反复查阅）。 可选：把 MT86 判读口诀做成小卡片", "days": [{"id": "d16", "title": "MemTest86 启动盘制作 + 全流程", "date": "Day 16 · 周一", "dot": "1", "tasks": ["下载 MemTest86（x86/ARM 版本选择），用 Rufus 制作启动U盘", "学习 MT86 测试项概念：地址测试/数据测试/缓存测试/错误判定", "独立跑完一个 Pass，学会看进度与错误页", "学习判读报错地址：免费版可用地址段人工推断颗粒范围；Pro版支持自动解码到 DIMM/Chip（Test 6/14 无法解码），免费版日志无 DIMM 解码"], "tools": "MemTest86官网、Rufus、测试机", "resources": [{"type": "vid", "url": "https://www.bilibili.com/video/BV1gh4y1C7kF", "label": "▶ MemTest86使用方法简介（风吹散的思念 · 9.5万播放）"}, {"type": "vid", "url": "https://www.bilibili.com/video/BV1QU411d79u", "label": "▶ MemTest86新手教程·启动盘（金百达协助员 · 2.5万播放）"}, {"type": "off", "url": "https://www.memtest86.com/tech_booting-memtest.html", "label": "📄 MemTest86 官方手册（启动/判读）"}, {"type": "off", "url": "https://www.memtest86.com/tech_booting-memtest.html", "label": "📄 MemTest86 技术手册"}, {"type": "off", "url": "https://www.cpuid.com/softwares/cpu-z.html", "label": "📄 CPU-Z 官网"}], "lectures": [{"title": "MemTest86：制作启动盘 + 全流程判读", "html": "<h5>1. 为什么用它（MemTest86 的地位）</h5>\n<p>MemTest86 是<b>独立于操作系统</b>的开机级内存测试工具（PassMark 出品），从 USB 启动，绕过系统/驱动干扰，直接扫描内存硬件错误。<b>行业默认的最终判据之一</b>：内存有没有问题，MT86 跑一轮比系统里任何软件都可信。</p>\n<h5>2. 制作启动 U 盘（标准流程，10 分钟）</h5>\n<ol><li>下载 MemTest86 镜像（x86/x64 用 PC 版；企业/服务器平台确认 UEFI 模式）；</li>\n<li>用 <b>Rufus</b> 或 MemTest86 自带工具写 U 盘（⚠️ 注意备份 U 盘数据，会清空）；</li>\n<li>电脑重启 → 按 F8/F11/F12（看主板）选 U 盘启动 → 进入测试界面（新版支持 XMP 配置读取）。</li></ol>\n<h5>3. 测试配置建议（客诉级别）</h5>\n<table><tr><th>场景</th><th>Pass 数</th><th>时长参考</th><th>目的</th></tr>\n<tr><td>快速筛查</td><td>1 Pass</td><td>约 1-2h</td><td>初步判断有无硬件错误</td></tr>\n<tr><td>客诉常规</td><td>2-4 Pass</td><td>过夜</td><td>排除偶发，覆盖更多地址</td></tr>\n<tr><td>疑难/NTF</td><td>≥4 Pass + 长测</td><td>24h+</td><td>间歇性/高温边界问题</td></tr></table>\n<p>建议同时开 <b>ECC 校验（如支持）</b>和 <b>温度监控</b>；高温环境（夏天/机箱悶）可在 55℃ 环境下复测，很多临界条子在温度高时才出错。</p>\n<h5>4. 判读（核心动作）</h5>\n<ul><li>看 <b>Errors 是否为 0</b>——任何 Error 都是 FAIL；</li>\n<li>看错误<b>地址范围</b>：免费版可按地址段人工推断颗粒区域（结合插槽号与 Rank）；Pro 版自动解码到 DIMM/Chip（Test 6/14 除外）；</li>\n<li>记录错误<b>模式</b>：固定地址反复错 = 颗粒/通道问题；随机地址零星错 = 电压/时序/温度边界；大面积错 = 接触/颗粒严重故障或多通道问题；</li>\n<li>跑完保存日志（免费版可截图/存 HTML，Pro 出报告）。</li></ul>\n<h5>5. 判定标准与后续</h5>\n<p><b>0 Error + 完整跑完 = PASS</b>；出现 Error = FAIL，下一步：换槽/换条/交叉替换确认<b>哪根条的哪颗粒/哪个通道</b>，然后决定换货/返修/换平台复测。</p>\n<div class=\"warn\">⚠️ 重要细节：免费版无法自动 DIMM/chip 解码，地址推断依赖经验和插槽图；别从\"广告多的第三方站\"下载，官方 memtest86.com 下载即可，Pro 版功能不需要就别花钱。</div>\n<div class=\"tip\">💡 考核点：能说清\"为什么用 MT86 而不是 Windows 内存诊断\"——答：开机级 + 独立于 OS + 覆盖率高的标准判据。</div>"}], "out": "可启动的 MT86 U盘 + 首轮测试日志"}, {"id": "d17", "title": "MonitorMemtest + BurnInTest", "date": "Day 17 · 周二", "dot": "2", "tasks": ["学习 MonitorMemtest：Windows 下的图形化内存测试工具", "学习 BurnInTest：测试项配置、内存占比、时长设置（8h+目标）", "实操：设置 BurnInTest RAM 测试（≥90%内存/循环/日志输出）", "学习日志判读：Error 计数、测试进度、如何定位失败项"], "tools": "MonitorMemtest、BurnInTest、测试规范", "resources": [{"type": "vid", "url": "https://www.bilibili.com/video/BV1ZMoeBPEKx", "label": "▶ 保姆级内存条测试·tm5压力/台风（宅机侠 · 17.6万播放）"}, {"type": "vid", "url": "https://www.bilibili.com/video/BV1MjKb62EtX", "label": "▶ 运维必备内存压测工具memtester（尚诚云课堂 · 1074播放）"}, {"type": "off", "url": "https://www.passmark.com/products/burnintest/index.php", "label": "📄 PassMark BurnInTest 官网"}], "lectures": [{"title": "MonitorMemtest + BurnInTest：压力测试", "html": "<h5>1. MonitorMemtest 用途（Windows 下图形化内存测试）</h5>\n<p>MonitorMemtest 是 PassMark 免费工具，适合<b>系统可进、想后台跑</b>观察场景：打开后持续监控内存读写、实时显示 Error，能指定内存区域测试。定位：轻量筛查 + 系统级观察，和 MT86 互补。</p>\n<h5>2. BurnInTest 配置（8h+ 长稳）</h5>\n<ol><li>新建测试 → 勾选 <b>RAM</b>（可加 CPU/Disk 模拟整机负载——客诉\"整机不稳定\"要加）；</li>\n<li>设置测试时间 480 分钟（8h）或循环次数——<b>长测才有说服力</b>；</li>\n<li>内存占用 ≥90% 才能有效压满（测多少配多少，默认可能只压一部分）；</li>\n<li>开启自动保存日志（CSV/HTML），便于截图存证——日志路径设好，别默认放 C 盘根目录；</li>\n<li>建议同时记录 HWiNFO 温度（观察高温是否触发降频/错误）。</li></ol>\n<h5>3. 判读（长测后怎么看）</h5>\n<ul><li>看 <b>Pass/Fail 计数</b>：0 Error + 持续运行 = 通过；任何 Error 都是 FAIL；</li>\n<li>中途蓝屏/死机 → 记录<b>时间点与当时温度/负载</b>，反查日志（哪个测试项、什么负载出问题）；</li>\n<li>与 MT86 配合：<b>MT86 查硬件坏点，BurnInTest 查系统级稳定性/NTF 复现</b>——分工明确，先用 MT86 排除硬件，再用 BurnIn 排查系统级；</li>\n<li>完成时导出报告（HTML 有测试摘要，可以直接贴进 FA 报告）。</li></ul>\n<h5>4. 常见误用提醒</h5>\n<ul><li>只跑 5 分钟就说\"稳定\"——长稳的价值在时间；</li>\n<li>内存占用 50% 就以为压满了；</li>\n<li>蓝屏了不记时间点直接重开——日志就废了。</li></ul>\n<div class=\"tip\">💡 判读要领：Error=0 是底线，测试时长是说服力，时间点日志是反查钥匙——三者齐全，才算一次有效长稳。</div><h5>5. 长测结果怎么写入 FA 报告</h5><ol><li>引 BurnInTest 报告/日志（含 Pass Fail 计数与时长）；</li><li>注明环境：内存占用比例/温度区间/工具版本；</li><li>意外事件（蓝屏/重启）要单独附日志和时间点；</li><li>结论写法：“8h 压力 0 Error，温度 65-75℃，判定通过”。</li></ol>"}], "out": "8h 压力测试参数配置截图 + 日志模板"}, {"id": "d18", "title": "稳定/兼容/性能测试 + 不良判定", "date": "Day 18 · 周三", "dot": "3", "tasks": ["学习测试规范的结构：目的/环境/步骤/判定标准", "兼容性测试：多平台点测流程（Intel+AMD+笔记本平台）", "性能测试基础：跑分工具（AIDA64 Cache&Memory Benchmark）", "学习不良项判定标准：出现 1 个错误算 FAIL？判据要查规范", "学习高低温老化测试概念：高温老化（如55℃/85℃）与低温老化目的，温区设置⚠️以公司测试规范为准", "认识信创平台测试（有项目时）：Stress/Memtest/Stream/S3/S4/Reboot/LTP——国产平台（飞腾/兆芯/麒麟等）基线测试方法，详见《02_工具实操手册》A4节"], "tools": "公司测试规范、AIDA64、测试记录模板", "resources": [], "lectures": [{"title": "测试规范：怎么测、按什么判", "html": "<h5>1. 测试规范是什么（判据的“宪法”）</h5>\n<p>测试规范 = 规定“测什么、怎么测、按什么判”的正式文档。<b>没有规范 = 没有判据 = 无法下结论</b>。FAE 遇到判不定 PASS/FAIL 时，第一反应不是自己想，是查规范。</p>\n<h5>2. 测试规范的结构（四段式）</h5>\n<ol><li><b>目的</b>：为什么测（验证稳定性/兼容/性能）；</li>\n<li><b>环境</b>：平台/温度/工具版本（环境不写全，结果不可比）；</li>\n<li><b>步骤</b>：具体到“工具+参数+时长+对象”；</li>\n<li><b>判定标准</b>：什么算 PASS / 什么算 FAIL / 边界条件。</li></ol>\n<h5>3. 判定标准怎么写（最重要）</h5>\n<ul><li>定性转定量：不写“运行稳定”，写“MT86 2 Pass 0 Error/BurnIn 8h 0 Error”；</li>\n<li>失败条件明确：出现 1 个 Error 算 FAIL？还是允许恢复后继续？——判据要查规范；</li>\n<li>边界情况：温度超限是否豁免？工具版本差异怎么处理？</li>\n<li>不确定先问：拿不准的判据问主管/看规范版本，别自己定。</li></ul>\n<h5>4. 高低温老化测试概念（FAE 要知道温区意义）</h5>\n<ul><li><b>高温老化（如 55℃/85℃）</b>：让临界失效（虚焊/时序边界/颗粒退化）显形——温度升高漏电加快、信号裕量变小；</li>\n<li><b>低温</b>：验证冷启动/低温时序（部分平台低温不稳）；</li>\n<li>温区设置 ⚠️ <b>以公司测试规范为准</b>（不同产品/颗粒规格不同）；</li>\n<li>老化时长：从几小时到数十小时，按规范与产品等级；</li>\n<li>客诉“夏天死机”：高低温复现是最有力的验证手段。</li></ul>\n<h5>5. 测试过程中的记录要求</h5>\n<ul><li>环境全记录（日期/温度/平台/BIOS/工具版本）；</li>\n<li>结果按时间点记录（何时开始/何时错误/何时结束）；</li>\n<li>异常截图/日志存档（证据链）；</li>\n<li>测试人签名（谁测的对结果负责）。</li></ul>\n<div class=\"tip\">💡 规范是“地图”，判据是“红线”：会读规范、会按判据下结论，测试才算真会。遇到“不知道按什么判” = 第一时间查规范，不是瞎猜。</div>"}, {"title": "AIDA64 使用详解：内存压力 + 性能基准", "html": "<h5>1. AIDA64 在 FAE 工具箱中的定位</h5>\n<p>AIDA64 = <b>信息+性能+压力</b>三合一工具：看信息（内存/SPD/主板）、跑性能（Cache & Memory Benchmark）、压系统（System Stability Test）。FAE 用它做“性能类客诉”和“稳定性复现”的第一现场。</p>\n<h5>2. 关键界面（先记这三个）</h5>\n<ul><li><b>Computer → DMI/SMBIOS</b>：内存插槽信息、容量、频率（对照识别）；</li>\n<li><b>Motherboard → SPD</b>：各内存条的 SPD 数据（XMP 档、厂商、颗粒信息）；</li>\n<li><b>Tools → Cache & Memory Benchmark</b>：读/写/复制/延迟四项指标；</li>\n<li><b>Tools → System Stability Test</b>：压力测试面板（勾选内存项）。</li></ul>\n<h5>3. 性能基准解读（判读 4 个值）</h5>\n<table><tr><th>指标</th><th>含义</th><th>异常提示</th></tr>\n<tr><td>Read/Write/Copy</td><td>带宽（GB/s）</td><td>明显偏低 → 频率/通道/设置问题</td></tr>\n<tr><td>Latency（延迟）</td><td>纳秒（ns）</td><td>异常高 → Gear/FCLK/时序问题</td></tr></table>\n<ul><li>对比基准：同平台同频率参考值（网上/同事数据）；</li>\n<li>比“自己上次”更有意义：客户报“性能变差了”→ 同机跑两次对比，排除主观。</li></ul>\n<h5>4. 压力测试用法</h5>\n<ul><li>Stress Cache & Memory + Stress FPU 可同时勾（模拟高负载）；</li>\n<li>时长：性能验证 30 分钟；稳定性验证 1-8h；</li>\n<li>同时开 HWiNFO 看温度，故障时回看曲线；</li>\n<li>中途报错/蓝屏：记录时间点 + 当时的温度/负载。</li></ul>\n<h5>5. 常见客诉场景</h5>\n<ul><li>“跑分比之前低” → 同条件复跑 + 查频率是否回落/XMP 是否失效；</li>\n<li>“压力测试报错” → 定位环节：降频/关 XMP/换槽逐一排除；</li>\n<li>“延迟很高” → 查 Gear/FCLK/时序是否被 BIOS 自动放宽。</li></ul>\n<div class=\"tip\">💡 AIDA64 三连：SPD 看身份、Benchmark 看性能、Stability 看稳定——三个界面十秒记住，客诉从“感觉不对”变成“数据说话”。</div>"}, {"title": "信创平台测试工具补充（memtester/Stream/LTP/S3S4循环）", "html": "<h5>1. 信创平台为什么单独讲</h5>\n<p>信创（信息技术应用创新）= 国产 CPU/OS/整机生态（如龙芯/兆芯/飞腾 + 统信UOS/麒麟 + 国产主板）。内存 FAE 在信创场景常遇到：<b>平台新、资料少、内存兼容问题多、测试工具要换思路</b>。会普通 x86 平台 ≠ 会信创平台。</p>\n<h5>2. 信创平台内存测试常用工具</h5>\n<table><tr><th>工具</th><th>用途</th><th>特点</th></tr>\n<tr><td>memtester</td><td>内存压力测试（Linux 命令行）</td><td>轻量、可脚本化、适合信创 Linux</td></tr>\n<tr><td>Stream</td><td>内存带宽基准（Linux）</td><td>测持续带宽，对比平台差异</td></tr>\n<tr><td>LTP（Linux Test Project）</td><td>系统级稳定性测试套件</td><td>覆盖内存/文件/进程，长测稳定</td></tr>\n<tr><td>S3/S4 循环</td><td>睡眠/休眠唤醒循环测试</td><td>抓休眠唤醒类兼容问题</td></tr>\n<tr><td>Reboot 循环</td><td>重启压力</td><td>抓开机初始化类问题</td></tr></table>\n<h5>3. 什么时候用什么</h5>\n<ul><li>快速内存筛查 → memtester（几十分钟到几小时）；</li>\n<li>性能基线 → Stream（读/写/复制三向量）；</li>\n<li>整机稳定性 → LTP 长测（过夜/24h+）；</li>\n<li>ACPI 类问题 → S3/S4/Reboot 循环（几十次循环找偶发）；</li>\n<li>结合：内存专项 memtester + 系统级 LTP + 电源状态循环。</li></ul>\n<h5>4. 信创平台的常见坑</h5>\n<ul><li>MemTest86 在部分国产平台 UEFI 兼容性差 → 用 memtester 替代；</li>\n<li>CPU 平台差异导致 JEDEC 频率支持不同（需查平台规格书）；</li>\n<li>国产 OS 驱动对内存参数展现有限 → 用命令行工具取数；</li>\n<li>工具要 source 编译或找发行包（部分工具无现成包）——提前准备。</li></ul>\n<h5>5. 排查流程参考</h5>\n<ol><li>确认平台：CPU 型号/OS 版本/BIOS（国产平台型号要写全）；</li>\n<li>系统级先测：LTP 或整体稳定性跑起来；</li>\n<li>内存专项：memtester 指定内存跑（memtester 1G 8 等）；</li>\n<li>状态循环：S3/S4/Reboot 各几十次，找偶发；</li>\n<li>对比：换内存/换槽/换平台对照，锁定边界。</li></ol>\n<div class=\"tip\">💡 信创平台口诀：“工具换思路（memtester/Stream/LTP）、平台看规格（国产CPU/OS）、偶发抓循环（S3/S4/重启）”——三大件到位，信创客诉不再发怵。</div>"}], "out": "测试规范速查表（判定标准高亮）"}, {"id": "d19", "title": "万用表/示波器测供电与通路", "date": "Day 19 · 周四", "dot": "4", "tasks": ["学习万用表：电压档测金手指供电——DDR4 VDD=1.2V；DDR5 VDD/VDDQ=1.1V、VPP=1.8V（对照测量）", "学习通断档测金手指到测试点通路（找虚焊/断路）", "认识简易示波器：测供电纹波、关键信号有无（入门级）", "实操：在报废条上练习测电压点，记录读数"], "tools": "万用表、简易示波器、ATE 工具说明", "resources": [{"type": "vid", "url": "https://www.bilibili.com/video/BV11N4y1679u", "label": "▶ 万用表使用方法一分钟学会（电工plc教学-老帝 · 90.2万播放）"}, {"type": "vid", "url": "https://www.bilibili.com/video/BV1HJ4m1J7Vy", "label": "▶ 万用表使用入门到精通（工控圈 · 28.4万播放）"}], "lectures": [{"title": "万用表 / 简易示波器测供电与通路", "html": "<h5>1. 万用表什么时候上场</h5>\n<p>软件排障（信息收集/交叉替换/MT86）走完后，仍指向电气层问题时才用万用表测供电与通路。它不是日常第一工具，但<b>“测供电能直接区分供电问题 vs 颗粒问题”</b>——一句话就能定位方向，节省大量时间。</p>\n<h5>2. 测电压（Finger 供电脚）</h5>\n<ul><li>档位：DC V（直流电压档）；</li>\n<li>测量：红笔接金手指供电脚（对照规格书/Datasheet 找位置），黑笔接地/金属支架；</li>\n<li>参考值：<b>DDR4 VDD=1.2V；DDR5 VDD/VDDQ=1.1V、VPP=1.8V</b>；</li>\n<li>读数偏离 → 供电问题（PMIC/主板/Bus 脱落）；</li>\n<li>注意：探金手指时别短路相邻脚，断电插拔。</li></ul>\n<h5>3. 测通路（通断档，找虚焊/断路）</h5>\n<ul><li>档位：蜂鸣档（通断档）；</li>\n<li>测量：金手指到测试点/焊点之间的导通性（找虚焊/断路）；</li>\n<li>正常：导通滴声清晰；异常：无声或时通时断；</li>\n<li>配合：颗粒焊球到金手指的通路（怀疑虚焊时逐段测）。</li></ul>\n<h5>4. 测短路（常见故障快速筛查）</h5>\n<ul><li>VDD 供电脚对地阻值：正常几百 Ω 以上（不同平台有差异），接近 0 说明有短路（颗粒/电容击穿）；</li>\n<li>金手指对地通断：异常说明内部短路。</li></ul>\n<h5>5. 会用才不伤设备</h5>\n<ul><li>先断电再测量，带电测会碰出火花；</li>\n<li>探笔尖细、手要稳，别戳到邻近脚；</li>\n<li>读数异常先复查接线，别急着下结论充电坏。</li></ul>\n<div class=\"tip\">💡 万用表三板斧：测电压（供电正常吗）→ 测通路（断了吗）→ 测短路（烧了吗）。三问三答，电气层方向就清楚了。</div><h5>6. 简易示波器（便携/入门级）够用吗</h5><p>FAE 现场排查不一定要高级示波器：<b>入门级/便携示波器（如 50-100MHz）</b>能看供电波形、纹波、信号基本形态就够。关键不是仪器多贵，而是<b>会不会设触发、会不会读 Vpp/频率、会不会存波形</b>。等你要看高速 DDR 数据总线时，才需要高速示波器+解码器（通常借研发的）。</p>"}], "out": "万用表测量记录表（点位/档位/读数）"}, {"id": "d20", "title": "完整测试闭环 + 阶段小测", "date": "Day 20 · 周五", "dot": "5", "tasks": ["独立完成一轮\"完整测试\"：装条→MT86→BurnInTest短跑→判定", "输出一份测试记录：目的/环境/数据/结论（PASS/FAIL+依据）", "完成 P1 阶段小测（原理+结构+平台+测试四块）", "完成《12周计划》W4 验收点打勾 + P1 阶段总结复盘"], "tools": "测试平台、测试规范、阶段测试卷", "resources": [], "lectures": [{"title": "完整测试闭环：从装条到结论的一次演练", "html": "<h5>1. 完整测试闭环是什么</h5>\n<p>从装条到结论的一次完整演练：<b>装条 → 识别 → 基础测试 → 压力 → 温度 → 判定 → 报告</b>。它把 P2 学到的零散技能串成一条线，是独立接单前的一次“全流程彩排”。</p>\n<h5>2. 七步闭环（每一步都要留下产出）</h5>\n<ol><li><b>装条</b>：正确安装（卡扣到位/防呆方向），拍照；</li>\n<li><b>识别</b>：BIOS/CPU-Z 确认容量/频率/时序（和标称对比）；</li>\n<li><b>基础测试</b>：MT86 1Pass（确认硬件无坏点）；</li>\n<li><b>压力测试</b>：BurnInTest 8h + 内存≥90%（长稳）；</li>\n<li><b>温度监控</b>：HWiNFO 记录 DIMM 温度全程（是否超限）；</li>\n<li><b>判定</b>：按判据总结（0 Error = 硬件正常；温度 OK = 环境正常）；</li>\n<li><b>报告</b>：一页纸：环境/步骤/结果/结论/建议。</li></ol>\n<h5>3. 每一步的判据（没有判据的测试是空转）</h5>\n<table><tr><th>步骤</th><th>判据</th></tr>\n<tr><td>识别</td><td>识别容量=标称，频率=预期（未开 XMP 按 JEDEC 属正常）</td></tr>\n<tr><td>基础测试</td><td>MT86 1Pass 0 Error</td></tr>\n<tr><td>压力</td><td>BurnIn 8h 0 Error（中途无蓝屏/死机）</td></tr>\n<tr><td>温度</td><td>DIMM 温度全程 ≤85℃（接触 Datasheet 界限）</td></tr>\n<tr><td>判定</td><td>全部通过 = PASS；任一项失败 = FAIL + 定位</td></tr></table>\n<h5>4. 闭环的意义（考核和实操重叠）</h5>\n<ul><li>对考核：完整闭环报告 = 硬证据，“会测”和“会交付”是两回事；</li>\n<li>对客诉：以后客户抱怨“测过没问题”，你能拿标准闭环流程答复；</li>\n<li>对新人：作为模板，让后来者照做。</li></ul>\n<h5>5. 常见错误</h5>\n<ul><li>识别完就急着测（没先确认识别对不对，测也白测）；</li>\n<li>压力时间不够（30 分钟说稳定）；</li>\n<li>不记录温度（高温降频导致偶发错，但你没记录就没证据）。</li></ul>\n<div class=\"tip\">💡 完整闭环一次做下来，你就拥有了“独立判断一条内存有没有问题”的完整武器库——这是上岗验收的核心题。</div>"}, {"title": "测试记录/测试报告怎么写", "html": "<h5>1. 测试记录 vs 测试报告（先分清）</h5>\n<p><b>测试记录</b> = 原始数据（时间/环境/步骤/结果），是过程存档；<b>测试报告</b> = 提炼后的结论（目的/方法/结果/判定），是交付物。报告是记录的提炼版，但报告里每条结论都能在记录里找到原档。</p>\n<h5>2. 一份合格测试记录的最低要求</h5>\n<ul><li>环境：日期/平台/BIOS/内存型号/温度/工具版本；</li>\n<li>步骤：测了什么工具、什么参数、跑多久；</li>\n<li>结果：Pass/Fail + 关键截图 + 日志路径；</li>\n<li>异常：中间发生了什么（蓝屏时间点/错误数/温度峰值）；</li>\n<li>签名：测试人 + 日期（可追溯为谁测的）。</li></ul>\n<h5>3. 测试报告结构（一页纸原则）</h5>\n<ol><li><b>测试目的</b>（为什么测——对应哪个客诉/需求）；</li>\n<li><b>测试环境</b>（平台矩阵 + 工具版本）；</li>\n<li><b>测试项与方法</b>（每项：工具/参数/时长/判据）；</li>\n<li><b>结果汇总</b>（表格：项/结果/备注）；</li>\n<li><b>结论与建议</b>（通过/不通过 + 下一步）。</li></ol>\n<h5>4. 判据的重要性（没有判据的测试是白测）</h5>\n<p>测试前写清：什么算 PASS？（MT86 0 Error？BurnIn 8h 无错？温度 ≤85℃？）没有判据，结果出来无法下结论，返工更伤。判据来自测试规范、规格书或与主管约定。</p>\n<div class=\"tip\">💡 测试记录是“做过”，测试报告是“会做”——记录完整证明你干了活，报告清晰证明你懂活。客户/领导要的是后者，但离开前者后者的结论站不住。</div><h5>6. 记录模板（可直接复制用）</h5><pre>测试记录\n日期/测试人/平台/BIOS/OS：\n工具与版本：\n测试项/参数/时长：\n结果：\n异常记录（时间点/数据/现象）：\n判定（PASS/FAIL + 依据）：</pre><p>把这份模板存成表格，每次测试直接填表——<b>30 秒的记录，顶 3 小时的回忆</b>。</p><div class=\"warn\">⚠️ 判据不确定时必须问：遇到“这个算 PASS 还是 FAIL”的分岔，先查规范，规范没写就问主管/测试负责人，并在记录里标注“判据来源：XX”。自己拍板定判据，一旦方向错，整个测试白做还误导后续。</div>"}], "out": "完整测试报告 1 份 + P1 阶段总结"}]}, {"id": "w5", "badge": "W5", "title": "故障场景拆解·硬件类：十大TOP客诉 + 根因映射", "sub": "阶段 P2 · 从\"认识内存\"到\"会拆故障\"", "accept": "能对每个故障现象列出 ≥4 条候选根因并排序。", "tools": "客户案例库、现场问题分析报告模板", "phase": "P2", "weekend": "周末加油站：把映射表打印贴工位；挑 1 个真实案例从\"现象\"反推\"根因验证链\"；预习 W6 排查流程。 可选：学习\"最小系统法\"排障视频", "days": [{"id": "d21", "title": "故障场景总览 + 案例库学习", "date": "Day 21 · 周一", "dot": "1", "tasks": ["通读客户案例库中 10 个真实案例，建立\"现象→根因\"直觉", "学习《现场问题分析报告模板》结构与字段", "整理十大TOP客诉清单：不识别/容量错、频率不达标、蓝屏死机、黑屏、过热、物理损坏等", "建立个人《故障-根因映射表》Excel 骨架（现象/根因/验证方法/案例号）"], "tools": "客户案例库、现场问题分析报告模板", "resources": [{"type": "vid", "url": "https://www.bilibili.com/video/BV1mp421m7aV", "label": "▶ 风扇正常转但黑屏无信号·解决（国丰装机 · 240.4万播放）"}, {"type": "vid", "url": "https://www.bilibili.com/video/BV1qV411S7g9", "label": "▶ 黑屏/蓝屏/闪退最全解决办法（大明湖畔千百万 · 7.0万播放）"}, {"type": "off", "url": "https://learn.microsoft.com/en-us/windows-hardware/drivers/debugger/bug-check-code-reference2", "label": "📄 微软蓝屏代码官方文档"}], "lectures": [{"title": "TOP 故障现象 → 候选根因 + 验证方法", "html": "<h5>1. TOP 故障现象清单（先背目录再背细节）</h5>\n<p>FAE 的“病例库”从十大高频现象开始：<b>无法开机/蓝屏/容量错/性能差/死机重启/不识别/混插兼容/高温/报错/NTF</b>。每个现象 → 候选根因 ≥4 条 + 验证方法——这是排查的“菜单”，客户报任何现象，你两秒内能定位到菜单哪一行。</p>\n<h5>2. 十大现象 × 候选根因（速查骨架）</h5>\n<table><tr><th>现象</th><th>候选根因（排序）</th><th>首选验证</th></tr>\n<tr><td>无法开机/黑屏</td><td>接触→混插→电源→主板</td><td>单条A2+清CMOS</td></tr>\n<tr><td>蓝屏</td><td>驱动↔内存→超频→温度</td><td>dump+MT86</td></tr>\n<tr><td>容量错</td><td>接触→SPD→混插→系统</td><td>BIOS vs 系统识别</td></tr>\n<tr><td>性能差</td><td>XMP未开→Gear→降频→混插</td><td>CPU-Z 频率</td></tr>\n<tr><td>死机重启</td><td>温度→供电→颗粒→驱动</td><td>HWiNFO+长测</td></tr>\n<tr><td>不识别</td><td>接触→SPD→槽→主板</td><td>单条逐槽测</td></tr>\n<tr><td>混插兼容</td><td>频率/时序/颗粒差异</td><td>单条各测 vs 混测</td></tr>\n<tr><td>高温</td><td>散热→TS→负载→降频</td><td>HWiNFO 温度曲线</td></tr>\n<tr><td>报错</td><td>工具/设置→颗粒→兼容</td><td>复现+判据核对</td></tr>\n<tr><td>NTF</td><td>环境→偶发→软件→批次</td><td>五板斧</td></tr></table>\n<h5>3. 怎么“用”这张表（不是背，是查）</h5>\n<ul><li>客户报现象 → 定位行 → 按排序查根因（先高概率/便宜项）；</li>\n<li>每行是“假设列表”：验证一个排除一个，收敛到结论；</li>\n<li>真实案例回填：哪条实际命中、漏了哪条 — 表持续更新；</li>\n<li>映射表与路径图配合：表给“可能”，图给“怎么走”。</li></ul>\n<h5>4. 常见错误</h5>\n<ul><li>凭感觉跳序（直接换条，跳过检查接触）；</li>\n<li>根因没排序（列 5 条不分先后，排查效率低）；</li>\n<li>验证方法缺失（列了根因查不了）。</li></ul>\n<h5>5. 考核/面试用法</h5>\n<p>考官随便抛一个现象（如“客户说频率只有 2400”），你能：<b>①定位菜单行 ②说出 3-4 条排序根因 ③给出验证方法</b>——这就是“会排查”的现场证明。</p>\n<div class=\"tip\">💡 十大现象映射表 = FAE 的“记忆宫殿”：先有目录，再往里面填案例细节。目录不全，经验再多也调不出来。</div>"}, {"title": "故障-根因映射表：怎么建、怎么用", "html": "<h5>1. 故障-根因映射表是什么</h5>\n<p>把“客户现象”与“可能根因”的对应关系整理成表：<b>现象 → 候选根因（≥4 条）→ 排序逻辑 → 验证方法</b>。它是排查路径图的“配料表”——路径图告诉你怎么走，映射表告诉你每个路口有什么可能。</p>\n<h5>2. 为什么能排序（排序逻辑是灵魂）</h5>\n<p>不是“列 5 条就完”，而是<b>说出为什么先查 A 再查 B</b>：</p>\n<ul><li>先查概率最高的（接触不良 > 颗粒坏）；</li>\n<li>先查成本最低的（软件设置 > 换件）；</li>\n<li>先查影响面的（环境/批次 > 单条）；</li>\n<li>方法上“先排除后确认”：先做便宜的排除，再收敛到贵/慢的确认。</li></ul>\n<h5>3. 映射表模板（随手可建）</h5>\n<pre>\n现象：蓝屏 0x1A（开机/游戏时随机）\n候选根因（排序）：\n  1. 时序过紧/手动超频不稳 → 恢复默认/XMP 对比\n  2. 颗粒体质临界 → MT86 长测 + 降频对比\n  3. 接触不良 → 重插/换槽\n  4. 电压/供电 → 万用表测 VDD\n  5. 驱动冲突 → dump 分析 + 更新驱动\n边界：验证完前几条再谈换条\n</pre>\n<h5>4. 映射表的进化（V1 → V2 → 手册）</h5>\n<ul><li>V1：学习阶段照抄 + 自己补充；</li>\n<li>V2：真实客诉回填（哪些根因实际命中、漏了哪些）；</li>\n<li>手册版：沉淀为团队排查手册的章节（“蓝屏→五查”）；</li>\n<li>考核：能现场对任意现象列出排序的根因 + 验证方法。</li></ul>\n<h5>5. 使用纪律</h5>\n<ul><li>不跳顺序：按排序查，别凭感觉跳（跳=可能遗漏高概率项）；</li>\n<li>每个根因必须有验证方法（列了查不了=废话）；</li>\n<li>结了案回填：真实根因打钩，映射表持续更新。</li></ul>\n<div class=\"tip\">💡 映射表是 FAE 的“答题卡”：客户报现象你秒出根因排序和验证法——这就是专业度，也是考核拿分点。</div><h5>6. 映射表与团队协作</h5><ul><li>把个人映射表升级为团队版：统一十大现象的根因排序；</li><li>团队案例回填：谁遇到新根因就补一行（共享知识）；</li><li>新人培训直接用团队映射表当教材；</li><li>评审/答辩时：能展示映射表 = 展示你的方法论体系。</li></ul>"}], "out": "故障-根因映射表 V0（框架+初填）"}, {"id": "d22", "title": "现象①：不开机/黑屏", "date": "Day 22 · 周二", "dot": "2", "tasks": ["列出不开机/黑屏 ≥4 条候选根因：接触不良、内存不兼容、插错槽、颗粒损坏、主板/CPU损坏、BIOS损坏", "学习每条的验证方法：重新插拔/换槽/最小化/交叉替换", "从案例库找 2 个\"黑屏\"案例跟踪根因结论", "更新映射表（排序写出最可能→最不可能）"], "tools": "案例库、映射表", "resources": [{"type": "vid", "url": "https://www.bilibili.com/video/BV1mp421m7aV", "label": "▶ 风扇正常转但黑屏无信号·解决（国丰装机 · 240.4万播放）"}, {"type": "vid", "url": "https://www.bilibili.com/video/BV1qV411S7g9", "label": "▶ 黑屏/蓝屏/闪退最全解决办法（大明湖畔千百万 · 7.0万播放）"}, {"type": "off", "url": "https://learn.microsoft.com/en-us/windows-hardware/drivers/debugger/bug-check-code-reference2", "label": "📄 微软蓝屏代码官方文档"}], "lectures": [{"title": "TOP 故障现象 → 候选根因 + 验证方法", "html": "<h5>1. TOP 故障现象清单（先背目录再背细节）</h5>\n<p>FAE 的“病例库”从十大高频现象开始：<b>无法开机/蓝屏/容量错/性能差/死机重启/不识别/混插兼容/高温/报错/NTF</b>。每个现象 → 候选根因 ≥4 条 + 验证方法——这是排查的“菜单”，客户报任何现象，你两秒内能定位到菜单哪一行。</p>\n<h5>2. 十大现象 × 候选根因（速查骨架）</h5>\n<table><tr><th>现象</th><th>候选根因（排序）</th><th>首选验证</th></tr>\n<tr><td>无法开机/黑屏</td><td>接触→混插→电源→主板</td><td>单条A2+清CMOS</td></tr>\n<tr><td>蓝屏</td><td>驱动↔内存→超频→温度</td><td>dump+MT86</td></tr>\n<tr><td>容量错</td><td>接触→SPD→混插→系统</td><td>BIOS vs 系统识别</td></tr>\n<tr><td>性能差</td><td>XMP未开→Gear→降频→混插</td><td>CPU-Z 频率</td></tr>\n<tr><td>死机重启</td><td>温度→供电→颗粒→驱动</td><td>HWiNFO+长测</td></tr>\n<tr><td>不识别</td><td>接触→SPD→槽→主板</td><td>单条逐槽测</td></tr>\n<tr><td>混插兼容</td><td>频率/时序/颗粒差异</td><td>单条各测 vs 混测</td></tr>\n<tr><td>高温</td><td>散热→TS→负载→降频</td><td>HWiNFO 温度曲线</td></tr>\n<tr><td>报错</td><td>工具/设置→颗粒→兼容</td><td>复现+判据核对</td></tr>\n<tr><td>NTF</td><td>环境→偶发→软件→批次</td><td>五板斧</td></tr></table>\n<h5>3. 怎么“用”这张表（不是背，是查）</h5>\n<ul><li>客户报现象 → 定位行 → 按排序查根因（先高概率/便宜项）；</li>\n<li>每行是“假设列表”：验证一个排除一个，收敛到结论；</li>\n<li>真实案例回填：哪条实际命中、漏了哪条 — 表持续更新；</li>\n<li>映射表与路径图配合：表给“可能”，图给“怎么走”。</li></ul>\n<h5>4. 常见错误</h5>\n<ul><li>凭感觉跳序（直接换条，跳过检查接触）；</li>\n<li>根因没排序（列 5 条不分先后，排查效率低）；</li>\n<li>验证方法缺失（列了根因查不了）。</li></ul>\n<h5>5. 考核/面试用法</h5>\n<p>考官随便抛一个现象（如“客户说频率只有 2400”），你能：<b>①定位菜单行 ②说出 3-4 条排序根因 ③给出验证方法</b>——这就是“会排查”的现场证明。</p>\n<div class=\"tip\">💡 十大现象映射表 = FAE 的“记忆宫殿”：先有目录，再往里面填案例细节。目录不全，经验再多也调不出来。</div>"}, {"title": "不开机/黑屏深度排查", "html": "<h5>1. 现象描述要点（先分清三种\"不开机\"）</h5>\n<p>客户说\"不开机\"信息不够——是<b>①完全无反应（风扇都不转）？②风扇转但黑屏（无 POST 画面）？③能进系统但屏幕黑？</b>三种情况方向完全不同：无反应先查电源/主板，风扇转黑屏多查内存/显卡，能进系统黑屏多查驱动/显示器。</p>\n<h5>2. 候选根因（按概率排序）</h5>\n<ol><li><b>内存接触不良/未插好</b>：卡扣没扣、插入不到位、金手指氧化——最常见；</li>\n<li><b>内存不兼容/损坏</b>：换单条/换槽可排除；</li>\n<li><b>插错插槽/单通道要求</b>：某些板必须插 A2 才能点；</li>\n<li><b>主板/CPU 故障</b>：内存完好但 CPU 座/内存通道坏；</li>\n<li><b>电源不足/损坏</b>：开机瞬间掉电；</li>\n<li><b>BIOS 状态异常</b>：清 CMOS 后恢复。</li></ol>\n<h5>3. Debug 灯与蜂鸣代码（内存问题的独特提示）</h5>\n<table><tr><th>提示</th><th>含义</th><th>动作</th></tr>\n<tr><td>Debug 灯停在 DRAM</td><td>内存初始化失败</td><td>重插/换槽/单条测试</td></tr>\n<tr><td>规律长鸣（持续 Beep）</td><td>内存错误（AMI/Award 常见）</td><td>内存相关优先排查</td></tr>\n<tr><td>短鸣 1 声</td><td>POST 正常</td><td>问题在显示/外设</td></tr>\n<tr><td>Debug 灯停在 CPU</td><td>CPU/供电问题</td><td>别在内存上耗时间</td></tr></table>\n<h5>4. 排查路径（快速版 + 完整版）</h5>\n<p><b>快速版（客户通话 5 分钟）</b>：①查 Debug 灯/蜂鸣 → ②单条内存 + A2 槽 + 清 BIOS → ③换槽换条 → ④最小系统。</p>\n<p><b>完整版（现场/返修）</b>：①指示灯/代码 → ②外观金手指 → ③单条 A2 清 CMOS → ④拔光外设备件逐个回装 → ⑤换内存/换槽/换平台交叉 → ⑥万用表测供电（VDD 1.1/1.2V，DDR5 VPP 1.8V）→ ⑦BIOS 更新。</p>\n<h5>5. 与\"内存损坏\"的区别（别误判）</h5>\n<p>黑屏 ≠ 内存坏：<b>只有报错代码/灯指向内存</b>才算。Debug 灯停在 DRAM 且规律长鸣 → 内存通道问题优先；停在 VGA → 显卡；停在 BOOT → 硬盘/引导。查错方向浪费的是客户时间，更伤信任。</p>\n<h5>6. 客户沟通话术</h5>\n<div class=\"warn\">⚠️ \"请先试单条内存插在从 CPU 往右数第二个槽（A2），其他根全部拔掉，看能否点亮——这样能快速判断是不是多根混插/接触问题。顺便拍一下主板上 Debug 灯或蜂鸣情况。\"</div>\n<div class=\"tip\">💡 记忆锚点：\"黑屏先分三种，再查灯，再单条 A2\"——三步走完，80% 的接触类问题已经定位。</div>"}, {"title": "案例库：让每一单客诉都变成资产", "html": "<h5>1. 案例库是什么（FAE 最值钱的个人资产）</h5>\n<p>案例库 = 把每一单客诉的\"现象/根因/对策/验证\"沉淀成可检索的记录。它是 FAE 最值钱的个人资产：<b>案例越多，排查越快，答辩越有底气</b>。面试/晋升时，「你处理过哪些案例、怎么处理的」比任何证书都有说服力。</p>\n<h5>2. 每例 <200 字的推荐格式（精简到可复用）</h5>\n<pre>\n案例编号：FAE-2026-XXX\n现象：一句话（客户视角）\n平台：主板/CPU/OS/内存型号\n根因：一句话（可验证）\n证据：日志/截图路径\n对策：临时 + 永久\n状态：已闭环/复核中\n</pre>\n<h5>3. 什么案例值得记（不是所有都记）</h5>\n<ul><li>第一次遇到的故障类型（新增认知）；</li>\n<li>排查过程走弯路的（<b>教训最值钱</b>——把\"当时差点往错误方向走\"写进去）；</li>\n<li>证据链完整、能当培训材料的（可分享给新人）；</li>\n<li>客户高频问题（同问必记——直接进 FAQ）。</li></ul>\n<h5>4. 归档节奏（别攒，顺手就记）</h5>\n<ul><li>客诉闭环当天顺手记一例（30 秒的事，趁热写细节才清楚）；</li>\n<li>月底统一补标签和索引（现象/平台/方法三类标签）；</li>\n<li>目标：<b>12 周 ≥10 例，一年 ≥30 例</b>——数字不到就说明你复盘不够；</li>\n<li>定期回访：哪些案例被反复问到？说明 FAQ 没覆盖；哪些过时了？更新或下架。</li></ul>\n<div class=\"tip\">💡 考核要求\"建立案例库 ≥10 例\"——现在每天闭环一单就入库，到 W12 自然达标。写案例时问自己：\"如果我失忆了，靠这条能恢复这个经验吗？\"</div><h5>5. 案例库的进阶用法（从记录到武器库）</h5><ul><li><b>检索标签体系</b>：现象关键词 + 平台 + 内存型号 + 方法——3 个月后还能搜到才是好归档；</li><li><b>案例反哺</b>：同类型案例 ≥3 个 → 提炼成 FAQ/排查手册章节；</li><li><b>年度盘点</b>：年底挑 TOP 案例做内部分享/晋升素材；</li><li><b>新人培训</b>：给新人读 3 个案例再讲出来，比讲 3 小时 PPT 有效。</li></ul>"}], "out": "黑屏根因清单（≥4条+验证方法+排序）"}, {"id": "d23", "title": "现象②③：不识别/容量错 + 频率不达标", "date": "Day 23 · 周三", "dot": "3", "tasks": ["不识别/容量错候选根因：SPD损坏、颗粒坏、混插冲突、32位系统限制、主板内存通道故障、接触不良", "频率不达标候选根因：未开XMP/EXPO、IMC体质、混插降频、散热、BIOS旧版、颗粒等级", "学习判断\"容量错\"的陷阱：系统识别 vs BIOS识别 vs 插槽限制", "更新映射表（这两个现象各≥4条）"], "tools": "案例库、CPU-Z、BIOS设置知识", "resources": [{"type": "vid", "url": "https://www.bilibili.com/video/BV1mp421m7aV", "label": "▶ 风扇正常转但黑屏无信号·解决（国丰装机 · 240.4万播放）"}, {"type": "vid", "url": "https://www.bilibili.com/video/BV1qV411S7g9", "label": "▶ 黑屏/蓝屏/闪退最全解决办法（大明湖畔千百万 · 7.0万播放）"}, {"type": "off", "url": "https://learn.microsoft.com/en-us/windows-hardware/drivers/debugger/bug-check-code-reference2", "label": "📄 微软蓝屏代码官方文档"}], "lectures": [{"title": "TOP 故障现象 → 候选根因 + 验证方法", "html": "<h5>1. TOP 故障现象清单（先背目录再背细节）</h5>\n<p>FAE 的“病例库”从十大高频现象开始：<b>无法开机/蓝屏/容量错/性能差/死机重启/不识别/混插兼容/高温/报错/NTF</b>。每个现象 → 候选根因 ≥4 条 + 验证方法——这是排查的“菜单”，客户报任何现象，你两秒内能定位到菜单哪一行。</p>\n<h5>2. 十大现象 × 候选根因（速查骨架）</h5>\n<table><tr><th>现象</th><th>候选根因（排序）</th><th>首选验证</th></tr>\n<tr><td>无法开机/黑屏</td><td>接触→混插→电源→主板</td><td>单条A2+清CMOS</td></tr>\n<tr><td>蓝屏</td><td>驱动↔内存→超频→温度</td><td>dump+MT86</td></tr>\n<tr><td>容量错</td><td>接触→SPD→混插→系统</td><td>BIOS vs 系统识别</td></tr>\n<tr><td>性能差</td><td>XMP未开→Gear→降频→混插</td><td>CPU-Z 频率</td></tr>\n<tr><td>死机重启</td><td>温度→供电→颗粒→驱动</td><td>HWiNFO+长测</td></tr>\n<tr><td>不识别</td><td>接触→SPD→槽→主板</td><td>单条逐槽测</td></tr>\n<tr><td>混插兼容</td><td>频率/时序/颗粒差异</td><td>单条各测 vs 混测</td></tr>\n<tr><td>高温</td><td>散热→TS→负载→降频</td><td>HWiNFO 温度曲线</td></tr>\n<tr><td>报错</td><td>工具/设置→颗粒→兼容</td><td>复现+判据核对</td></tr>\n<tr><td>NTF</td><td>环境→偶发→软件→批次</td><td>五板斧</td></tr></table>\n<h5>3. 怎么“用”这张表（不是背，是查）</h5>\n<ul><li>客户报现象 → 定位行 → 按排序查根因（先高概率/便宜项）；</li>\n<li>每行是“假设列表”：验证一个排除一个，收敛到结论；</li>\n<li>真实案例回填：哪条实际命中、漏了哪条 — 表持续更新；</li>\n<li>映射表与路径图配合：表给“可能”，图给“怎么走”。</li></ul>\n<h5>4. 常见错误</h5>\n<ul><li>凭感觉跳序（直接换条，跳过检查接触）；</li>\n<li>根因没排序（列 5 条不分先后，排查效率低）；</li>\n<li>验证方法缺失（列了根因查不了）。</li></ul>\n<h5>5. 考核/面试用法</h5>\n<p>考官随便抛一个现象（如“客户说频率只有 2400”），你能：<b>①定位菜单行 ②说出 3-4 条排序根因 ③给出验证方法</b>——这就是“会排查”的现场证明。</p>\n<div class=\"tip\">💡 十大现象映射表 = FAE 的“记忆宫殿”：先有目录，再往里面填案例细节。目录不全，经验再多也调不出来。</div>"}, {"title": "频率不达标深度排查", "html": "<h5>1. 先定义\"达标\"（防止鸡同鸭讲）</h5>\n<p>客户说\"内存只有 2400\"——先问清楚：<b>标称多少？期望多少？怎么看出来的？（BIOS / CPU-Z / 任务管理器）</b>任务管理器/CPU-Z 显示的是当前实际频率，XMP 未开时按 JEDEC 保守档（如 DDR5-4800 / DDR4-2400）运行是<b>正常</b>的，不是故障。</p>\n<h5>2. 候选根因（按概率排序）</h5>\n<ol><li><b>未开启 XMP/EXPO</b>：频率停留在 JEDEC 档——占 80%；</li>\n<li><b>平台不支持/IMC 体质</b>：CPU 内存控制器上限不足；</li>\n<li><b>混插降频</b>：两根不同频率/颗粒的条子按慢的跑；</li>\n<li><b>散热不足降频</b>：温度过高自动降频；</li>\n<li><b>BIOS 设置/版本</b>：Gear 模式未选对、旧 BIOS 限制；</li>\n<li><b>插槽不对</b>：未插最优通道（A2+B2）。</li></ol>\n<h5>3. 排查动作（按顺序）</h5>\n<ul><li>看 CPU-Z <b>Memory 页</b>（当前频率/时序）vs <b>SPD 页</b>（XMP 档位——确认条子标称）；</li>\n<li>先确认 XMP/EXPO 是否已开启（BIOS 里 Memory Profile）；</li>\n<li>单条开 XMP 测试：排除混插干扰；</li>\n<li><b>频率换算</b>：实际频率 = 内存时钟 ×2（DDR 双沿），CPU-Z 显示 3000 = DDR4-6000？不——CPU-Z 的 DRAM Frequency 是时钟频率，DDR4-3200 显示 1600MHz，别算错；</li>\n<li>更新 BIOS 到支持该内存版本（早期 BIOS 对高频率支持不全）；</li>\n<li>手动放宽时序（如 CL 降档）或加内存电压试探 IMC 边界，记录结果。</li></ul>\n<h5>4. 判定标准</h5>\n<p><b>XMP 开启后跑到标称频率且稳定（压力测试过）= 达标</b>；跑不到但 JEDEC 默认稳定 = <b>平台体质/兼容问题</b>——要给客户解释\"内存没问题，是平台上限\"，并给出可执行建议（换插槽/升级 BIOS/保守频率）。</p>\n<h5>5. 沟通话术（高频场景）</h5>\n<div class=\"tip\">💡 \"别人买同款能上 6000\"——回复：\"每颗 CPU 的 IMC 体质不同，6000 是标称上限不是保证值。我先帮您确认 BIOS 设置和插槽，再试手动微调，尽量贴近标称。\"</div>\n<p>记住：<b>频率类客诉 80% 是设置问题，不是质量问题</b>——先教客户开 XMP，再谈排查。</p>"}, {"title": "不识别/容量错深度排查", "html": "<h5>1. \"不识别/容量错\"的三种级别（先定位层级！）</h5>\n<ul><li><b>BIOS 都不显示该条</b>：硬件级问题（接触/颗粒/SPD/槽/通道）；</li>\n<li><b>BIOS 显示容量错误</b>：SPD 数据错/颗粒坏/插槽限制；</li>\n<li><b>系统里容量少</b>：OS 位数限制/内存保留（集显共享）/最大内存设置/内存泄漏。</li></ul>\n<p>层级定了，排查范围缩小 80%——<b>第一步永远是问\"BIOS 显示多少\"</b>，而不是直接拆机。</p>\n<h5>2. 候选根因（按概率排序）</h5>\n<ol><li><b>接触不良</b>：金手指氧化、未插到位、槽内灰尘——最常见；</li>\n<li><b>SPD 数据错误/损坏</b>：字段错、刷写失败、二手条改过标；</li>\n<li><b>颗粒损坏/虚焊</b>：容量识别失败、通道坏；</li>\n<li><b>混插兼容</b>：不同容量/频率/颗粒混插降级或识别异常；</li>\n<li><b>主板通道限制</b>：某些平台单条容量上限、插槽位要求、CPU 内存通道坏；</li>\n<li><b>系统限制</b>：32 位系统 4GB 上限、msconfig 最大内存勾选、集显共享显存。</li></ol>\n<h5>3. 排查动作（按顺序）</h5>\n<ul><li>看 BIOS 识别 vs 系统识别，先定位层级；</li>\n<li>CPU-Z SPD 页读字段（容量/频率/厂商），确认标称与实际；</li>\n<li>单条各槽位逐测（定位插槽/条子/通道问题）；</li>\n<li>更新 BIOS；清 CMOS；恢复 BIOS 默认；</li>\n<li>系统里 msconfig → 引导 → 高级选项 → 查\"最大内存\"是否被勾选；</li>\n<li>任务管理器 → 性能 → 内存 → 看\"为硬件保留\"多少（集显共享会占用）。</li></ul>\n<h5>4. 判定树</h5>\n<table><tr><th>BIOS 显示</th><th>系统显示</th><th>结论方向</th></tr>\n<tr><td>正确</td><td>偏少</td><td>系统/软件层（保留/位数/设置）</td></tr>\n<tr><td>错误</td><td>错误</td><td>硬件/SPD 层（接触/颗粒/虚焊）</td></tr>\n<tr><td>插单条正确、两条错</td><td>—</td><td>混插兼容/通道问题</td></tr>\n<tr><td>时好时坏</td><td>—</td><td>接触不良/虚焊优先</td></tr></table>\n<div class=\"tip\">💡 常见翻车案例：客户报\"16GB 只有 8GB\"——结果是集显共享显存占了一半，不是内存坏。先问\"BIOS 显示多少\"，一句话省一天。</div>"}], "out": "\"不识别/容量错/频率不达标\"根因清单"}, {"id": "d24", "title": "现象④⑤：蓝屏死机重启 + 过热报警", "date": "Day 24 · 周四", "dot": "4", "tasks": ["蓝屏死机候选根因：颗粒不稳定、时序过紧、电压不足、驱动冲突、系统损坏、过热", "过热报警候选根因：散热片未贴、风道差、颗粒自发热、超频电压高、环境温度高", "学习蓝屏代码初步认识：0x1A(MEMORY_MANAGEMENT)、0x50(PAGE_FAULT)等", "更新映射表（各≥4条）"], "tools": "案例库、事件查看器、蓝屏代码速查", "resources": [{"type": "vid", "url": "https://www.bilibili.com/video/BV19G411Y7Jx", "label": "▶ 蓝屏终止代码KERNEL_DATA_INPAGE_ERROR（电脑蓝屏_南京小吧 · 6.8万播放）"}, {"type": "vid", "url": "https://www.bilibili.com/video/BV12G411t7nf", "label": "▶ 不定时蓝屏重启·每次代码不同（其趣生活 · 1.1万播放）"}, {"type": "off", "url": "https://learn.microsoft.com/en-us/windows-hardware/drivers/debugger/bug-check-code-reference2", "label": "📄 微软蓝屏代码官方文档"}], "lectures": [{"title": "蓝屏代码：从 Code 到内存判断", "html": "<h5>1. 常见内存相关蓝屏代码（先看 Code 再动手）</h5>\n<table><tr><th>Code</th><th>名称</th><th>含义/方向</th></tr>\n<tr><td>0x1A</td><td>MEMORY_MANAGEMENT</td><td>内存管理异常，高度指向内存</td></tr>\n<tr><td>0x50</td><td>PAGE_FAULT_IN_NONPAGED_AREA</td><td>非分页区缺页，内存+驱动都要查</td></tr>\n<tr><td>0x7E/0x8E</td><td>SYSTEM_THREAD / KERNEL_MODE_EXCEPTION</td><td>多为驱动，也可由坏内存引起</td></tr>\n<tr><td>0x7A</td><td>KERNEL_DATA_INPAGE_ERROR</td><td>页面数据读入失败（内存/存储）</td></tr>\n<tr><td>0x0A</td><td>IRQL_NOT_LESS_OR_EQUAL</td><td>驱动问题为主，别急着赖内存</td></tr>\n<tr><td>0x3B</td><td>SYSTEM_SERVICE_EXCEPTION</td><td>驱动/服务异常，需看 dump 定位模块</td></tr>\n<tr><td>0xC4/0x1E</td><td>硬件相关代码</td><td>硬件错误，配合内存扫描确认</td></tr></table>\n<h5>2. 分析流程（Code → dump → 交叉验证）</h5>\n<ol><li>记录 <b>Code + 时间 + 场景</b>（游戏/待机/开机/特定软件）；</li>\n<li>启用小内存转储（Win+R → sysdm.cpl → 高级 → 启动和故障恢复 → 小内存转储 256KB）；</li>\n<li>WinDbg 打开 dump：<code>!analyze -v</code> 看 FAULTING_MODULE 定位故障模块；</li>\n<li><b>交叉验证</b>：MemTest86 全项扫描 → 0 Error 则内存嫌疑下降，重点查驱动/软件；有 Error 才指向内存；</li>\n<li>更新驱动/BIOS 复测；仍复现再深入（电压/时序/硬件替换）。</li></ol>\n<h5>3. 蓝屏反推：哪些场景更可能内存相关</h5>\n<ul><li>游戏高负载时随机蓝屏 + 内存错误 → 颗粒/时序/温度嫌疑高；</li>\n<li>待机/轻负载蓝屏 → 驱动/电源管理嫌疑高；</li>\n<li>开机即蓝屏 → 驱动冲突/硬件初始化；</li>\n<li>同一软件必现蓝屏 → 优先怀疑软件/驱动，别先赖内存。</li></ul>\n<h5>4. 客户要求快速结论时怎么说</h5>\n<p>\"蓝屏 Code 只是线索，不是判决书——我拿到 dump 分析 + 交叉跑一遍内存扫描，才能给您准确结论，预计 X 小时。\" 用纪律换取客户信任，而不是拍脑袋给答案。</p>\n<div class=\"warn\">⚠️ 铁律：蓝屏 Code 不是判决书——必须配合 dump 分析和内存扫描再下结论，这是客诉答辩的纪律，也是不背锅的护身符。</div>\n<div class=\"tip\">💡 记忆锚点：\"Code 定方向，dump 定模块，MT86 定内存\"——三步闭环，蓝屏客诉不再慌。</div>"}, {"title": "蓝屏/死机/重启深度排查", "html": "<h5>1. 收集关键信息</h5>\n<p>蓝屏不是\"现象\"而是\"结果\"。必须拿到：<b>蓝屏 Code + dump 文件 + 发生场景（游戏/待机/开机）+ 频率</b>。没有 Code 就无从下手。</p>\n<h5>2. 候选根因（按概率排序）</h5>\n<ol><li><b>内存不稳定</b>：XMP 过紧/颗粒体质差（MT86 验证）；</li>\n<li><b>驱动/系统问题</b>：显卡/芯片组驱动冲突、系统损坏（dump 分析）；</li>\n<li><b>供电不稳</b>：电源老化、主板供电不足；</li>\n<li><b>温度过高</b>：内存/CPU 过热；</li>\n<li><b>混插/接触不良</b>：多根条子时序不同步；</li>\n<li><b>超频过度</b>：CPU/内存同时超频互相干扰。</li></ol>\n<h5>3. 蓝屏 Code 速查（内存相关）</h5>\n<table><tr><th>Code</th><th>名称</th><th>方向</th></tr>\n<tr><td>0x1A</td><td>MEMORY_MANAGEMENT</td><td>高度指向内存</td></tr>\n<tr><td>0x50</td><td>PAGE_FAULT_IN_NONPAGED_AREA</td><td>内存或驱动</td></tr>\n<tr><td>0x7A</td><td>KERNEL_DATA_INPAGE_ERROR</td><td>内存或存储</td></tr>\n<tr><td>0x0A</td><td>IRQL_NOT_LESS_OR_EQUAL</td><td>驱动为主</td></tr></table>\n<h5>4. 排查流程</h5>\n<ol><li>获取 Code + dump（C:\\Windows\\Minidump）；</li>\n<li>MemTest86 基础扫描（排除硬件坏点）；</li>\n<li>关 XMP 回 JEDEC 档测试（排除超频不稳）；</li>\n<li>更新驱动/BIOS；</li>\n<li>交叉替换内存/主板/电源。</li></ol>\n<div class=\"warn\">⚠️ 不要只看 Code 就断言内存坏：0x1A 指向内存，但也可能 CPU 内存控制器问题。MT86 0 Error + 关 XMP 稳定 = 很大概率不是内存颗粒坏，而是设置/兼容问题。</div>"}], "out": "蓝屏/过热根因清单"}, {"id": "d25", "title": "现象⑥：物理损坏 + 周复盘", "date": "Day 25 · 周五", "dot": "5", "tasks": ["物理损坏候选根因：运输磕碰、插拔损坏、静电ESD、安装不当、主板卡扣问题", "学习物理损坏的判定证据：照片、外观检查、金手指痕迹", "完成映射表 V1：覆盖≥6现象 × ≥4根因，并排序", "完成《12周计划》W5 验收点打勾（导师抽问）"], "tools": "映射表V1、导师抽问清单", "resources": [], "lectures": [{"title": "物理损坏：判别与取证", "html": "<h5>1. 物理损坏是“假性不良”里最直接的一类</h5>\n<p>物理损坏 ≠ 颗粒老化/软件问题：<b>有可见证据、可拍照取证、根因明确</b>。FAE 处理物理损坏客诉的核心：<b>判别 + 取证 + 明确责任边界</b>——是运输/安装/使用导致，不是产品质量问题。</p>\n<h5>2. 常见物理损坏类型与判定</h5>\n<table><tr><th>类型</th><th>特征</th><th>判据</th></tr>\n<tr><td>颗粒崩角/裂纹</td><td>边角缺失、裂纹</td><td>放大镜可见，拍照</td></tr>\n<tr><td>金手指划伤/掉点</td><td>镀层破损、露铜</td><td>微距照片，比对</td></tr>\n<tr><td>PCB 弯曲/断裂</td><td>板弯、线路裂</td><td>对光观察，测量</td></tr>\n<tr><td>焊点脱落/虚焊加重</td><td>跌落/受力后故障</td><td>X-ray/功能表现</td></tr>\n<tr><td>烧灼痕迹</td><td>发黑/焦味/元件熔</td><td>照片 + 气味 + 供电检查</td></tr></table>\n<h5>3. 判别动作（先证据后结论）</h5>\n<ol><li>外观检查：放大镜/微距全面拍照（金手指/颗粒/PCB）；</li>\n<li>记录收货/安装/使用过程（谁装的、有无跌落/用力插拔）；</li>\n<li>功能测试：能否识别、测试报错分布（与外观异常位置关联）；</li>\n<li>对照正常件：同型号同批次外观对比；</li>\n<li>判定：可见损伤 + 损伤位置与故障关联 = 物理损坏证据充分。</li></ol>\n<h5>4. 取证标准（照片要能作为证据）</h5>\n<ul><li>微距 + 全景各一张（宏观位置 + 微观细节）；</li>\n<li>带参照物（硬币/尺子）显示尺寸；</li>\n<li>光线均匀，重点部位特写；</li>\n<li>原始文件保留（不要压缩/美颜）；</li>\n<li>照片时间戳 + 条子 SN/标签同框。</li></ul>\n<h5>5. 责任边界与沟通</h5>\n<ul><li>判定物理损坏（安装/使用/运输不当）→ 明确说明“非产品质量问题”，给证据；</li>\n<li>客户不认：给对照 + 流程（可安排返厂检测确认）；</li>\n<li>包装破损：走物流理赔（保留开箱视频/照片）；</li>\n<li>话术：“我们检测发现 X 位置有明显损伤，和故障位置吻合，建议…”。</li></ul>\n<div class=\"tip\">💡 物理损坏客诉的胜负手是“取证”：三张图（全景+特写+参照物）+ 时间线，谁看了都无话可说。证据链完整，客户也认。</div>"}], "out": "故障-根因映射表 V1 + W5周复盘"}]}, {"id": "w6", "badge": "W6", "title": "根因分层与诊断流程：排查路径图 + 交叉替换", "sub": "阶段 P2 · 形成不跳步的系统化排查能力", "accept": "对任意给定案例能画出排查路径图，不跳步。", "tools": "分析判断思路SOP、MT86、AIDA64、HWiNFO64", "phase": "P2", "weekend": "周末加油站：把排查路径图背诵成肌肉记忆；阅读 NTF 方法论背景；预习 W7 复现实验设计。 可选：看 WinDbg 蓝屏 dump 分析入门", "days": [{"id": "d26", "title": "信息收集 → 初步诊断", "date": "Day 26 · 周一", "dot": "1", "tasks": ["学习《分析判断思路SOP》第一步：信息收集（机型/平台/BIOS/内存型号/现象/概率/环境/操作）", "学习初步诊断：安装/接触/外观三步检查（金手指、插槽、卡扣）", "实操：拿一台测试机完整演练\"信息收集表\"填写", "理解\"信息不全就下结论\"是FAE第一大忌"], "tools": "分析判断思路SOP、信息收集表模板", "resources": [{"type": "vid", "url": "https://www.bilibili.com/video/BV19z4y1f7m5", "label": "▶ Outlook邮件技巧·分类管理（东方瑞通 · 1.5万播放）"}, {"type": "vid", "url": "https://www.bilibili.com/video/BV1afQoYnEvQ", "label": "▶ 客服邮件处理（邹阳FBM笔记 · 6827播放）"}], "lectures": [{"title": "信息收集模板：一次问全的 10 个字段", "html": "<h5>1. 为什么信息收集是第一步</h5>\n<p>FAE 90% 的坑来自信息不全就下结论。客户说\"内存坏了\"是<b>结果</b>，你要的是<b>过程事实</b>：什么环境、什么操作、什么现象、什么概率。信息收集的质量直接决定排查方向——收集错，后面全错。</p>\n<h5>2. 十字段模板（发给客户的填空版）</h5>\n<ol><li><b>客户/联系方式</b>：对接人 + 电话/企业微信（紧急时直接联系）；</li>\n<li><b>机型/品牌+SN</b>：整机厂牌型号 + 序列号（判批次/渠道）；</li>\n<li><b>主板型号+BIOS 版本</b>：BIOS 日期/版本号（很多问题随 BIOS 更新消失或出现）；</li>\n<li><b>CPU 型号</b>：IMC 代际差异（12 代 vs 13/14 代内存策略不同）；</li>\n<li><b>OS 版本+补丁</b>：Win10/11 大版本 + 累积更新（兼容性客诉常在这里）；</li>\n<li><b>内存型号+SN+批次+颗粒</b>：模组 PN、条码批次、颗粒厂商（同型号不同批次可能不同颗粒）；</li>\n<li><b>插槽位置/是否混插</b>：A1/A2/B1/B2 哪个槽、是否与其他品牌混用；</li>\n<li><b>现象描述+截图/视频</b>：蓝屏要 dump 文件/蓝屏照片，死机要录触发过程；</li>\n<li><b>复现概率+触发条件</b>：必现/偶发、开机/压力/冷机/热机/特定软件；</li>\n<li><b>环境+已做动作</b>：温度/供电/湿度，客户已经试过什么（换槽？单条？清CMOS？）。</li></ol>\n<h5>3. 每个字段的追问示例（拿到\"不够填\"时怎么追问）</h5>\n<ul><li>\"蓝屏\" → 追问：蓝屏代码是多少？什么时候开始？开着什么软件？截图发我；</li>\n<li>\"开不了机\" → 追问：有无报警声/指示灯？显示器有无信号？插几根条？</li>\n<li>\"偶尔死机\" → 追问：大概多久一次？重启后正常吗？是特定操作还是随机？</li>\n<li>\"性能差\" → 追问：和什么基准比？BIOS 里频率实际多少？XMP/EXPO 开了吗？</li></ul>\n<h5>4. 沟通技巧（让客户愿意配合）</h5>\n<ul><li>发<b>填空模板</b>（表格格式）比来回追问高效——客户填起来快，你也拿得全；</li>\n<li>要求<b>截图/视频而非口头描述</b>：\"蓝屏\"要有照片+dump，\"报错\"要有截图（很多问题看一眼截图就定性了）；</li>\n<li>进度<b>主动同步</b>销售/客户，避免\"失联\"猜疑；</li>\n<li>一次问全 vs 挤牙膏：宁可第一次多问几项，别\"想到哪问到哪\"——客户会觉得你没章法。</li></ul>\n<h5>5. 常见\"信息陷阱\"提醒</h5>\n<ul><li>客户说\"换了内存就好\" ≠ 旧条一定坏——可能只是旧条与平台配合问题；</li>\n<li>客户说\"两根都试过\" 要确认：是\"两根都不行\"还是\"每根单独都行、两根一起不行\"（后者是兼容性/供电问题）；</li>\n<li>BIOS 版本必问——刷了 Beta BIOS 后的\"新故障\"可能版本引入；</li>\n<li>拍照要求：金手指正反面、整条标签、插槽位、蓝屏/报错画面，缺一不可。</li></ul>\n<div class=\"tip\">💡 把十字段做成一张 Excel/表格模板存桌面，接单直接发给客户填——这是 FAE 的第一个\"趁手工具\"。</div>"}, {"title": "金手指外观检查速查", "html": "<h5>1. 初步诊断第一步：看金手指（工具：手电 + 放大镜/微距拍照）</h5>\n<p>五类高频外观问题要一眼分得清：<b>氧化、划伤、掉点/镀层破损、弯曲变形、污染（助焊剂/油污/汗渍）</b>。每条都要用微距图取证。</p>\n<h5>2. 判定参考表（对着照片分级）</h5>\n<table><tr><th>现象</th><th>可能成因</th><th>处理建议</th></tr>\n<tr><td>整排均匀发暗/发绿</td><td>存放过久、环境潮湿（硫化/氧化）</td><td>重新插拔多次（摩擦去氧化膜），多数可改善；无效则换条</td></tr>\n<tr><td>局部划伤 + 对应插槽位复现故障</td><td>插拔摩擦、插槽内有异物/毛刺</td><td>锁定该金手指与槽位，检查插槽；必要时换槽</td></tr>\n<tr><td>金面缺失/掉点（露铜）</td><td>镀金层磨穿、返工损坏</td><td>直接判定不可用，换条（镀层破损会接触电阻升高）</td></tr>\n<tr><td>边缘弯曲/变形</td><td>安装受力不均、卡扣未到位</td><td>检查卡扣与安装方向，变形严重则换条</td></tr>\n<tr><td>表面污染（助焊剂残留/油污）</td><td>制程残留、手触碰</td><td>无水酒精+无尘布轻擦（仅限轻度污染），擦后吹干再装</td></tr></table>\n<h5>3. 为什么金手指外观会引发\"奇奇怪怪\"的故障</h5>\n<p>金手指与插槽弹片靠<b>接触压力</b>导通。氧化膜/污染/划伤都会增大接触电阻：高速信号（DQ/DQS 上千兆）对接触阻抗极敏感，轻微劣化就表现为<b>偶发蓝屏、开机报警、同一条换个槽就正常</b>——这就是\"看起来像坏、换槽又好了\"的常见来源。</p>\n<h5>4. 处理边界（重要！）</h5>\n<ul><li><b>橡皮擦</b>：很多人会试，但会磨损镀金层且留屑，只适用于\"死马当活马医\"的应急，不推荐作为标准动作；</li>\n<li><b>酒精</b>：只处理油污类轻度污染，先断电再操作，擦完彻底晾干；</li>\n<li><b>严禁</b>用砂纸/利器刮金手指——直接报废。</li></ul>\n<h5>5. 和客户沟通（一句话模板）</h5>\n<p>\"请拍一张金手指的清晰照片发我们，正反两面都要\"——这是初步诊断<b>最便宜也最有效</b>的动作，很多接触类问题一眼定性，比让客户来回换货强得多。</p>\n<div class=\"tip\">💡 现场铁律：先拍照取证，再动手处理。同一根条子拔插前后的照片对比，就是最好的判定证据。</div>"}], "out": "一份完整填写的信息收集表"}, {"id": "d27", "title": "最小化 → 交叉替换", "date": "Day 27 · 周二", "dot": "2", "tasks": ["学习\"最小化系统\"：只保留 CPU+1内存+集显/最小启动，逐件加回", "学习交叉替换法：内存/主板/CPU 两两替换定位故障边界", "实操：用一台机器做\"单根内存 A/B 槽位\"交叉测试", "画出\"交叉替换判定表\"（部件A好/坏 × 部件B好/坏的组合）"], "tools": "SOP、交叉替换工具表", "resources": [], "lectures": [{"title": "最小化系统 + 交叉替换：定位故障的黄金法则", "html": "<h5>1. 最小化系统（先从最少零件开始）</h5>\n<p>最小化 = 只用最小必要硬件排除故障：<b>CPU + 1 根内存（A2 槽最优）+ 集显/最小显卡 + 电源</b>，不接硬盘/SATA/USB 外设。做法：逐步外设一件一件加回去，加到哪一步出问题，嫌疑就在哪一步。<b>一次只加一个变量</b>——这是排查纪律的核心。</p>\n<h5>2. 交叉替换法（换件定位）</h5>\n<p>当两个部件可能互相影响时（如内存 vs 主板插槽），用<b>交叉组合</b>定位：</p>\n<table><tr><th>组合</th><th>好内存+好主板</th><th>疑似坏内存+好主板</th><th>好内存+疑似坏主板</th></tr>\n<tr><td>现象</td><td>正常</td><td>出问题</td><td>出问题</td></tr>\n<tr><td>结论</td><td>基线</td><td>指向内存</td><td>指向主板</td></tr></table>\n<h5>3. 操作纪律（决定实验是否有效）</h5>\n<ul><li>每次只换一个变量（“换内存又换槽位”就没法定位）；</li>\n<li>替换用<b>已知正常件</b>（不能用“疑似坏内存”互相测）；</li>\n<li>记录每一步现象与结论，形成判定表；</li>\n<li>内存故障定位顺序：换槽 → 换条 → 换平台 → 电气测量。</li></ul>\n<h5>4. 客户现场应用（教客户做最小化）</h5>\n<p>客户报“内存坏”，不要急着说“那就换条”——先让他做最小化+交叉：单条 A2 槽能否开机？两根单独各测一次？把结果发你，你就能判断是条子、插槽还是主板。给客户可执行步骤，既快又显专业。</p>\n<h5>5. 典型应用场景</h5>\n<ul><li>开机黑屏/报警：最小化后排除外设/供电干扰；</li>\n<li>偶发重启：最小化 + 长测，看问题是否还出现；</li>\n<li>多内存不稳定：单条各测 —— 定位是哪根/混插；</li>\n<li>外人说“主板坏了”：交叉替换表一摆，数据说话。</li></ul>\n<div class=\"tip\">💡 交叉替换判定表是面试/考核常客：能画出这张表，说明你真的懂“用实验隔离变量”。这也是 FAE 区别于“换件工”的分水岭。</div>"}], "out": "交叉替换判定表（自己设计的模板）"}, {"id": "d28", "title": "BIOS 默认 → 深入分析（信号/温压/边界）", "date": "Day 28 · 周三", "dot": "3", "tasks": ["学习\"恢复BIOS默认再测\"：排除软设置干扰的正确步骤", "深入分析三件套：信号（示波器入门）、温压（HWiNFO64）、边界（超频/降频对照）", "实操：一个疑似\"频率不稳\"案例，走 BIOS默认→加压→降频全流程", "学习 AIDA64 压力测试解读传感器数据"], "tools": "BIOS、HWiNFO64、AIDA64、示波器入门", "resources": [{"type": "vid", "url": "https://www.bilibili.com/video/BV1b1BKB8EdX", "label": "▶ 保姆级XMP/EXPO开启教程（无敌电脑大王 · 2.9万播放）"}, {"type": "vid", "url": "https://www.bilibili.com/video/BV113411i7eS", "label": "▶ 简谈内存SPD、刷写XMP（吗吗哈哈 · 8625播放）"}, {"type": "off", "url": "https://en.wikipedia.org/wiki/Intel_Extreme_Memory_Profile", "label": "📄 维基百科·Intel XMP"}], "lectures": [{"title": "BIOS 内存项 + XMP/EXPO 机制", "html": "<h5>1. BIOS 内存菜单常见项</h5>\n<ul><li><b>Memory Frequency/比率</b>：手动频率或自动（Auto/By SPD）；</li>\n<li><b>XMP/EXPO Profile</b>：一键载入超频配置；</li>\n<li><b>DRAM 电压</b>：DDR5 标准 VDD/VDDQ=1.1V，XMP/EXPO 档常见 1.1~1.25V（部分高频条 1.35V+）；DDR4 XMP 常用 1.35V，加电压提高稳定性但升温；</li>\n<li><b>Gear Mode（Intel）</b>：Gear1/Gear2 选择；</li>\n<li><b>Memory Training / 重新训练</b>：开机训练记忆参数，老主板换条后建议清内存训练。</li></ul>\n<h5>2. XMP/EXPO 原理</h5>\n<p>SPD 里除了 JEDEC 标准档，还有一个（或多个）<b>超频 Profile</b>：指定了更高频率+时序+电压。BIOS 开启后按 Profile 跑，而不是按 JEDEC 保守档。</p>\n<h5>3. XMP 开启后不稳定的常见原因</h5>\n<ol><li>IMC 体质不够（CPU 不行）；</li>\n<li>电压不足（需要手动微增 VDDQ/SA）；</li>\n<li>散热不足（高温降频/不稳）；</li>\n<li>主板 BIOS 兼容性差（需更新）；</li>\n<li>混插不同频率/不同颗粒条子。</li></ol>\n<h5>4. 恢复 BIOS 默认的正确做法</h5>\n<p>进 BIOS → Load Defaults / 恢复默认设置 → 保存重启；必要时短接 CMOS 跳线或拔电池 30 秒。恢复默认后内存回到 JEDEC 档，用来排除\"超频设置导致的故障\"。</p>\n<div class=\"tip\">💡 排查客诉\"一开 XMP 就重启\"：先恢复默认确认 JEDEC 档稳定 → 再逐步开 XMP → 最后微调电压/降频定位边界。</div><h5>6. XMP/EXPO 开启后不稳定的排查顺序</h5><ol><li>恢复默认（JEDEC）对比：默认稳 = 超频相关问题，默认也不稳 = 硬件/接触问题；</li><li>确认插槽 A2+B2（双通道最优，插错影响频率与稳定性）；</li><li>更新 BIOS（新版本常改善内存兼容）；</li><li>手动微调：放宽时序一档或加电压 0.05V（记录每次变化）；</li><li>仍不稳 → 怀疑颗粒体质/散热/IMC → 按映射表深入。</li></ol><p>BIOS 内存项操作原则：<b>一次改一项、每项都记录、改完必复测</b>——这是超频排障的纪律。</p>"}, {"title": "HWiNFO64 使用详解：温压监控 + 日志", "html": "<h5>1. HWiNFO64 的定位（免费的传感器显微镜）</h5>\n<p>HWiNFO64 是免费的硬件信息与传感器监控工具（官网 hwinfo.com）。FAE 用它看<b>温度、电压、频率</b>，判断稳定性问题的环境因素——很多“偶发死机”的答案就藏在抓到的温度/电压曲线里。<b>偶发问题的破解 = 抓环境数据</b>，HWiNFO 就是抓手。</p>\n<h5>2. 关键界面（先记这三个）</h5>\n<ul><li>启动时选 <b>Sensors-only（仅传感器）</b> 模式；</li>\n<li>找 <b>DIMM/内存温度</b>：DDR5 条子通常带温度传感器（TS）；</li>\n<li>看 <b>VDDQ / VDD 电压</b>：是否稳定在标准档附近（DDR5=1.1V；DDR4 XMP=1.35V）；</li>\n<li>看 <b>CPU/主板供电温度</b>：过热会影响内存稳定性（闷箱机案例）。</li></ul>\n<h5>3. 抓日志（重要！偶发问题的破案关键）</h5>\n<ol><li>Sensors 窗口 → 工具栏点击 <b>Logging（日志）</b> 按钮；</li>\n<li>设置间隔（如 1 秒）与保存路径（CSV）；</li>\n<li>开始记录 → 去跑压力测试/复现故障场景；</li>\n<li>故障发生后停止日志 → Excel 打开 CSV 看“崩溃前温度/电压发生了什么”。</li></ol>\n<h5>4. 与故障窗口关联（NTF 场景怎么用）</h5>\n<ul><li>只抓故障后没意义：要抓<b>故障发生前后</b>的数据（先开日志再复现）；</li>\n<li>看趋势：温度爬到 95℃ 才蓝屏？电压 1.08V 瞬时跌落？——这就是线索；</li>\n<li>日志时间线对齐 dump/事件记录（几点几分崩溃，日志里那个点前后什么样）；</li>\n<li>取证：CSV + 截图存档进案例（FA 报告证据）。</li></ul>\n<h5>5. 常用判读</h5>\n<table><tr><th>指标</th><th>正常</th><th>异常提示</th></tr>\n<tr><td>DIMM 温度</td><td>&lt; 85℃</td><td>超限 → 散热/降频检查</td></tr>\n<tr><td>VDD/VDDQ</td><td>±3% 内稳定</td><td>跌落大 → 供电/PMIC 问题</td></tr>\n<tr><td>频率实时值</td><td>与设置一致</td><td>骤降 → 降频/BIOS 自动调整</td></tr></table>\n<div class=\"tip\">💡 HWiNFO 是“环境证据”制造机：会抓日志 + 会对齐时间线 + 会看趋势，你就有能力把偶发问题从“玄学”变成“数据”。</div>"}, {"title": "AIDA64 使用详解：内存压力 + 性能基准", "html": "<h5>1. AIDA64 在 FAE 工具箱中的定位</h5>\n<p>AIDA64 = <b>信息+性能+压力</b>三合一工具：看信息（内存/SPD/主板）、跑性能（Cache & Memory Benchmark）、压系统（System Stability Test）。FAE 用它做“性能类客诉”和“稳定性复现”的第一现场。</p>\n<h5>2. 关键界面（先记这三个）</h5>\n<ul><li><b>Computer → DMI/SMBIOS</b>：内存插槽信息、容量、频率（对照识别）；</li>\n<li><b>Motherboard → SPD</b>：各内存条的 SPD 数据（XMP 档、厂商、颗粒信息）；</li>\n<li><b>Tools → Cache & Memory Benchmark</b>：读/写/复制/延迟四项指标；</li>\n<li><b>Tools → System Stability Test</b>：压力测试面板（勾选内存项）。</li></ul>\n<h5>3. 性能基准解读（判读 4 个值）</h5>\n<table><tr><th>指标</th><th>含义</th><th>异常提示</th></tr>\n<tr><td>Read/Write/Copy</td><td>带宽（GB/s）</td><td>明显偏低 → 频率/通道/设置问题</td></tr>\n<tr><td>Latency（延迟）</td><td>纳秒（ns）</td><td>异常高 → Gear/FCLK/时序问题</td></tr></table>\n<ul><li>对比基准：同平台同频率参考值（网上/同事数据）；</li>\n<li>比“自己上次”更有意义：客户报“性能变差了”→ 同机跑两次对比，排除主观。</li></ul>\n<h5>4. 压力测试用法</h5>\n<ul><li>Stress Cache & Memory + Stress FPU 可同时勾（模拟高负载）；</li>\n<li>时长：性能验证 30 分钟；稳定性验证 1-8h；</li>\n<li>同时开 HWiNFO 看温度，故障时回看曲线；</li>\n<li>中途报错/蓝屏：记录时间点 + 当时的温度/负载。</li></ul>\n<h5>5. 常见客诉场景</h5>\n<ul><li>“跑分比之前低” → 同条件复跑 + 查频率是否回落/XMP 是否失效；</li>\n<li>“压力测试报错” → 定位环节：降频/关 XMP/换槽逐一排除；</li>\n<li>“延迟很高” → 查 Gear/FCLK/时序是否被 BIOS 自动放宽。</li></ul>\n<div class=\"tip\">💡 AIDA64 三连：SPD 看身份、Benchmark 看性能、Stability 看稳定——三个界面十秒记住，客诉从“感觉不对”变成“数据说话”。</div>"}, {"title": "示波器入门：深入分析的\"信号放大镜\"", "html": "<h5>1. 示波器在 FAE 工具箱里的定位</h5>\n<p>示波器是\"深入分析三件套\"之一：<b>示波器（信号）→ HWiNFO64（温压）→ 超频/降频对照（边界）</b>。它不是日常排查第一工具——先用软件排障，软件覆盖不了再上示波器。</p>\n<h5>2. 示波器能看内存相关什么（FAE 场景）</h5>\n<ul><li><b>供电波形</b>：VDD/VDDQ/VPP 是否稳定、有无跌落/纹波过大（万用表只能看平均，示波器看瞬间）；</li>\n<li><b>信号完整性</b>：数据线波形有无振铃/反射（配合 ODT 问题排查）；</li>\n<li><b>时序测量</b>：实际 tRCD/tRP 等是否与 SPD 一致（需解码器或逻辑分析仪，示波器辅助）；</li>\n<li><b>电源上电顺序</b>：VDD/VDDQ/VPP 上电时序有无异常（DDR5 对 PMIC 时序敏感）。</li></ul>\n<h5>3. 入门操作（拿到示波器别慌）</h5>\n<ol><li>接电源 → 校准探头（1x/10x 档位选对）→ 接地线接好；</li>\n<li>选择通道 CH1 → 设电压刻度（如 0.5V/div）→ 设时间刻度（看电源用 50ms，看信号用 ns 级）；</li>\n<li>触发模式选 AUTO 或 NORMAL + 触发电平设到信号中间；</li>\n<li>测量菜单加 <b>Vpp/Vmax/Vmin/频率</b> 显示，读数截屏存证。</li></ol>\n<h5>4. 常见测量判断（FAE 够用版）</h5>\n<table><tr><th>测什么</th><th>正常形态</th><th>异常提示</th></tr>\n<tr><td>DDR5 VDD/VDDQ</td><td>稳定 1.1V 平线</td><td>跌落/纹波大 → 供电或 PMIC 问题</td></tr>\n<tr><td>VPP 1.8V</td><td>稳定 1.8V</td><td>偏低 → 刷新异常风险</td></tr>\n<tr><td>数据线波形</td><td>干净方波过渡</td><td>振铃大 → ODT/走线/接触问题</td></tr></table>\n<h5>5. 示波器使用纪律</h5>\n<ul><li>测量前确认探头补偿（1kHz 方波校准）；</li>\n<li>单手操作、先断电再动探头；</li>\n<li>照片/波形存证（客户沟通和 FA 报告都需要）；</li>\n<li>不会看波形先问资深同事，别乱下结论。</li></ul>\n<div class=\"tip\">💡 示波器不是 FAE 的日常，但\"什么时候该上示波器\"的判断力是必须的：软件排障走完、仍指向电气层时，就是它上场的时候。</div>"}], "out": "深入分析动作清单（可复用Checklist）"}, {"id": "d29", "title": "绘制排查路径图", "date": "Day 29 · 周四", "dot": "4", "tasks": ["画出完整排查路径图：信息收集→初诊→最小化→交叉替换→BIOS默认→深入分析", "学习\"不跳步\"原则：每一步都有判定标准，先过再走下一步", "用 2 个真实案例画出个性化路径图", "路径图评审：请导师检查逻辑闭环"], "tools": "SOP、XMind/白板工具", "resources": [], "lectures": [{"title": "排查路径图：不跳步的排障地图", "html": "<h5>1. 为什么要有路径图</h5>\n<p>内存问题千奇百怪，但排查套路是固定的。路径图 = 把套路<b>画成决策树</b>，每一步都有<b>判定标准</b>，满足才进下一步。好处：<b>不跳步、不遗漏、可复现、可教人</b>——一个人跑是经验，画成图是资产。</p>\n<h5>2. 标准七层路径（背诵，刻进肌肉）</h5>\n<pre>\n现象记录（现象/概率/环境/版本）\n   ↓ 信息收集完毕？\n信息收集模板补齐（缺字段先问全）\n   ↓\n初步诊断：安装/接触/外观（金手指/插槽/卡扣）\n   ↓\n最小化环境：单条、单槽（A2）、清BIOS\n   ↓\n交叉替换：内存/主板/CPU 定位边界\n   ↓\nBIOS默认 + XMP对照测试（软设置隔离）\n   ↓\n深入分析：MT86/长测/温压/信号（万用表/示波器）\n   ↓\n根因定性 → 对策 → 验证 → 报告\n</pre>\n<h5>3. 每层的判定标准（写清楚才能不跳步）</h5>\n<table><tr><th>层</th><th>判定标准（过/不过）</th></tr>\n<tr><td>信息收集</td><td>字段齐全才算过（缺现象概率就继续问）</td></tr>\n<tr><td>外观/接触</td><td>金手指无氧化划伤 + 插槽无异物 + 卡扣到位</td></tr>\n<tr><td>最小化</td><td>单条 A2 能否点亮/稳定（能 → 多根/混插问题）</td></tr>\n<tr><td>交叉替换</td><td>换条/换槽/换平台 现象跟谁走（跟条=条坏，跟槽=板坏）</td></tr>\n<tr><td>BIOS/XMP</td><td>默认是否稳定 / 开 XMP 是否复现（复现→频率时序相关）</td></tr>\n<tr><td>深入分析</td><td>MT86 0 Error？温度曲线？电压正常？</td></tr></table>\n<h5>4. 画图技巧（输出物质量）</h5>\n<ul><li>用流程图图形（矩形=动作、菱形=判断）或大纲树——<b>菱形判断要写\"是→往哪、否→往哪\"</b>；</li>\n<li>每个分支标结论去向，避免画成\"只有路径没有出口\"；</li>\n<li>真实案例复盘时\"回填\"路径：某案例卡在第几步、是哪层判定漏了，就是你的瓶颈；</li>\n<li>路径图要能\"倒着读\"：从现象出发，反推出最少验证步骤。</li></ul>\n<h5>5. 考核要求（高频考点）</h5>\n<p>\"对任意案例能画出路径图，不跳步\"——画完自问：<b>如果客户只给了这些信息，我能走到哪一步？缺什么信息？</b>答得出，就达标。面试/答辩常让你现场画某现象的路径图，背下七层 + 会回填 = 稳。</p>\n<div class=\"tip\">💡 记忆锚点：\"现象→收集→外观→最小化→交叉→BIOS→深入\"——七层口诀，走到哪层都有判定，才是真排障。</div>"}], "out": "标准排查路径图 + 2个案例路径图"}, {"id": "d30", "title": "案例演练 + 周复盘", "date": "Day 30 · 周五", "dot": "5", "tasks": ["导师给 1 个全新案例，独立走查排查路径（不许跳步）", "输出排查过程记录：每一步判断依据", "完成《12周计划》W6 验收点打勾", "周复盘：把路径图更新进知识库"], "tools": "新案例、路径图模板、验收清单", "resources": [], "lectures": [{"title": "案例演练：把路径图跑一遍", "html": "<h5>1. 演练方法（导师给案例或自己造案例）</h5>\n<p>拿到一个新现象（如“开机风扇转但不亮屏”“两根条只认一根”“频率只有2400”），<b>不查答案</b>，按路径图一步步走，每步写下判断依据——这是检验“真会”的唯一方式：会画图 ≠ 会用图，能用了才算会。</p>\n<h5>2. 演练步骤（标准姿势）</h5>\n<ol><li>现象写全：什么平台/什么操作/什么现象/什么概率；</li>\n<li>信息收集：缺失字段列表（问自己“还缺哪 3 个信息”）；</li>\n<li>初诊分支：外观/接触/最小化 → 记录结果；</li>\n<li>交叉替换：设计实验（换槽/换条/换平台），预判三种结果各自指向；</li>\n<li>深入分析：该用 MT86 还是长测还是万用表？判据是什么？</li>\n<li>结论：根因 + 证据 + 对策。</li></ol>\n<h5>3. 复盘回填（演练的目的是升级路径图）</h5>\n<ul><li>卡在哪一步？为什么卡？（缺信心/缺知识/缺工具）</li>\n<li>哪一步跳了？跳的代价是什么？</li>\n<li>新案例能不能“回填”路径图？新增分支写进去；</li>\n<li>结论：这个案例让我补了什么知识？</li></ul>\n<h5>4. 演练的进阶玩法</h5>\n<ul><li><b>限时演练</b>：给自己 30 分钟，模拟客户等待；</li>\n<li><b>限步骤演练</b>：只问 3 个问题就要下方向；</li>\n<li><b>角色扮演</b>：让同事当客户给模糊描述，你追问（练信息收集）；</li>\n<li><b>倒推演练</b>：给根因，倒推要什么证据能证明它。</li></ul>\n<div class=\"tip\">💡 演练的金标准：每一步都写“我为什么这么判断”。写不出理由 = 还没真会，只是背流程。</div><h5>5. 演练结果的输出（证明你真的过了一遍）</h5><ol><li>写演练记录：现象/每步判断依据/结论（一页纸）；</li><li>回填路径图：新增分支/修正判定标准；</li><li>把演练记录发给导师点评（暴露盲区比自我感觉好）；</li><li>把 2-3 次演练的共性瓶颈列入学习清单。</li></ol><div class=\"warn\">⚠️ 演练评分参考：现象描述（20%）→ 信息收集完整（20%）→ 路径不跳步（25%）→ 判定有依据（20%）→ 结论与证据（15%）——导师可以按这五项打分，你也能自评。低于 70 分 = 继续练，别急着上真实客诉。</div>"}], "out": "独立案例排查记录 + W6复盘"}]}, {"id": "w7", "badge": "W7", "title": "NTF偶发故障专项：复现 + 交叉验证 + 压力复测 + 批次对比", "sub": "阶段 P2 · 搞定\"消失的故障\"，用证据链说话", "accept": "在模拟NTF案例中复现并给出结论与证据链。", "tools": "MonitorMemtest、BurnInTest、版本/批次对照表", "phase": "P2", "weekend": "周末加油站：复习 W5-W7 的映射表+路径图+NTF证据链；预习 W8 沟通话术手册。 可选：学习\"如何写技术邮件\"范例 3 篇", "days": [{"id": "d31", "title": "NTF 方法论：为什么会有\"找不到故障\"", "date": "Day 31 · 周一", "dot": "1", "tasks": ["学习 NTF（No Trouble Found）定义与产生原因", "学习 NTF 方法论五板斧：交叉验证、复现环境搭建、压力复测、批次对比、版本比对", "理解区分四类：真不良/假性不良/人为故障/环境干扰", "从案例库找 1 个 NTF 案例看处理过程"], "tools": "NTF方法论资料、案例库", "resources": [{"type": "vid", "url": "https://www.bilibili.com/video/BV1mp421m7aV", "label": "▶ 风扇正常转但黑屏无信号·解决（国丰装机 · 240.4万播放）"}, {"type": "vid", "url": "https://www.bilibili.com/video/BV1qV411S7g9", "label": "▶ 黑屏/蓝屏/闪退最全解决办法（大明湖畔千百万 · 7.0万播放）"}, {"type": "off", "url": "https://learn.microsoft.com/en-us/windows-hardware/drivers/debugger/bug-check-code-reference2", "label": "📄 微软蓝屏代码官方文档"}], "lectures": [{"title": "TOP 故障现象 → 候选根因 + 验证方法", "html": "<h5>1. TOP 故障现象清单（先背目录再背细节）</h5>\n<p>FAE 的“病例库”从十大高频现象开始：<b>无法开机/蓝屏/容量错/性能差/死机重启/不识别/混插兼容/高温/报错/NTF</b>。每个现象 → 候选根因 ≥4 条 + 验证方法——这是排查的“菜单”，客户报任何现象，你两秒内能定位到菜单哪一行。</p>\n<h5>2. 十大现象 × 候选根因（速查骨架）</h5>\n<table><tr><th>现象</th><th>候选根因（排序）</th><th>首选验证</th></tr>\n<tr><td>无法开机/黑屏</td><td>接触→混插→电源→主板</td><td>单条A2+清CMOS</td></tr>\n<tr><td>蓝屏</td><td>驱动↔内存→超频→温度</td><td>dump+MT86</td></tr>\n<tr><td>容量错</td><td>接触→SPD→混插→系统</td><td>BIOS vs 系统识别</td></tr>\n<tr><td>性能差</td><td>XMP未开→Gear→降频→混插</td><td>CPU-Z 频率</td></tr>\n<tr><td>死机重启</td><td>温度→供电→颗粒→驱动</td><td>HWiNFO+长测</td></tr>\n<tr><td>不识别</td><td>接触→SPD→槽→主板</td><td>单条逐槽测</td></tr>\n<tr><td>混插兼容</td><td>频率/时序/颗粒差异</td><td>单条各测 vs 混测</td></tr>\n<tr><td>高温</td><td>散热→TS→负载→降频</td><td>HWiNFO 温度曲线</td></tr>\n<tr><td>报错</td><td>工具/设置→颗粒→兼容</td><td>复现+判据核对</td></tr>\n<tr><td>NTF</td><td>环境→偶发→软件→批次</td><td>五板斧</td></tr></table>\n<h5>3. 怎么“用”这张表（不是背，是查）</h5>\n<ul><li>客户报现象 → 定位行 → 按排序查根因（先高概率/便宜项）；</li>\n<li>每行是“假设列表”：验证一个排除一个，收敛到结论；</li>\n<li>真实案例回填：哪条实际命中、漏了哪条 — 表持续更新；</li>\n<li>映射表与路径图配合：表给“可能”，图给“怎么走”。</li></ul>\n<h5>4. 常见错误</h5>\n<ul><li>凭感觉跳序（直接换条，跳过检查接触）；</li>\n<li>根因没排序（列 5 条不分先后，排查效率低）；</li>\n<li>验证方法缺失（列了根因查不了）。</li></ul>\n<h5>5. 考核/面试用法</h5>\n<p>考官随便抛一个现象（如“客户说频率只有 2400”），你能：<b>①定位菜单行 ②说出 3-4 条排序根因 ③给出验证方法</b>——这就是“会排查”的现场证明。</p>\n<div class=\"tip\">💡 十大现象映射表 = FAE 的“记忆宫殿”：先有目录，再往里面填案例细节。目录不全，经验再多也调不出来。</div>"}, {"title": "NTF 专项：从\"复现不了\"到\"证据链完整\"", "html": "<h5>1. NTF 是什么（No Trouble Found / 无法复现）</h5>\n<p>NTF = 客户报告了故障，但按标准流程测不出来/复现不了。字面“没找到问题”，实质是<b>“现有方法抓不到，需要换思路”</b>。FAE 面对 NTF 的第一心态：不是“客户胡说”，而是“我还没找到方法”。</p>\n<h5>2. NTF 的三大来源</h5>\n<ul><li><b>环境相关</b>：客户侧温度/供电/负载波动，测试环境太干净；</li>\n<li><b>偶发硬件</b>：临界失效（时序边界/虚焊/颗粒退化）只在特定条件出错；</li>\n<li><b>软件/驱动</b>：系统层问题被误报为内存问题（测内存反而正常）。</li></ul>\n<h5>3. NTF 五板斧（方法论骨架）</h5>\n<ol><li><b>交叉验证</b>：换人换机换工具，排除操作/设备误差；</li>\n<li><b>复现环境搭建</b>：按客户条件还原（温度/负载/软件）；</li>\n<li><b>压力复测</b>：加时间加强度（长测/高低温/大负载）；</li>\n<li><b>批次对比</b>：同批次不同批次的条子对比，看是否是批次性问题；</li>\n<li><b>版本比对</b>：BIOS/驱动/固件版本前后对比，排除软件引入。</li></ol>\n<h5>4. 每板斧的证据产出</h5>\n<table><tr><th>板斧</th><th>做什么</th><th>证据</th></tr>\n<tr><td>交叉验证</td><td>同条件双人复测</td><td>两份独立日志</td></tr>\n<tr><td>复现环境</td><td>还原客户条件</td><td>环境记录表 + 结果</td></tr>\n<tr><td>压力复测</td><td>24h 长测 + 高温</td><td>时长/温度/错误数</td></tr>\n<tr><td>批次对比</td><td>同规格不同批</td><td>批次号 + 各自结果</td></tr>\n<tr><td>版本比对</td><td>新老版本对比</td><td>版本列表 + 现象变化</td></tr></table>\n<h5>5. 心态与沟通</h5>\n<ul><li>NTF ≠ 客户撒谎：先默认“有效反馈”，用数据找答案；</li>\n<li>给客户的同步：“我们正在用 X 方法复现，目前测了 N 小时无异常，已加严到 Y 条件”——透明度是关键；</li>\n<li>真闭不了环：明确“未复现 + 建议措施”（更换/持续监控），不编结论。</li></ul>\n<div class=\"tip\">💡 NTF 的终极答案不是“没问题”，而是“在什么条件下没问题、什么条件下可能有问题”——把边界说清楚，就是专业闭环。</div>"}, {"title": "案例库：让每一单客诉都变成资产", "html": "<h5>1. 案例库是什么（FAE 最值钱的个人资产）</h5>\n<p>案例库 = 把每一单客诉的\"现象/根因/对策/验证\"沉淀成可检索的记录。它是 FAE 最值钱的个人资产：<b>案例越多，排查越快，答辩越有底气</b>。面试/晋升时，「你处理过哪些案例、怎么处理的」比任何证书都有说服力。</p>\n<h5>2. 每例 <200 字的推荐格式（精简到可复用）</h5>\n<pre>\n案例编号：FAE-2026-XXX\n现象：一句话（客户视角）\n平台：主板/CPU/OS/内存型号\n根因：一句话（可验证）\n证据：日志/截图路径\n对策：临时 + 永久\n状态：已闭环/复核中\n</pre>\n<h5>3. 什么案例值得记（不是所有都记）</h5>\n<ul><li>第一次遇到的故障类型（新增认知）；</li>\n<li>排查过程走弯路的（<b>教训最值钱</b>——把\"当时差点往错误方向走\"写进去）；</li>\n<li>证据链完整、能当培训材料的（可分享给新人）；</li>\n<li>客户高频问题（同问必记——直接进 FAQ）。</li></ul>\n<h5>4. 归档节奏（别攒，顺手就记）</h5>\n<ul><li>客诉闭环当天顺手记一例（30 秒的事，趁热写细节才清楚）；</li>\n<li>月底统一补标签和索引（现象/平台/方法三类标签）；</li>\n<li>目标：<b>12 周 ≥10 例，一年 ≥30 例</b>——数字不到就说明你复盘不够；</li>\n<li>定期回访：哪些案例被反复问到？说明 FAQ 没覆盖；哪些过时了？更新或下架。</li></ul>\n<div class=\"tip\">💡 考核要求\"建立案例库 ≥10 例\"——现在每天闭环一单就入库，到 W12 自然达标。写案例时问自己：\"如果我失忆了，靠这条能恢复这个经验吗？\"</div><h5>5. 案例库的进阶用法（从记录到武器库）</h5><ul><li><b>检索标签体系</b>：现象关键词 + 平台 + 内存型号 + 方法——3 个月后还能搜到才是好归档；</li><li><b>案例反哺</b>：同类型案例 ≥3 个 → 提炼成 FAQ/排查手册章节；</li><li><b>年度盘点</b>：年底挑 TOP 案例做内部分享/晋升素材；</li><li><b>新人培训</b>：给新人读 3 个案例再讲出来，比讲 3 小时 PPT 有效。</li></ul>"}], "out": "NTF 方法论思维导图"}, {"id": "d32", "title": "复现环境搭建", "date": "Day 32 · 周二", "dot": "2", "tasks": ["学习复现要素：同平台/同BIOS/同OS/同负载/同环境温度", "实操：为\"每月一次蓝屏\"设计复现实验（压力+场景模拟）", "学习记录复现条件：时间/温度/负载/运行软件清单", "搭建个人复现实验清单模板"], "tools": "复现实验模板、压力工具", "resources": [], "lectures": [{"title": "复现环境搭建：让\"偶发\"现形", "html": "<h5>1. 为什么要“复现环境”（偶发问题的唯一出路）</h5>\n<p>客户报“偶尔死机/随机蓝屏”但测不出 → 没有复现环境就永远无法定位。复现环境 = <b>把出问题的条件尽量还原</b>，让“偶发”变成“可预期重现”。<b>不能复现的问题，只能靠 NTF 流程兜底</b>；能复现，就赢了一半。</p>\n<h5>2. 复现环境搭建清单</h5>\n<ul><li><b>同平台</b>：同 CPU/主板/BIOS/OS（版本一致才可对比）；</li>\n<li><b>同负载</b>：客户出问题时的软件/负载类型（游戏就开游戏，渲染就跑渲染）；</li>\n<li><b>同温度</b>：夏天闷箱就模拟高温（取暖器/封闭机箱/高室温）；</li>\n<li><b>同操作</b>：客户说“每次开某软件就挂”就反复跑该软件；</li>\n<li><b>加压策略</b>：先按原样跑，再加大强度（长测/高温/加负载）让临界问题显形。</li></ul>\n<h5>3. 复现实验设计（一次一变量）</h5>\n<pre>\n基线：原平台原环境 24h 长测 → 记录\n变量1：换内存（同型号）→ 观察\n变量2：换插槽 → 观察\n变量3：降频/关 XMP → 观察\n变量4：加高温 → 观察\n结论：哪个变量让问题出现/消失 → 定位边界\n</pre>\n<p>每次只改一个变量，记录现象与结果——交叉表就是证据链的骨架。</p>\n<h5>4. 复现失败怎么办（进入 NTF 流程）</h5>\n<ul><li>保留“未复现”的记录（同条件测过 N 小时无异常，也是证据）；</li>\n<li>加大强度重试（时间更长/温度更高/负载更重）；</li>\n<li>收集客户侧日志（WHEA/事件查看器/dump）持续监控；</li>\n<li>按 NTF 方法论推进，别硬等复现。</li></ul>\n<h5>5. 复现环境的应用场景</h5>\n<ul><li>客诉偶发问题定位；</li>\n<li>对策验证（改完再跑同样环境确认解决）；</li>\n<li>批次对比/版本对比实验的底座。</li></ul>\n<div class=\"tip\">💡 “偶发”的敌人有三个：时间（跑够久）、温度（压到位）、样本（同条件多复测）。三管齐下，偶发就会显形。</div><h5>6. 复现结果怎么用（不白搭环境）</h5><ol><li>复现成功 → 拿到“哑弹”：锁定条件 → 逐步变量法定位触发点；</li><li>复现失败（未复现）→ 也是结果：记录“同条件 N 小时无异常”作为 NTF 证据；</li><li>无论成功失败，环境配置表存档（后续对策验证复用）；</li><li>复现成功的数据 = FA 报告最硬核的证据。</li></ol>"}], "out": "复现实验设计文档（针对案例）"}, {"id": "d33", "title": "压力复测 + 版本比对", "date": "Day 33 · 周三", "dot": "3", "tasks": ["设计并执行 8h+ MonitorMemtest/BurnInTest 压力复测", "学习版本比对：BIOS版本、驱动版本、颗粒版本对故障的影响", "实操：同一故障现象在不同 BIOS 版本下复测对比", "建立《版本/批次对照表》记录格式"], "tools": "MonitorMemtest、BurnInTest、版本记录表", "resources": [], "lectures": [{"title": "压力复测 + 版本比对：给间歇性问题加码", "html": "<h5>1. 压力复测是给谁用的</h5>\n<p>客户报“偶发死机/随机重启”但基础测试全过 → <b>压力复测</b>就是给这种“间歇性/隐性”问题加码的武器：延长时间、提高温度、加大负载，把临界问题从“藏起来”逼到“显形”。</p>\n<h5>2. 加码四要素（组合使用）</h5>\n<table><tr><th>要素</th><th>做法</th><th>让什么显形</th></tr>\n<tr><td>时间</td><td>基础 1Pass → 长测 24h</td><td>温度累积/时序临界</td></tr>\n<tr><td>温度</td><td>高温箱 55℃/85℃ 区间测试</td><td>高温退化/散热问题</td></tr>\n<tr><td>负载</td><td>BurnIn 内存+CPU 同时压</td><td>供电/系统级问题</td></tr>\n<tr><td>场景</td><td>复刻客户“必死操作”</td><td>特定软件/驱动交互</td></tr></table>\n<h5>3. 版本比对（与复测搭配）</h5>\n<ul><li>新老 BIOS 对比：同条子刷不同版本，看问题是否随版本消失/出现；</li>\n<li>驱动版本对比：显卡/芯片组/内存相关驱动前后对照；</li>\n<li>固件对比：SSD/外设固件（系统级报错时）；</li>\n<li>记录每个版本 + 现象表，找到“引入问题版本”或“修复版本”。</li></ul>\n<h5>4. 记录与判读</h5>\n<ul><li>每次复测填写：条件（时长/温度/负载）/结果（0 错 or N 错+时间点）；</li>\n<li>错误只在高温出现 → 散热/颗粒温度边界；只在长测后段出现 → 累积问题；只在某个版本出现 → 版本引入；</li>\n<li>结论要能回答：“在什么条件下没问题 / 什么条件下有问题”——边界即结论。</li></ul>\n<h5>5. 与客户的沟通</h5>\n<p>“我们已按您的场景做了 24h 高温压力复测，目前 0 错误；同时对比了 BIOS 老版本，怀疑与 X 版本有关，正在验证”——管理层和客户要的是“有动作 + 有时间表”，不是“测了没问题”一句话。</p>\n<div class=\"tip\">💡 间歇性问题的三件套：长时间（24h）+ 高温（55-85℃）+ 版本对比。三件都上，NTF 就不“难找”了。</div>"}], "out": "压力复测日志 + 版本对照表首行"}, {"id": "d34", "title": "批次对比 + 区分真假不良", "date": "Day 34 · 周四", "dot": "4", "tasks": ["学习批次号解读：从条码/标签识别生产批次、颗粒批次", "学习批次对比实验：不同批次同型号条子交叉验证", "学习真不良(数据确凿) vs 假性不良(环境/驱动/人为) vs 环境干扰(ESD/电源)的判断逻辑", "用 2 个旧案例练习\"贴标签\"：真/假/人为/环境"], "tools": "批次对照表、历史案例", "resources": [], "lectures": [{"title": "批次对比 + 真/假不良判别", "html": "<h5>1. 批次对比是什么</h5>\n<p>把<b>同型号、不同生产批次</b>的样品拿出来对比测试，定位“是不是某个批次的共性问题”。客户报“这批条子有问题”时，批次对比是最快的批量风险判断工具。</p>\n<h5>2. 批次号解读（怎么看条子批次）</h5>\n<ul><li>模组标签：通常有 <b>PN（产品编号）+ 批次码/日期码</b>（周码/年周，如 2635 = 2026 年第 35 周）；</li>\n<li>颗粒批次：颗粒表面有 <b>Date Code</b>（如 2608 = 2026 年第 08 周）；</li>\n<li>SN 序列号：部分厂商含批次信息，用于追溯；</li>\n<li>不同来源的“同型号”可能不同颗粒批次——要区分“模组批次 vs 颗粒批次”。</li></ul>\n<h5>3. 批次对比实验设计</h5>\n<ol><li>取样本：故障批次 ≥3 条 + 对照批次 ≥2 条（同型号）；</li>\n<li>同平台同条件：同一主板/BIOS/OS 跑同样测试；</li>\n<li>测试项：MT86 1Pass + 8h 长稳 + 温度监控（统一判据）；</li>\n<li>记录：每条批次号 + 结果（0 Error / Errors）；</li>\n<li>结论：故障集中在某个批次 = 批次性问题；分散出现 = 通用问题。 </li></ol>\n<h5>4. 真不良 vs 假性不良 vs 环境干扰（判定逻辑）</h5>\n<table><tr><th>类型</th><th>特征</th><th>动作</th></tr>\n<tr><td>真不良（数据确凿）</td><td>错误可复现、定位到颗粒/地址</td><td>换货/返修/FA 报告</td></tr>\n<tr><td>假性不良（环境/驱动/人为）</td><td>换平台/换驱动后消失</td><td>还原条件确认 + 说明</td></tr>\n<tr><td>环境干扰（ESD/电源/温度）</td><td>特定场景才触发、现场复现难</td><td>环境记录 + 复现实验</td></tr></table>\n<h5>5. 客户沟通</h5>\n<p>“我们抽了 X 条故障批次 + Y 条对照批次跑了同样测试，结果显示 Z” ——用批次数据说话，比“应该没问题”有说服力十倍。</p>\n<div class=\"tip\">💡 批次对比的前提是“会看批次号”——你读不懂标签，实验就无从设计。先练：拿两条条子，30 秒找到 PN 和 Date Code。</div>"}], "out": "批次对比实验记录 + 四类不良判别卡"}, {"id": "d35", "title": "模拟 NTF 案例：结论与证据链", "date": "Day 35 · 周五", "dot": "5", "tasks": ["完成 1 个模拟 NTF 案例：从复现→证据→结论全流程", "输出 NTF 报告：现象/复现条件/测试数据/结论/证据链", "请导师评审证据链是否完整、结论是否过度", "完成《12周计划》W7 验收点打勾 + 周复盘"], "tools": "NTF案例包、报告模板", "resources": [{"type": "vid", "url": "https://www.bilibili.com/video/BV1gaFez8EFT", "label": "▶ 电脑不定时死机卡住重启怎么办（程工修笔记本 · 5683播放）"}], "lectures": [{"title": "NTF 方法论：找不到故障时的破案纪律", "html": "<h5>1. 什么是 NTF 以及为什么存在</h5>\n<p>NTF（No Trouble Found）＝客户报告故障，但标准流程<b>测不出/复现不了</b>。常见原因：环境相关、偶发硬件（温度/时序临界）、软件/驱动被误归为内存。<b>NTF 不是“客户错”的信号，是“现有方法不够”的信号</b>。</p>\n<h5>2. NTF 方法论五板斧（破案纪律）</h5>\n<ol><li><b>交叉验证</b>：换人/换机/换工具，排除操作和设备误差（先确认不是自己测错）；</li>\n<li><b>复现环境搭建</b>：还原客户条件（同平台/同负载/同温度）——不还原就永远复现不了；</li>\n<li><b>压力复测</b>：延长时间、提高温度、加大负载——临界问题在压力下显形；</li>\n<li><b>批次对比</b>：同型号不同批次交叉测，看是不是批次性问题；</li>\n<li><b>版本比对</b>：BIOS/驱动/固件版本前后对比，排除软件引入。</li></ol>\n<h5>3. 每板斧的执行标准（不是口号）</h5>\n<table><tr><th>板斧</th><th>怎么做</th><th>产出证据</th></tr>\n<tr><td>交叉</td><td>两人独立同条件测</td><td>双份独立日志</td></tr>\n<tr><td>复现</td><td>环境表：平台/负载/温度/操作</td><td>复现记录</td></tr>\n<tr><td>复测</td><td>≥24h 长测 + 高温（55/85℃）</td><td>时长/温度/错误数</td></tr>\n<tr><td>批次</td><td>同规格不同批号各取样品</td><td>批次-结果对照</td></tr>\n<tr><td>版本</td><td>新老 BIOS/驱动对照</td><td>版本-现象对照</td></tr></table>\n<h5>4. NTF 报告的结构（证据链完整才算闭环）</h5>\n<ol><li>客户反馈原话（现象/条件/概率）；</li>\n<li>复现尝试记录（方法/时长/结果）；</li>\n<li>五板斧结果表（都做了哪些、各什么结论）；</li>\n<li>结论与边界：在 X 条件下未复现；可能方向 Y；建议 Z（更换/监控/加严测试）；</li>\n<li>后续动作：持续性监控、客户侧日志收集、案例归档。</li></ol>\n<h5>5. 心态（NTF 是 FAE 的成人礼）</h5>\n<ul><li>客户报“有问题”你没复现 → 不是客户错，是条件没还原；</li>\n<li>不要编“可能没问题”硬结案 → 说“未复现+边界”；</li>\n<li>NTF 处理得好 = 释放专业性：透明度、方法、边界，客户看在眼里。</li></ul>\n<div class=\"tip\">💡 NTF 的破案纪律：先排除自己 → 再还原条件 → 加压等它显形 → 用对比安证据 → 边界说清楚。五板斧走完，NTF 不再是黑箱。</div>"}, {"title": "NTF 专项：从\"复现不了\"到\"证据链完整\"", "html": "<h5>1. NTF 是什么（No Trouble Found / 无法复现）</h5>\n<p>NTF = 客户报告了故障，但按标准流程测不出来/复现不了。字面“没找到问题”，实质是<b>“现有方法抓不到，需要换思路”</b>。FAE 面对 NTF 的第一心态：不是“客户胡说”，而是“我还没找到方法”。</p>\n<h5>2. NTF 的三大来源</h5>\n<ul><li><b>环境相关</b>：客户侧温度/供电/负载波动，测试环境太干净；</li>\n<li><b>偶发硬件</b>：临界失效（时序边界/虚焊/颗粒退化）只在特定条件出错；</li>\n<li><b>软件/驱动</b>：系统层问题被误报为内存问题（测内存反而正常）。</li></ul>\n<h5>3. NTF 五板斧（方法论骨架）</h5>\n<ol><li><b>交叉验证</b>：换人换机换工具，排除操作/设备误差；</li>\n<li><b>复现环境搭建</b>：按客户条件还原（温度/负载/软件）；</li>\n<li><b>压力复测</b>：加时间加强度（长测/高低温/大负载）；</li>\n<li><b>批次对比</b>：同批次不同批次的条子对比，看是否是批次性问题；</li>\n<li><b>版本比对</b>：BIOS/驱动/固件版本前后对比，排除软件引入。</li></ol>\n<h5>4. 每板斧的证据产出</h5>\n<table><tr><th>板斧</th><th>做什么</th><th>证据</th></tr>\n<tr><td>交叉验证</td><td>同条件双人复测</td><td>两份独立日志</td></tr>\n<tr><td>复现环境</td><td>还原客户条件</td><td>环境记录表 + 结果</td></tr>\n<tr><td>压力复测</td><td>24h 长测 + 高温</td><td>时长/温度/错误数</td></tr>\n<tr><td>批次对比</td><td>同规格不同批</td><td>批次号 + 各自结果</td></tr>\n<tr><td>版本比对</td><td>新老版本对比</td><td>版本列表 + 现象变化</td></tr></table>\n<h5>5. 心态与沟通</h5>\n<ul><li>NTF ≠ 客户撒谎：先默认“有效反馈”，用数据找答案；</li>\n<li>给客户的同步：“我们正在用 X 方法复现，目前测了 N 小时无异常，已加严到 Y 条件”——透明度是关键；</li>\n<li>真闭不了环：明确“未复现 + 建议措施”（更换/持续监控），不编结论。</li></ul>\n<div class=\"tip\">💡 NTF 的终极答案不是“没问题”，而是“在什么条件下没问题、什么条件下可能有问题”——把边界说清楚，就是专业闭环。</div>"}], "out": "模拟NTF报告（含证据链）"}]}, {"id": "w8", "badge": "W8", "title": "客户对接与跨部门协同：信息收集 + 技术邮件 + 话术", "sub": "阶段 P2 · 技术能力开始\"对外\"", "accept": "完成1次完整信息收集 + 1封技术邮件 + 1次会议记录。", "tools": "沟通话术手册、FA模板、会议记录模板", "phase": "P2", "weekend": "周末加油站：整理 P2 阶段成果（映射表V1→V2、路径图、NTF证据链、邮件话术包）；预习 W9 客诉流程SOP。 可选：给导师发一封\"P2阶段总结\"邮件练手", "days": [{"id": "d36", "title": "信息收集模板实战", "date": "Day 36 · 周一", "dot": "1", "tasks": ["学习信息收集模板全字段：机型/平台/BIOS/内存型号/现象/概率/环境/操作", "学习\"一次问全\"技巧：给客户模板让他们一次性填好", "模拟角色扮演：客户报障，用模板追问到位", "把模板存入企业微信快捷回复/邮箱签名常用"], "tools": "信息收集模板、沟通话术手册", "resources": [{"type": "vid", "url": "https://www.bilibili.com/video/BV19z4y1f7m5", "label": "▶ Outlook邮件技巧·分类管理（东方瑞通 · 1.5万播放）"}, {"type": "vid", "url": "https://www.bilibili.com/video/BV1afQoYnEvQ", "label": "▶ 客服邮件处理（邹阳FBM笔记 · 6827播放）"}], "lectures": [{"title": "信息收集模板：一次问全的 10 个字段", "html": "<h5>1. 为什么信息收集是第一步</h5>\n<p>FAE 90% 的坑来自信息不全就下结论。客户说\"内存坏了\"是<b>结果</b>，你要的是<b>过程事实</b>：什么环境、什么操作、什么现象、什么概率。信息收集的质量直接决定排查方向——收集错，后面全错。</p>\n<h5>2. 十字段模板（发给客户的填空版）</h5>\n<ol><li><b>客户/联系方式</b>：对接人 + 电话/企业微信（紧急时直接联系）；</li>\n<li><b>机型/品牌+SN</b>：整机厂牌型号 + 序列号（判批次/渠道）；</li>\n<li><b>主板型号+BIOS 版本</b>：BIOS 日期/版本号（很多问题随 BIOS 更新消失或出现）；</li>\n<li><b>CPU 型号</b>：IMC 代际差异（12 代 vs 13/14 代内存策略不同）；</li>\n<li><b>OS 版本+补丁</b>：Win10/11 大版本 + 累积更新（兼容性客诉常在这里）；</li>\n<li><b>内存型号+SN+批次+颗粒</b>：模组 PN、条码批次、颗粒厂商（同型号不同批次可能不同颗粒）；</li>\n<li><b>插槽位置/是否混插</b>：A1/A2/B1/B2 哪个槽、是否与其他品牌混用；</li>\n<li><b>现象描述+截图/视频</b>：蓝屏要 dump 文件/蓝屏照片，死机要录触发过程；</li>\n<li><b>复现概率+触发条件</b>：必现/偶发、开机/压力/冷机/热机/特定软件；</li>\n<li><b>环境+已做动作</b>：温度/供电/湿度，客户已经试过什么（换槽？单条？清CMOS？）。</li></ol>\n<h5>3. 每个字段的追问示例（拿到\"不够填\"时怎么追问）</h5>\n<ul><li>\"蓝屏\" → 追问：蓝屏代码是多少？什么时候开始？开着什么软件？截图发我；</li>\n<li>\"开不了机\" → 追问：有无报警声/指示灯？显示器有无信号？插几根条？</li>\n<li>\"偶尔死机\" → 追问：大概多久一次？重启后正常吗？是特定操作还是随机？</li>\n<li>\"性能差\" → 追问：和什么基准比？BIOS 里频率实际多少？XMP/EXPO 开了吗？</li></ul>\n<h5>4. 沟通技巧（让客户愿意配合）</h5>\n<ul><li>发<b>填空模板</b>（表格格式）比来回追问高效——客户填起来快，你也拿得全；</li>\n<li>要求<b>截图/视频而非口头描述</b>：\"蓝屏\"要有照片+dump，\"报错\"要有截图（很多问题看一眼截图就定性了）；</li>\n<li>进度<b>主动同步</b>销售/客户，避免\"失联\"猜疑；</li>\n<li>一次问全 vs 挤牙膏：宁可第一次多问几项，别\"想到哪问到哪\"——客户会觉得你没章法。</li></ul>\n<h5>5. 常见\"信息陷阱\"提醒</h5>\n<ul><li>客户说\"换了内存就好\" ≠ 旧条一定坏——可能只是旧条与平台配合问题；</li>\n<li>客户说\"两根都试过\" 要确认：是\"两根都不行\"还是\"每根单独都行、两根一起不行\"（后者是兼容性/供电问题）；</li>\n<li>BIOS 版本必问——刷了 Beta BIOS 后的\"新故障\"可能版本引入；</li>\n<li>拍照要求：金手指正反面、整条标签、插槽位、蓝屏/报错画面，缺一不可。</li></ul>\n<div class=\"tip\">💡 把十字段做成一张 Excel/表格模板存桌面，接单直接发给客户填——这是 FAE 的第一个\"趁手工具\"。</div>"}], "out": "信息收集模板（自用优化版）"}, {"id": "d37", "title": "技术邮件写作", "date": "Day 37 · 周二", "dot": "2", "tasks": ["学习技术邮件结构：主题/背景/已查信息/初步判断/请求事项/时间承诺", "学习写作原则：结论先行、数据说话、口径一致、不夸大", "实操：写 1 封\"向客户要信息\"的邮件，导师批改", "学习回复客户催问的礼貌话术"], "tools": "邮件模板、导师批改", "resources": [{"type": "vid", "url": "https://www.bilibili.com/video/BV19z4y1f7m5", "label": "▶ Outlook邮件技巧·分类管理（东方瑞通 · 1.5万播放）"}, {"type": "vid", "url": "https://www.bilibili.com/video/BV1afQoYnEvQ", "label": "▶ 客服邮件处理（邹阳FBM笔记 · 6827播放）"}], "lectures": [{"title": "技术邮件写作：结构 + 话术 + 模板", "html": "<h5>1. 技术邮件在 FAE 工作里的定位</h5>\n<p>FAE 的很多结论是<b>通过邮件交付</b>的：给客户的技术答复、给研发的问题描述、给销售的口径同步。邮件写得好 = 专业形象 + 减少来回拉扯；写不好 = 客户追问三次、领导帮你擦屁股。</p>\n<h5>2. 技术邮件结构（六段式模板）</h5>\n<pre>\n主题：关于【客户/项目】内存【现象】的进展说明\n背景：1-2 行说明这封邮件为什么发（什么事/谁发起）\n已确认的信息：客户/平台/内存型号/现象（字段清单）\n初步判断：当前结论或假设（明确是“结论”还是“假设”）\n请求事项：需要对方做什么（具体/可执行/带期限）\n时间承诺：下一步结论/交付时间\n</pre>\n<h5>3. 写作五原则</h5>\n<ul><li><b>结论先行</b>：第一段就出结论，别让读者猜；</li>\n<li><b>数据说话</b>：用日志截图/数字，不用“好像/应该”；</li>\n<li><b>口径一致</b>：技术口径与销售/研发统一，别内部矛盾；</li>\n<li><b>不夸大</b>：不确定就写“待确认”，不写“肯定没问题”；</li>\n<li><b>一次问全</b>：需要客户提供的东西一次列全，别挤牙膏。</li></ul>\n<h5>4. 常见句式库（可直接套）</h5>\n<ul><li>催办：\"麻烦您在 X 时间前确认 Y，以便我们 Z\"；</li>\n<li>致歉/解释：\"非常抱歉造成困扰，我们正在按 A→B→C 排查，预计 X 时间给结论\"；</li>\n<li>拒绝/边界：\"此项超出我们可承诺范围，建议以官方规格为准，我们可协助验证\"；</li>\n<li>结束：\"期待您的反馈，如需进一步信息随时联系\"。</li></ul>\n<h5>5. 邮件“三步走”</h5>\n<p>① 写草稿（把要说的都倒出来）→ ② 压缩（删形容词，改数据）→ ③ 复查（结论在不在第一段？待办有没有期限？口径和团队一致吗？）。10 分钟内能完成一封专业邮件。</p>\n<div class=\"tip\">💡 邮件是“留痕”的：客户会翻旧邮件对质。所以写邮件时想好“一年后回看这封，我是否解释得清” —— 这是技术邮件的终极检验。</div><h5>6. 邮件“回锅肉”检查单（发送前 30 秒）</h5><ul><li>主题能一眼看懂吗？（含客户/项目/现象关键词）；</li><li>第一段有没有结论/背景？</li><li>待办有没有“谁+何时”？</li><li>附件文件名规范吗？（日期_主题_内容，不含个人昵称）；</li><li>收件人选对了吗？抄送给需要知情的人？</li></ul><p>30 秒检查，避免“邮件发出去又要追一封解释”的尴尬。</p>"}], "out": "1 封批改后的技术邮件"}, {"id": "d38", "title": "临时对策写作", "date": "Day 38 · 周三", "dot": "3", "tasks": ["学习临时对策要素：具体动作/适用范围/有效期/验证方法/风险说明", "学习\"临时 vs 永久对策\"边界（权宜可用 ≠ 根因解决）", "实操：为 1 个案例写临时对策（如先降频/换槽位/关XMP）", "学习对策的\"内外口径一致\"：研发/销售/客户说辞统一"], "tools": "对策模板、案例库", "resources": [], "lectures": [{"title": "临时对策写作：先救急，再根治", "html": "<h5>1. 临时对策的意义和边界</h5>\n<p>临时对策 = <b>先让客户能继续用</b>的权宜方案，不等根因定位就要给出去（客户在等，产线在停）。它的边界是：<b>明确标注“临时”、给出适用范围和有效期、并同步根因对策的进度</b>——权宜可用 ≠ 根因解决，这是最重要的纪律。</p>\n<h5>2. 临时对策从哪里来（常见动作库）</h5>\n<ul><li><b>换槽/换通道</b>：A2→B2 或单条试（排除接触/通道）；</li>\n<li><b>降频/关 XMP/EXPO</b>：回到 JEDEC 档（排除超频边界）；</li>\n<li><b>单条运行</b>：排除混插/多插兼容；</li>\n<li><b>清 CMOS/恢复默认</b>：排除 BIOS 残留设置；</li>\n<li><b>换平台试</b>：确认是否是平台配合问题；</li>\n<li><b>更新/回退驱动</b>：排除软件层（先和内存无关，但能让客户先用）。</li></ul>\n<h5>3. 临时对策单的内容（写清楚才是负责任）</h5>\n<pre>\n现象：蓝屏 0x1A（游戏 30 分钟内）\n临时对策：换到 A2 单条 + 关 XMP 恢复 4800\n适用范围：仅排除接触/超频因素，可先恢复使用\n有效期：至根因确认（预计 X 天）\n验证方法：运行游戏 1 小时观察\n风险：若 3 天无复发按 NTF 流程继续\n------------------------------\n永久对策（进行中）：交叉替换定位 + 批次对比\n负责人/期限：王工 / X 日期\n</pre>\n<h5>4. 客户沟通要点</h5>\n<ul><li>给对策时同步预期：“先这样用，我们同时在找根因，X 时间给您结论”——别让客户以为临时就是最终；</li>\n<li>每个动作给“为什么”：“关 XMP 是因为怀疑超频边界，先排除它”；</li>\n<li>客户执行反馈要收集：有效/无效都记录，作为后续判据。</li></ul>\n<h5>5. 常见错误</h5>\n<ul><li>只给动作不给验证方法（客户做完不知道有没有效）；</li>\n<li>不给有效性说明（“先试试”不是专业表述）；</li>\n<li>把临时当永久（客户一直在降频用，根因静默）——主动跟进闭环。</li></ul>\n<div class=\"tip\">💡 临时对策的口诀：“能用 + 标注临时 + 给验证方法 + 跟进永久”——四点齐，客户信任度直接拉满。</div>"}], "out": "临时对策文档 1 份"}, {"id": "d39", "title": "跟会 + 会议记录", "date": "Day 39 · 周四", "dot": "4", "tasks": ["参加一次真实会议（客诉会/项目会/周会）", "用模板写会议记录：议题/结论/待办/负责人/期限", "学习\"随会学习\"：记录不认识的术语会后查证", "学习异议应对：客户质疑时不要硬刚，用数据回应"], "tools": "会议记录模板、会前议程", "resources": [{"type": "vid", "url": "https://www.bilibili.com/video/BV1hi4y1d7rk", "label": "▶ 如何写好会议纪要·老笔杆子（会写材料的明叔 · 33.1万播放）"}], "lectures": [{"title": "跟会与会议记录：FAE 的软技能", "html": "<h5>1. 会议记录四要素（缺一不可）</h5>\n<p><b>议题 → 结论 → 待办 → 责任人/期限</b>。没有待办和责任的会议记录等于没记——散会 3 天后再看，你只记得\"开了个会\"，具体谁做什么全忘了。</p>\n<table><tr><th>要素</th><th>怎么写</th><th>反面例子</th></tr>\n<tr><td>议题</td><td>一句话说明这会为什么开</td><td>（不写，翻记录不知道讨论啥）</td></tr>\n<tr><td>结论</td><td>已达成一致的 X 条决定</td><td>\"讨论了内存问题\"（没结论）</td></tr>\n<tr><td>待办</td><td>具体动作 + 下一步</td><td>\"跟进一下\"（跟什么？）</td></tr>\n<tr><td>责任人/期限</td><td>谁 + 截止日期</td><td>\"尽快处理\"（多快？）</td></tr></table>\n<h5>2. 随会学习（FAE 的\"偷师\"机会）</h5>\n<ul><li>听不懂的术语<b>现场记下来，会后查</b>——会上问显得外行，会下搞懂显得勤奋；</li>\n<li>关注客诉会中\"销售/研发/生产\"各自的立场：销售要安抚客户、研发要证据、生产要排查批次——同一问题的三个视角；</li>\n<li>学导师怎么拆需求（把客户模糊要求翻译成技术判断）、怎么应对异议（被挑战时用数据回应还是先认下再补测）。</li></ul>\n<h5>3. 输出格式（邮件版，30 分钟出）</h5>\n<pre>\n【会议纪要】XX客户 内存异常客诉复盘\n背景：<1 行，客户/问题/影响>\n结论：\n  1. 根因初步指向 <X>，需进一步验证 <Y>\n  2. 临时对策 <A> 已与客户确认\n待办：\n  - [ ] 张三 补充 MemTest86 日志 11/20\n  - [ ] 李四 与研发确认 PMIC 异常机制 11/21\n</pre>\n<p>口径与公司一致：使用公司标准模板/命名，发给客户前先内部确认。</p>\n<h5>4. 会议记录常见坑</h5>\n<ul><li>只记\"讨论了什么\"不记\"决定是什么\"——结论才是可执行项；</li>\n<li>待办没定责任人 → 等于没分配，3 天后没人做；</li>\n<li>会议纪要拖到第二天才发 → 记忆模糊 + 显得不专业。</li></ul>\n<div class=\"tip\">💡 写完自问：如果我现在失忆，只看这份纪要，能知道\"下一步谁在什么时候做什么\"吗？能，就是合格的纪要。</div>"}], "out": "会议记录 1 份"}, {"id": "d40", "title": "P2 阶段总结 + 周复盘", "date": "Day 40 · 周五", "dot": "5", "tasks": ["完成信息收集+邮件+会议记录三项验收打包", "完成 P2 阶段小测（故障+流程+NTF+沟通）", "完成《12周计划》W8 验收点打勾", "P2 阶段总结：能力模型 B/C 域勾选盘点"], "tools": "验收清单、阶段测试卷", "resources": [], "lectures": [{"title": "P2 阶段总结：诊断能力复盘", "html": "<h5>1. P2（W5-W8）能力盘点（逐项要有证据）</h5>\n<ul><li>十大故障场景每个都能列 ≥4 条根因并排序（映射表 V1→V2，能讲清排序逻辑）；</li>\n<li>排查路径图能画、不跳步（给任意案例能现场画）；</li>\n<li>NTF 方法论五板斧能讲能用（复现/交叉/复测/批次/版本）；</li>\n<li>信息收集模板、技术邮件、临时对策、会议记录都有产出（不是学过，是交付过）。</li></ul>\n<h5>2. 阶段总结模板（写给导师看的 500 字）</h5>\n<ol><li><b>我学会的最重要 3 个技能</b>（举例说怎么用的——光说\"会排查\"不算，要说\"某案例我用交叉替换定位了插槽问题\"）；</li>\n<li><b>我踩过的坑</b>（比如\"信息不全就下结论\"\"指标模糊就测试\"——承认坑比炫耀成绩更有价值）；</li>\n<li><b>能力模型 B/C 域自评</b>（故障分析 + 客户对接）打勾，含自评依据；</li>\n<li><b>P3 之前还缺什么</b>（如\"没独立处理过真实客诉\"\"FA 报告没写过\"）——写清楚才能被补。</li></ol>\n<h5>3. 复盘动作（不只是写总结）</h5>\n<ul><li>把映射表、路径图、NTF 报告、邮件模板<b>归档进知识库</b>（编号命名，别散落在聊天记录里）；</li>\n<li>把\"容易忘的判断口诀\"做成<b>卡片</b>（贴工位/手机备忘录）；</li>\n<li>给导师发 500 字<b>阶段小结</b>（锻炼书面汇报能力，也让导师知道你的进展）；</li>\n<li>对照 P3 目标（独立客诉）列出<b>前置条件清单</b>：哪单可以认领、缺什么技能。</li></ul>\n<h5>4. P2 结束时的自测问答</h5>\n<ul><li>客户说\"内存坏了\"，你第一反应是问哪些问题？（应能流畅说出 10 字段）；</li>\n<li>蓝屏 0x1A 和 0x50，你分别往哪查？</li>\n<li>两根内存一条能开机一条不行，下一步做什么？</li></ul>\n<div class=\"tip\">💡 P2 是\"从学知识到用知识\"的转折点：盘点不是走形式，是确认自己真的能独立走完排查闭环。</div><h5>5. P2 复盘的金字塔（自我评估框架）</h5><ul><li><b>What</b>：我学了什么（十大现象/路径图/NTF 五板斧）；</li><li><b>So What</b>：我会用了什么（是否独立走完过排查闭环）；</li><li><b>Now What</b>：下一步补什么（独立客诉/FA 报告/深挖电气层）。</li></ul><p>用这个框架写给导师的阶段小结，比流水账高级得多，也更容易得到针对性指导。</p>"}], "out": "P2 阶段总结 + 三项验收存档"}]}, {"id": "w9", "badge": "W9", "title": "独立客诉参与：客诉单闭环", "sub": "阶段 P3 · 第一次真正上战场", "accept": "独立参与1-2单常规客诉：信息收集→排查→临时对策→进度同步销售；客诉单闭环、销售与客户均确认对策有效。", "tools": "客户支持流程SOP、企业微信/邮件", "phase": "P3", "weekend": "周末加油站：预习 FA 报告模板结构；把客诉复盘结论同步给导师；准备 W10 的案例素材。 可选：找 1 份优秀 FA 报告通读学习写法", "days": [{"id": "d41", "title": "客诉流程 SOP 精读 + 认领案例", "date": "Day 41 · 周一", "dot": "1", "tasks": ["精读《客户支持流程SOP》：接单→登记→处理→复盘全流程", "学习客诉单字段：客户/机型/内存型号/数量/现象/期望", "认领/旁听 1 个真实客诉案例", "建立客诉跟进表（进度/下一步/责任人）"], "tools": "客户支持流程SOP、客诉单模板", "resources": [{"type": "vid", "url": "https://www.bilibili.com/video/BV1PYkrBcE9H", "label": "▶ 如何高情商处理客户投诉（海纳集团视频号 · 7031播放）"}, {"type": "vid", "url": "https://www.bilibili.com/video/BV19b4y1d7rg", "label": "▶ 处理顾客投诉五步曲（梁老师889 · 2032播放）"}], "lectures": [{"title": "客诉处理：从接单到闭环", "html": "<h5>1. 八步闭环（每一步都要有产出物）</h5>\n<p><b>信息收集→初判分级→复现测试→根因分析→临时对策→根因对策→验证→归档</b>。不要跳步：客户催得急也要把证据链走完，否则后患无穷。</p>\n<table><tr><th>步骤</th><th>关键动作</th><th>产出物</th></tr>\n<tr><td>①信息收集</td><td>按模板问全：机型/平台/BIOS/内存型号/现象/概率/环境/操作</td><td>信息收集表（一次问全）</td></tr>\n<tr><td>②初判分级</td><td>判断停线/重大/常规，定响应时效</td><td>问题分级 + 响应节点</td></tr>\n<tr><td>③复现测试</td><td>客户环境复现 + 本司平台复现（MemTest86/BurnInTest）</td><td>复现记录（截图/日志/视频）</td></tr>\n<tr><td>④根因分析</td><td>最小化/交叉替换/批次比对/电气测量，锁定层级</td><td>根因假设 + 证据</td></tr>\n<tr><td>⑤临时对策</td><td>先给客户能用的：换槽/降频/单条/关XMP</td><td>临时对策单</td></tr>\n<tr><td>⑥根因对策</td><td>联动研发/质量：换货/固件/工艺/来料管控</td><td>永久对策 + 责任方</td></tr>\n<tr><td>⑦验证</td><td>对策有效性验证（复测通过 + 客户确认）</td><td>验证报告</td></tr>\n<tr><td>⑧归档</td><td>编号入案例库，写清现象→根因→对策→可复用的排查思路</td><td>案例库条目</td></tr></table>\n<h5>2. 分级与响应时效（先响应，再解决）</h5>\n<ul><li><b>产线停线</b>：最高级，1 小时内响应，电话 + 群同步，24h 内给临时对策；</li>\n<li><b>客户升级/大客户</b>：当日响应，48h 内给初步结论；</li>\n<li><b>常规单</b>：1 个工作日内响应。</li></ul>\n<p>第一时间回复<b>\"已收到，正在排查，预计 X 时间给结论\"</b>——不是等有结论才回。客户的焦虑来自沉默，回复=\\\"确定性缓冲\\\"。</p>\n<h5>3. 客诉单要填的字段（对照你的模板逐一确认）</h5>\n<p>客户/机型/平台/BIOS版本/内存型号与SN/数量/故障现象（原话）/出现概率（必现/偶发/频率）/触发条件（开机/压力/冷机/热机）/环境（温度/电压/机箱风道）/客户期望（退货/换货/分析报告/赔偿）/紧急度。缺字段=后面必返工。</p>\n<h5>4. 临时对策 vs 永久对策（边界要分清）</h5>\n<p>临时对策是<b>给客户先能用</b>：换槽/降频/单条/关 XMP/清 CMOS；永久对策是<b>消除根因</b>：换货/固件/工艺/来料管控。\"权宜可用 ≠ 根因解决\"——临时对策单上要写清适用范围与有效期，避免客户把临时当永久。</p>\n<h5>5. 内部协同与对外口径</h5>\n<p>FAE 是窗口：销售/研发/客户三方信息都从你这里对齐。<b>对外口径统一</b>，别在客户群里互相矛盾——不确定的事先内部确认再回复；同时把客户的原始诉求完整带回内部（含情绪、期望、决策人）。</p>\n<h5>6. 客户预期管理话术（背熟直接可用）</h5>\n<ul><li>催结果：\"根因还在交叉验证，我先把已确认的部分同步给您，预计 X 确认完整结论\"；</li>\n<li>想退货：\"换货流程已启动，同时我建议先试临时对策避免影响生产，两条线并行\"；</li>\n<li>质疑结论：\"我用了 A/B 交叉和压力测试，数据如下...如果还有疑虑我们可以一起复现\"。</li></ul>\n<div class=\"tip\">💡 考核/面试点：能说出\"八步闭环\"还不够，要能随手举出每一\"步的产出物——纸上写不出来的流程不叫会。</div>"}], "out": "客诉单登记记录 + 跟进表"}, {"id": "d42", "title": "客诉排查执行（第一天）", "date": "Day 42 · 周二", "dot": "2", "tasks": ["按信息收集模板向客户补齐全部字段（缺什么问什么）", "初步诊断：安装/接触/外观检查步骤走一遍", "最小化验证：单条/换槽/交叉替换开始执行", "每日进展同步（销售+客户群）"], "tools": "排查SOP、信息收集表、企业微信", "resources": [{"type": "vid", "url": "https://www.bilibili.com/video/BV1PYkrBcE9H", "label": "▶ 如何高情商处理客户投诉（海纳集团视频号 · 7031播放）"}, {"type": "vid", "url": "https://www.bilibili.com/video/BV19b4y1d7rg", "label": "▶ 处理顾客投诉五步曲（梁老师889 · 2032播放）"}], "lectures": [{"title": "客诉处理：从接单到闭环", "html": "<h5>1. 八步闭环（每一步都要有产出物）</h5>\n<p><b>信息收集→初判分级→复现测试→根因分析→临时对策→根因对策→验证→归档</b>。不要跳步：客户催得急也要把证据链走完，否则后患无穷。</p>\n<table><tr><th>步骤</th><th>关键动作</th><th>产出物</th></tr>\n<tr><td>①信息收集</td><td>按模板问全：机型/平台/BIOS/内存型号/现象/概率/环境/操作</td><td>信息收集表（一次问全）</td></tr>\n<tr><td>②初判分级</td><td>判断停线/重大/常规，定响应时效</td><td>问题分级 + 响应节点</td></tr>\n<tr><td>③复现测试</td><td>客户环境复现 + 本司平台复现（MemTest86/BurnInTest）</td><td>复现记录（截图/日志/视频）</td></tr>\n<tr><td>④根因分析</td><td>最小化/交叉替换/批次比对/电气测量，锁定层级</td><td>根因假设 + 证据</td></tr>\n<tr><td>⑤临时对策</td><td>先给客户能用的：换槽/降频/单条/关XMP</td><td>临时对策单</td></tr>\n<tr><td>⑥根因对策</td><td>联动研发/质量：换货/固件/工艺/来料管控</td><td>永久对策 + 责任方</td></tr>\n<tr><td>⑦验证</td><td>对策有效性验证（复测通过 + 客户确认）</td><td>验证报告</td></tr>\n<tr><td>⑧归档</td><td>编号入案例库，写清现象→根因→对策→可复用的排查思路</td><td>案例库条目</td></tr></table>\n<h5>2. 分级与响应时效（先响应，再解决）</h5>\n<ul><li><b>产线停线</b>：最高级，1 小时内响应，电话 + 群同步，24h 内给临时对策；</li>\n<li><b>客户升级/大客户</b>：当日响应，48h 内给初步结论；</li>\n<li><b>常规单</b>：1 个工作日内响应。</li></ul>\n<p>第一时间回复<b>\"已收到，正在排查，预计 X 时间给结论\"</b>——不是等有结论才回。客户的焦虑来自沉默，回复=\\\"确定性缓冲\\\"。</p>\n<h5>3. 客诉单要填的字段（对照你的模板逐一确认）</h5>\n<p>客户/机型/平台/BIOS版本/内存型号与SN/数量/故障现象（原话）/出现概率（必现/偶发/频率）/触发条件（开机/压力/冷机/热机）/环境（温度/电压/机箱风道）/客户期望（退货/换货/分析报告/赔偿）/紧急度。缺字段=后面必返工。</p>\n<h5>4. 临时对策 vs 永久对策（边界要分清）</h5>\n<p>临时对策是<b>给客户先能用</b>：换槽/降频/单条/关 XMP/清 CMOS；永久对策是<b>消除根因</b>：换货/固件/工艺/来料管控。\"权宜可用 ≠ 根因解决\"——临时对策单上要写清适用范围与有效期，避免客户把临时当永久。</p>\n<h5>5. 内部协同与对外口径</h5>\n<p>FAE 是窗口：销售/研发/客户三方信息都从你这里对齐。<b>对外口径统一</b>，别在客户群里互相矛盾——不确定的事先内部确认再回复；同时把客户的原始诉求完整带回内部（含情绪、期望、决策人）。</p>\n<h5>6. 客户预期管理话术（背熟直接可用）</h5>\n<ul><li>催结果：\"根因还在交叉验证，我先把已确认的部分同步给您，预计 X 确认完整结论\"；</li>\n<li>想退货：\"换货流程已启动，同时我建议先试临时对策避免影响生产，两条线并行\"；</li>\n<li>质疑结论：\"我用了 A/B 交叉和压力测试，数据如下...如果还有疑虑我们可以一起复现\"。</li></ul>\n<div class=\"tip\">💡 考核/面试点：能说出\"八步闭环\"还不够，要能随手举出每一\"步的产出物——纸上写不出来的流程不叫会。</div>"}, {"title": "客诉执行工具箱：怎么用好排查工具", "html": "<h5>1. 常规客诉两天排查节奏（先定框架）</h5>\n<table><tr><th>时间</th><th>动作</th><th>工具</th></tr>\n<tr><td>Day1 上午</td><td>信息收集 + 外观/接触检查</td><td>信息收集模板、手电放大镜</td></tr>\n<tr><td>Day1 下午</td><td>最小化 + 交叉替换</td><td>单条换槽、已知正常件</td></tr>\n<tr><td>Day2 上午</td><td>开机级扫描</td><td>MemTest86（1-2 Pass）</td></tr>\n<tr><td>Day2 下午</td><td>系统压力 + 定论</td><td>BurnInTest 8h / 短跑</td></tr></table>\n<p>两天是“常规客诉”基线；疑难/NTF 走升级流程。</p>\n<h5>2. 交叉替换在本单怎么用</h5>\n<p>客户报“这条内存有问题”——先别急着判断是不是条子坏：</p>\n<ul><li>让客户做：单条 A2 槽能否开机？两根各自单独测一次？换槽测？</li>\n<li>判断逻辑：跟条走 = 条子；跟槽走 = 主板；都在 A2 好但 B2 坏 = 槽位问题；</li>\n<li>替换件必须用<b>已知正常件</b>，别拿两条疑似坏的互测。</li></ul>\n<h5>3. 信息收集阶段的关键追问</h5>\n<ul><li>“蓝屏什么代码？什么时候开始？开着什么软件？”——截图/dump 优先；</li>\n<li>“不识别是 BIOS 不显示还是系统不显示？”——定位层级；</li>\n<li>“频率多少？XMP 开了吗？”——排除设置层；</li>\n<li>“试过什么操作？”——避免重复动作浪费客户时间。</li></ul>\n<h5>4. 每个工具的出场顺序（为什么这么排）</h5>\n<ol><li>信息收集/外观（先看再测，便宜优先）；</li>\n<li>最小化+交叉（排除系统干扰）；</li>\n<li>MT86（硬件坏点确认）；</li>\n<li>BurnIn（系统级长稳）；</li>\n<li>万用表/示波器（电气层深挖，必要时）。</li></ol>\n<p>顺序原则：先便宜后昂贵、先排除后确认、先软件后电气。</p>\n<h5>5. 工具箱纪律</h5>\n<ul><li>每个工具的日志/截图保存（证据链）；</li>\n<li>工具版本记录（判读时版本不同结果可能不同）；</li>\n<li>不明参数先查手册；</li>\n<li>用熟 5 个工具 > 会开 15 个工具——深度比广度重要。</li></ul>\n<div class=\"tip\">💡 工具箱的本质是“时机”：什么时候用哪个工具比会用多少工具更重要。两天节奏表就是你的时机地图。</div>"}], "out": "排查日志第1天"}, {"id": "d43", "title": "客诉排查执行（第二天）", "date": "Day 43 · 周三", "dot": "3", "tasks": ["深入测试：MT86/BurnInTest 跑数据，拿日志说话", "复现情况记录：现象/概率/环境/软件版本", "与导师/测试/研发初步对齐判断方向", "用数据回复客户（避免\"凭感觉\"式回复）"], "tools": "MT86、BurnInTest、测试记录模板", "resources": [{"type": "vid", "url": "https://www.bilibili.com/video/BV1PYkrBcE9H", "label": "▶ 如何高情商处理客户投诉（海纳集团视频号 · 7031播放）"}, {"type": "vid", "url": "https://www.bilibili.com/video/BV19b4y1d7rg", "label": "▶ 处理顾客投诉五步曲（梁老师889 · 2032播放）"}], "lectures": [{"title": "客诉处理：从接单到闭环", "html": "<h5>1. 八步闭环（每一步都要有产出物）</h5>\n<p><b>信息收集→初判分级→复现测试→根因分析→临时对策→根因对策→验证→归档</b>。不要跳步：客户催得急也要把证据链走完，否则后患无穷。</p>\n<table><tr><th>步骤</th><th>关键动作</th><th>产出物</th></tr>\n<tr><td>①信息收集</td><td>按模板问全：机型/平台/BIOS/内存型号/现象/概率/环境/操作</td><td>信息收集表（一次问全）</td></tr>\n<tr><td>②初判分级</td><td>判断停线/重大/常规，定响应时效</td><td>问题分级 + 响应节点</td></tr>\n<tr><td>③复现测试</td><td>客户环境复现 + 本司平台复现（MemTest86/BurnInTest）</td><td>复现记录（截图/日志/视频）</td></tr>\n<tr><td>④根因分析</td><td>最小化/交叉替换/批次比对/电气测量，锁定层级</td><td>根因假设 + 证据</td></tr>\n<tr><td>⑤临时对策</td><td>先给客户能用的：换槽/降频/单条/关XMP</td><td>临时对策单</td></tr>\n<tr><td>⑥根因对策</td><td>联动研发/质量：换货/固件/工艺/来料管控</td><td>永久对策 + 责任方</td></tr>\n<tr><td>⑦验证</td><td>对策有效性验证（复测通过 + 客户确认）</td><td>验证报告</td></tr>\n<tr><td>⑧归档</td><td>编号入案例库，写清现象→根因→对策→可复用的排查思路</td><td>案例库条目</td></tr></table>\n<h5>2. 分级与响应时效（先响应，再解决）</h5>\n<ul><li><b>产线停线</b>：最高级，1 小时内响应，电话 + 群同步，24h 内给临时对策；</li>\n<li><b>客户升级/大客户</b>：当日响应，48h 内给初步结论；</li>\n<li><b>常规单</b>：1 个工作日内响应。</li></ul>\n<p>第一时间回复<b>\"已收到，正在排查，预计 X 时间给结论\"</b>——不是等有结论才回。客户的焦虑来自沉默，回复=\\\"确定性缓冲\\\"。</p>\n<h5>3. 客诉单要填的字段（对照你的模板逐一确认）</h5>\n<p>客户/机型/平台/BIOS版本/内存型号与SN/数量/故障现象（原话）/出现概率（必现/偶发/频率）/触发条件（开机/压力/冷机/热机）/环境（温度/电压/机箱风道）/客户期望（退货/换货/分析报告/赔偿）/紧急度。缺字段=后面必返工。</p>\n<h5>4. 临时对策 vs 永久对策（边界要分清）</h5>\n<p>临时对策是<b>给客户先能用</b>：换槽/降频/单条/关 XMP/清 CMOS；永久对策是<b>消除根因</b>：换货/固件/工艺/来料管控。\"权宜可用 ≠ 根因解决\"——临时对策单上要写清适用范围与有效期，避免客户把临时当永久。</p>\n<h5>5. 内部协同与对外口径</h5>\n<p>FAE 是窗口：销售/研发/客户三方信息都从你这里对齐。<b>对外口径统一</b>，别在客户群里互相矛盾——不确定的事先内部确认再回复；同时把客户的原始诉求完整带回内部（含情绪、期望、决策人）。</p>\n<h5>6. 客户预期管理话术（背熟直接可用）</h5>\n<ul><li>催结果：\"根因还在交叉验证，我先把已确认的部分同步给您，预计 X 确认完整结论\"；</li>\n<li>想退货：\"换货流程已启动，同时我建议先试临时对策避免影响生产，两条线并行\"；</li>\n<li>质疑结论：\"我用了 A/B 交叉和压力测试，数据如下...如果还有疑虑我们可以一起复现\"。</li></ul>\n<div class=\"tip\">💡 考核/面试点：能说出\"八步闭环\"还不够，要能随手举出每一\"步的产出物——纸上写不出来的流程不叫会。</div>"}, {"title": "客诉执行工具箱：怎么用好排查工具", "html": "<h5>1. 常规客诉两天排查节奏（先定框架）</h5>\n<table><tr><th>时间</th><th>动作</th><th>工具</th></tr>\n<tr><td>Day1 上午</td><td>信息收集 + 外观/接触检查</td><td>信息收集模板、手电放大镜</td></tr>\n<tr><td>Day1 下午</td><td>最小化 + 交叉替换</td><td>单条换槽、已知正常件</td></tr>\n<tr><td>Day2 上午</td><td>开机级扫描</td><td>MemTest86（1-2 Pass）</td></tr>\n<tr><td>Day2 下午</td><td>系统压力 + 定论</td><td>BurnInTest 8h / 短跑</td></tr></table>\n<p>两天是“常规客诉”基线；疑难/NTF 走升级流程。</p>\n<h5>2. 交叉替换在本单怎么用</h5>\n<p>客户报“这条内存有问题”——先别急着判断是不是条子坏：</p>\n<ul><li>让客户做：单条 A2 槽能否开机？两根各自单独测一次？换槽测？</li>\n<li>判断逻辑：跟条走 = 条子；跟槽走 = 主板；都在 A2 好但 B2 坏 = 槽位问题；</li>\n<li>替换件必须用<b>已知正常件</b>，别拿两条疑似坏的互测。</li></ul>\n<h5>3. 信息收集阶段的关键追问</h5>\n<ul><li>“蓝屏什么代码？什么时候开始？开着什么软件？”——截图/dump 优先；</li>\n<li>“不识别是 BIOS 不显示还是系统不显示？”——定位层级；</li>\n<li>“频率多少？XMP 开了吗？”——排除设置层；</li>\n<li>“试过什么操作？”——避免重复动作浪费客户时间。</li></ul>\n<h5>4. 每个工具的出场顺序（为什么这么排）</h5>\n<ol><li>信息收集/外观（先看再测，便宜优先）；</li>\n<li>最小化+交叉（排除系统干扰）；</li>\n<li>MT86（硬件坏点确认）；</li>\n<li>BurnIn（系统级长稳）；</li>\n<li>万用表/示波器（电气层深挖，必要时）。</li></ol>\n<p>顺序原则：先便宜后昂贵、先排除后确认、先软件后电气。</p>\n<h5>5. 工具箱纪律</h5>\n<ul><li>每个工具的日志/截图保存（证据链）；</li>\n<li>工具版本记录（判读时版本不同结果可能不同）；</li>\n<li>不明参数先查手册；</li>\n<li>用熟 5 个工具 > 会开 15 个工具——深度比广度重要。</li></ul>\n<div class=\"tip\">💡 工具箱的本质是“时机”：什么时候用哪个工具比会用多少工具更重要。两天节奏表就是你的时机地图。</div>"}], "out": "测试数据包 + 中间结论"}, {"id": "d44", "title": "临时对策 + 闭环推进", "date": "Day 44 · 周四", "dot": "4", "tasks": ["输出临时对策（可立即执行的权宜方案）", "与销售确认商务口径，与客户确认对策可接受", "对策验证：按临时对策执行后复测", "推进客诉单闭环：销售与客端双向确认"], "tools": "对策模板、销售协同、企微", "resources": [], "lectures": [{"title": "客诉推进：从\"判断\"到\"客户满意\"", "html": "<h5>1. 客诉第 4-5 天的关键动作（从\"判断\"到\"闭环\"）</h5>\n<p>到这一步，你已经完成了信息收集、复现、初步定位。<b>现在最重要的事不是再测，而是把结论\"翻译\"成客户能接受的方案</b>：临时对策 + 明确的时间承诺 + 定期同步。很多客诉死在\"结论已经对，但客户不满意\"——因为沟通节奏没跟上。</p>\n<h5>2. 临时对策落地三步</h5>\n<ol><li><b>写清动作与验证方法</b>（让客户能执行）：换槽/单条/关 XMP/降频每一步说清\"做什么、怎么验证、预期结果\"；</li>\n<li><b>和销售确认商务口径</b>：换货/赔偿边界不自己承诺——技术归你，商务归商务，别越界；</li>\n<li><b>客户执行后复测</b> → 确认对策有效 → 记录（客户反馈\"有效/无效\"都要留档）。</li></ol>\n<h5>3. 闭环推进（销售+客户双向确认）</h5>\n<ul><li>给<b>销售</b>：技术结论 + 商务建议（该不该换货、什么口径对外）；</li>\n<li>给<b>客户</b>：临时对策 + 后续永久修复时间表（\"先用这个方案，预计 X 时间出最终根因\"）；</li>\n<li><b>归档</b>：把该案例写入案例库（现象/根因/对策/验证）——闭环当天归档，别拖。</li></ul>\n<h5>4. 客户不满意时的补救</h5>\n<ul><li>先道歉（客户要的是被重视，不是对错）；</li>\n<li>给确定性：\"目前证据表明 X，我建议 Y，预计 Z 时间给您结论\"；</li>\n<li>升级通道：常规解决不了就走升级流程（带证据，别硬扛）；</li>\n<li>闭环后回访：\"方案用了 3 天还稳定吗？\"——体现负责，也是口碑。</li></ul>\n<div class=\"tip\">💡 客户满意度 = 解决速度 × 沟通透明度。一天同步一次进展，比三天后给完美答案更让人安心。主动同步是 FAE 最便宜的加分项。</div><h5>5. 客诉全过程的时间线（客户心里的进度条）</h5><table><tr><th>时间</th><th>客户期望</th><th>FAE 动作</th></tr><tr><td>Day0</td><td>有人回应</td><td>1h 内首次响应</td></tr><tr><td>Day1-2</td><td>有动作</td><td>信息收集+初步排查+同步一次</td></tr><tr><td>Day3-4</td><td>有方向</td><td>初步结论+临时对策</td></tr><tr><td>Day5+</td><td>有时间表</td><td>永久对策+闭环时间承诺</td></tr></table><p>客户的满意度按“沟通节奏”打分，不按“问题难度”打分——节奏保持住，难题也能稳住客户。</p>"}], "out": "临时对策文档 + 闭环确认记录"}, {"id": "d45", "title": "客诉复盘 + 周复盘", "date": "Day 45 · 周五", "dot": "5", "tasks": ["客诉全流程复盘：做得好/卡在哪/下次改进", "把该案例填入个人案例库（现象/根因/对策/验证）", "完成《12周计划》W9 验收点打勾", "如果可能，认领第2单客诉（进阶挑战）"], "tools": "案例库模板、复盘模板", "resources": [{"type": "vid", "url": "https://www.bilibili.com/video/BV1PYkrBcE9H", "label": "▶ 如何高情商处理客户投诉（海纳集团视频号 · 7031播放）"}, {"type": "vid", "url": "https://www.bilibili.com/video/BV19b4y1d7rg", "label": "▶ 处理顾客投诉五步曲（梁老师889 · 2032播放）"}], "lectures": [{"title": "客诉处理：从接单到闭环", "html": "<h5>1. 八步闭环（每一步都要有产出物）</h5>\n<p><b>信息收集→初判分级→复现测试→根因分析→临时对策→根因对策→验证→归档</b>。不要跳步：客户催得急也要把证据链走完，否则后患无穷。</p>\n<table><tr><th>步骤</th><th>关键动作</th><th>产出物</th></tr>\n<tr><td>①信息收集</td><td>按模板问全：机型/平台/BIOS/内存型号/现象/概率/环境/操作</td><td>信息收集表（一次问全）</td></tr>\n<tr><td>②初判分级</td><td>判断停线/重大/常规，定响应时效</td><td>问题分级 + 响应节点</td></tr>\n<tr><td>③复现测试</td><td>客户环境复现 + 本司平台复现（MemTest86/BurnInTest）</td><td>复现记录（截图/日志/视频）</td></tr>\n<tr><td>④根因分析</td><td>最小化/交叉替换/批次比对/电气测量，锁定层级</td><td>根因假设 + 证据</td></tr>\n<tr><td>⑤临时对策</td><td>先给客户能用的：换槽/降频/单条/关XMP</td><td>临时对策单</td></tr>\n<tr><td>⑥根因对策</td><td>联动研发/质量：换货/固件/工艺/来料管控</td><td>永久对策 + 责任方</td></tr>\n<tr><td>⑦验证</td><td>对策有效性验证（复测通过 + 客户确认）</td><td>验证报告</td></tr>\n<tr><td>⑧归档</td><td>编号入案例库，写清现象→根因→对策→可复用的排查思路</td><td>案例库条目</td></tr></table>\n<h5>2. 分级与响应时效（先响应，再解决）</h5>\n<ul><li><b>产线停线</b>：最高级，1 小时内响应，电话 + 群同步，24h 内给临时对策；</li>\n<li><b>客户升级/大客户</b>：当日响应，48h 内给初步结论；</li>\n<li><b>常规单</b>：1 个工作日内响应。</li></ul>\n<p>第一时间回复<b>\"已收到，正在排查，预计 X 时间给结论\"</b>——不是等有结论才回。客户的焦虑来自沉默，回复=\\\"确定性缓冲\\\"。</p>\n<h5>3. 客诉单要填的字段（对照你的模板逐一确认）</h5>\n<p>客户/机型/平台/BIOS版本/内存型号与SN/数量/故障现象（原话）/出现概率（必现/偶发/频率）/触发条件（开机/压力/冷机/热机）/环境（温度/电压/机箱风道）/客户期望（退货/换货/分析报告/赔偿）/紧急度。缺字段=后面必返工。</p>\n<h5>4. 临时对策 vs 永久对策（边界要分清）</h5>\n<p>临时对策是<b>给客户先能用</b>：换槽/降频/单条/关 XMP/清 CMOS；永久对策是<b>消除根因</b>：换货/固件/工艺/来料管控。\"权宜可用 ≠ 根因解决\"——临时对策单上要写清适用范围与有效期，避免客户把临时当永久。</p>\n<h5>5. 内部协同与对外口径</h5>\n<p>FAE 是窗口：销售/研发/客户三方信息都从你这里对齐。<b>对外口径统一</b>，别在客户群里互相矛盾——不确定的事先内部确认再回复；同时把客户的原始诉求完整带回内部（含情绪、期望、决策人）。</p>\n<h5>6. 客户预期管理话术（背熟直接可用）</h5>\n<ul><li>催结果：\"根因还在交叉验证，我先把已确认的部分同步给您，预计 X 确认完整结论\"；</li>\n<li>想退货：\"换货流程已启动，同时我建议先试临时对策避免影响生产，两条线并行\"；</li>\n<li>质疑结论：\"我用了 A/B 交叉和压力测试，数据如下...如果还有疑虑我们可以一起复现\"。</li></ul>\n<div class=\"tip\">💡 考核/面试点：能说出\"八步闭环\"还不够，要能随手举出每一\"步的产出物——纸上写不出来的流程不叫会。</div>"}, {"title": "案例库：让每一单客诉都变成资产", "html": "<h5>1. 案例库是什么（FAE 最值钱的个人资产）</h5>\n<p>案例库 = 把每一单客诉的\"现象/根因/对策/验证\"沉淀成可检索的记录。它是 FAE 最值钱的个人资产：<b>案例越多，排查越快，答辩越有底气</b>。面试/晋升时，「你处理过哪些案例、怎么处理的」比任何证书都有说服力。</p>\n<h5>2. 每例 <200 字的推荐格式（精简到可复用）</h5>\n<pre>\n案例编号：FAE-2026-XXX\n现象：一句话（客户视角）\n平台：主板/CPU/OS/内存型号\n根因：一句话（可验证）\n证据：日志/截图路径\n对策：临时 + 永久\n状态：已闭环/复核中\n</pre>\n<h5>3. 什么案例值得记（不是所有都记）</h5>\n<ul><li>第一次遇到的故障类型（新增认知）；</li>\n<li>排查过程走弯路的（<b>教训最值钱</b>——把\"当时差点往错误方向走\"写进去）；</li>\n<li>证据链完整、能当培训材料的（可分享给新人）；</li>\n<li>客户高频问题（同问必记——直接进 FAQ）。</li></ul>\n<h5>4. 归档节奏（别攒，顺手就记）</h5>\n<ul><li>客诉闭环当天顺手记一例（30 秒的事，趁热写细节才清楚）；</li>\n<li>月底统一补标签和索引（现象/平台/方法三类标签）；</li>\n<li>目标：<b>12 周 ≥10 例，一年 ≥30 例</b>——数字不到就说明你复盘不够；</li>\n<li>定期回访：哪些案例被反复问到？说明 FAQ 没覆盖；哪些过时了？更新或下架。</li></ul>\n<div class=\"tip\">💡 考核要求\"建立案例库 ≥10 例\"——现在每天闭环一单就入库，到 W12 自然达标。写案例时问自己：\"如果我失忆了，靠这条能恢复这个经验吗？\"</div><h5>5. 案例库的进阶用法（从记录到武器库）</h5><ul><li><b>检索标签体系</b>：现象关键词 + 平台 + 内存型号 + 方法——3 个月后还能搜到才是好归档；</li><li><b>案例反哺</b>：同类型案例 ≥3 个 → 提炼成 FAQ/排查手册章节；</li><li><b>年度盘点</b>：年底挑 TOP 案例做内部分享/晋升素材；</li><li><b>新人培训</b>：给新人读 3 个案例再讲出来，比讲 3 小时 PPT 有效。</li></ul>"}], "out": "客诉闭环案例 1 例入库 + 周复盘"}]}, {"id": "w10", "badge": "W10", "title": "FA失效分析报告：现象→数据→根因→对策→验证→预防", "sub": "阶段 P3 · 把一次客诉变成一份资产", "accept": "按模板输出FA报告，报告通过领导评审，根因可追溯、验证数据完整。", "tools": "FA报告模板", "phase": "P3", "weekend": "周末加油站：把 FA 报告给研发/测试同事看，收集跨部门视角；预习 W11 新项目导入。 可选：学习 8D 报告的基本结构（FA 的进阶形态）", "days": [{"id": "d46", "title": "FA 报告模板拆解", "date": "Day 46 · 周一", "dot": "1", "tasks": ["学习 FA 报告六段式：现象→数据→根因→对策→验证→预防", "通读 1 份优秀 FA 报告，拆解每段写法", "学习\"FA写法与边界\"：能下结论的才有依据，不能下结论的明确待验证", "选定自己将要写的案例（优先用 W9 客诉案例）"], "tools": "FA报告模板、优秀范例", "resources": [{"type": "vid", "url": "https://www.bilibili.com/video/BV18t421L7oa", "label": "▶ 笔记本加内存条·拆装方法（想想3c数码 · 18.7万播放）"}, {"type": "vid", "url": "https://www.bilibili.com/video/BV1zp411f7h2", "label": "▶ 内存条的拆装（KOTIN京天售后 · 4.3万播放）"}, {"type": "vid", "url": "https://www.bilibili.com/video/BV1G2dhBmESw", "label": "▶ 学会看内存条出厂日期（政雨Rich · 2.8万播放）"}, {"type": "off", "url": "https://en.wikipedia.org/wiki/DIMM", "label": "📄 维基百科·DIMM"}], "lectures": [{"title": "FA 报告六段式详解：每段怎么写", "html": "<h5>1. FA 报告六段式（FAE 的“毕业设计”）</h5>\n<p>FA 报告 = 失效分析报告，六段骨架：<b>现象 → 数据 → 根因 → 对策 → 验证 → 预防</b>。它不是“交作业”，是给客户、研发、质量三方看的工程结论——决定条子退不退、设计改不改。</p>\n<h5>2. 每段怎么写（示例式）</h5>\n<table><tr><th>段落</th><th>内容</th><th>示例</th></tr>\n<tr><td>现象</td><td>客户原话+环境+频率</td><td>客户：游戏 30 分钟蓝屏 0x1A；平台：B760M + i5-13490F + 2×16G；频率：每周 2-3 次</td></tr>\n<tr><td>数据</td><td>测试记录+截图+日志</td><td>MT86 3Pass 0 错；BurnIn 8h 0 错；HWiNFO DIMM 温度 68℃（正常）</td></tr>\n<tr><td>根因</td><td>排除逻辑+结论+证据</td><td>排除接触（重插无改善）→ 排除超频（关 XMP 仍现）→ 指向驱动：dump 显示 ntoskrnl 访问 0xFFFF... → 更新显卡驱动后未复发</td></tr>\n<tr><td>对策</td><td>临时+永久（分责任）</td><td>临时：更新驱动（客户操作）；永久：厂家驱动验证流程优化（研发）</td></tr>\n<tr><td>验证</td><td>对策后复测数据</td><td>更新后同场景游戏 7 天无蓝屏；MT86 复测 0 错</td></tr>\n<tr><td>预防</td><td>流程/文档/FAQ 沉淀</td><td>新增 FAQ：“蓝屏 0x1A 先查驱动再查内存”；案例库归档</td></tr></table>\n<h5>3. 写作边界（宁可少说不可乱说）</h5>\n<ul><li>能下结论的写结论，不能下结论的写“待验证”；</li>\n<li>不用“可能/应该”，用“数据表明/排除后指向”；</li>\n<li>根因必须可追溯：每个结论能指到一条证据；</li>\n<li>边界写清：哪些平台测了、哪些没测。</li></ul>\n<h5>4. 提高写作效率（复用模板）</h5>\n<ul><li>保留一套 FA 报告模板（六段+表格格式），每单套用；</li>\n<li>测试数据直接引用日志/截图，不重复粘贴大段；</li>\n<li>结案时同步写案例库条目（200 字）+ FAQ（高频才写）。</li></ul>\n<div class=\"tip\">💡 写六段式口诀：“现象要原话、数据要证据、根因要追踪、对策要落地、验证要有数、预防要沉淀”——一段丢一个都扣分。</div>"}], "out": "FA 报告结构拆解笔记"}, {"id": "d47", "title": "案例数据整理", "date": "Day 47 · 周二", "dot": "2", "tasks": ["收集案例全部数据：现象描述/测试日志/截图/环境信息", "整理时间线：什么时间做了什么测试、得到什么结果", "把数据分类归档（现象/试验/电气/温压/软件）", "第37步检查：证据链是否有断点"], "tools": "案例数据包、归档结构", "resources": [], "lectures": [{"title": "案例数据整理：把杂乱证据变成 FA 报告素材", "html": "<h5>1. 案例数据整理的意义</h5>\n<p>同一个现象，3 份杂乱日志 vs 1 份整理好的证据表，领导/研发的响应完全不同。<b>整理证据是 FAE 的专业素养</b>：让数据自己说话，而不是你替数据说话。</p>\n<h5>2. 从杂乱证据到 FA 报告素材的 4 步</h5>\n<ol><li><b>收集</b>：所有日志/截图/视频放同一目录，命名规范（日期_现象_工具）；</li>\n<li><b>筛选</b>：去掉无关信息，保留与现象直接相关的（有错误/异常的时间点优先）；</li>\n<li><b>标注</b>：给关键证据加批注（“此处 Error 出现时温度 85℃”“此为复现第 3 次”）——别让读者猜；</li>\n<li><b>汇总</b>：做成证据表（时间/事件/证据/意义），一条一行。</li></ol>\n<h5>3. 证据表模板（FA 报告直接可用）</h5>\n<pre>\n时间      事件            证据            意义\n14:02   首次蓝屏 0x1A    dump 文件     指向内存\n14:20   MT86 1 Pass 2错  日志截图      硬件层确认\n14:35   换槽后复测 0错   截图           指向接触/槽位\n</pre>\n<h5>4. 证据整理的纪律</h5>\n<ul><li>原始文件绝不修改，整理是复制+标注（保留原始证据链）；</li>\n<li>截图带时间戳/完整信息（别截一半）；</li>\n<li>每个结论标注“证据在哪”——写进 FA 报告时能秒找到；</li>\n<li>整理完自己先读一遍：不看原始日志，光看证据表能还原过程吗？</li></ul>\n<div class=\"tip\">💡 好证据包的标准：别人只拿你的证据表，不用翻原始文件，就能复述整件事——这就是“让数据说话”。</div><h5>5. 整理工具与技巧</h5><ul><li>截图工具带矩形框选 + 标注（圈出关键 Error）；</li><li>日志用编辑器搜索关键词定位（如 \"Error\"/\"Fail\"）；</li><li>证据目录按时间命名（20261119_现象_日志），查起来快；</li><li>整理完用 1 句话总结“这份证据说明了什么”——写进证据表意义列。</li></ul>"}], "out": "数据包（按FA报告结构组织）"}, {"id": "d48", "title": "撰写 FA 报告初稿", "date": "Day 48 · 周三", "dot": "3", "tasks": ["按模板填写六段式初稿", "\"现象\"写清客户原话 + 截图；\"数据\"附日志证据", "\"根因\"用\"排除+确认\"逻辑书写；\"对策\"区分临时/永久", "\"验证\"写明验证方法/时长/结果；\"预防\"落到文件或流程"], "tools": "FA报告模板、数据包", "resources": [{"type": "vid", "url": "https://www.bilibili.com/video/BV18Q4y1j76R", "label": "▶ 8D报告怎么写（讨教君质量与管理分享 · 2.8万播放）"}, {"type": "vid", "url": "https://www.bilibili.com/video/BV1BzoNBnEKD", "label": "▶ 8D报告入门·D0到D8全流程（数智营企 · 572播放）"}], "lectures": [{"title": "FA 报告：现象→数据→根因→对策→验证→预防", "html": "<h5>1. 六段式骨架（FA 报告是 FAE 的\"毕业设计\"）</h5>\n<ol><li><b>现象</b>：客户原话 + 截图——谁、什么环境、多久一次（先让任何人快速还原现场）；</li>\n<li><b>数据</b>：测试日志/截图/温压曲线/电气测量——全部可追溯（原始文件路径，不是贴图就完）；</li>\n<li><b>根因</b>：排除+确认逻辑写出结论，附证据（\"先怀疑 X，因 Y 排除，最终指向 Z\"）；</li>\n<li><b>对策</b>：临时（客户侧）与永久（公司侧）分开，各带负责人和时限；</li>\n<li><b>验证</b>：对策后复测数据，写明方法/时长/结果（\"MemTest86 2Pass 0 Error\"比\"已稳定\"可信）；</li>\n<li><b>预防</b>：设计/制程/文档/FAQ/批次处理建议——报告的价值在\"下次不犯\"。</li></ol>\n<h5>2. 写作边界（FAE 第一课）</h5>\n<ul><li>能下结论的写结论，不能下结论的写\"待验证项\"；</li>\n<li>不用\"可能是/应该吧\"，用\"数据表明/排除后指向\"；</li>\n<li>根因必须可追溯：每个结论都能指向一条证据（没有证据的结论=猜测）；</li>\n<li>边界写清：哪些平台测了、哪些没测——坦诚比完美更重要。</li></ul>\n<h5>3. 每段写作要点</h5>\n<table><tr><th>段落</th><th>必须包含</th><th>常见坑</th></tr>\n<tr><td>现象</td><td>原话+截图+频率</td><td>只有结论没现场</td></tr>\n<tr><td>数据</td><td>工具+版本+时长+判据</td><td>贴了日志没解读</td></tr>\n<tr><td>根因</td><td>排除逻辑+证据</td><td>直接跳结论</td></tr>\n<tr><td>对策</td><td>临时/永久分开+负责人</td><td>只有一个笼统建议</td></tr>\n<tr><td>验证</td><td>方法+时长+结果</td><td>\"已稳定\"无数据</td></tr>\n<tr><td>预防</td><td>具体动作+责任方</td><td>\"加强检测\"空话</td></tr></table>\n<h5>4. 评审关注点（领导在看什么）</h5>\n<p>领导看三件事：<b>证据全不全、逻辑通不通、口径专不专业</b>。用《避坑清单》反复自查后再提交，减少返工。</p>\n<div class=\"tip\">💡 写 FA 报告前问自己：如果我是领导，能靠这份报告给客户解释清楚吗？能给研发指方向吗？能三个月后自己看明白吗？三个能，就合格。</div>"}], "out": "FA 报告初稿"}, {"id": "d49", "title": "报告评审 + 修改", "date": "Day 49 · 周四", "dot": "4", "tasks": ["请导师/领导评审初稿，逐条记录意见", "学习评审关注点：根因可追溯性、验证数据完整性、结论不过度", "修改报告：补数据/改措辞/弱化无依据结论", "形成《FA报告避坑清单》（首版）"], "tools": "评审意见、修改记录", "resources": [], "lectures": [{"title": "报告评审：领导在看什么", "html": "<h5>1. 评审常见问题（避坑清单——写报告前先自查）</h5>\n<ul><li><b>证据不足</b>：结论没有数据支撑 → 补日志/截图/测量值（每个结论问自己\"证据在哪\"）；</li>\n<li><b>逻辑跳跃</b>：从现象直接跳结论 → 补上排查过程（让人能跟着你的思路走）；</li>\n<li><b>口径过度</b>：\"肯定是内存问题\" → 改成\"数据指向内存，待交叉验证\"——留余量是专业；</li>\n<li><b>边界不清</b>：哪些测过、哪些没测 → 明确\"验证范围与局限\"（坦诚被尊重，吹牛被抓包）</li></ul>\n<h5>2. 评审前自查清单（10 分钟过一遍）</h5>\n<ul><li>现象有客户原话 + 截图？</li>\n<li>每条结论能指向一条具体证据（日志行/截图/数值）？</li>\n<li>排除逻辑写了？为什么先怀疑这个、后来排除？</li>\n<li>临时对策与永久对策分开，各定了负责人/时限？</li>\n<li>用了\"可能/应该\"的地方改成\"数据表明/排除后指向\"？</li></ul>\n<h5>3. 评审流程（走完才叫定稿）</h5>\n<ol><li>自己先按清单自查一遍（上面 5 条全过）；</li>\n<li>请<b>导师/研发/测试同事预审</b>：导师看逻辑、研发看机理、测试看数据——不同视角抓不同问题；</li>\n<li>按意见修改 → 标出<b>\"修改记录\"</b>（哪条意见改成了什么——让评审知道你有回应）；</li>\n<li>领导终审 → 通过后归档（编号 + 标签）。</li></ol>\n<h5>4. 心态（评审是免费的老师）</h5>\n<p>评审不是找茬，是帮你把报告变成\"别人也能验证\"的文档。被打回 2-3 次很正常——每打回一次，避坑清单就多一条经验，下次报告就快一小时。被打回时记下每条意见，不改报告也要记录。</p>\n<div class=\"tip\">💡 你写报告的速度 = 你对\"评审想看什么\"的理解速度。理解越深，返工越少。第一次写不好没关系，别第三次还犯同一个错。</div><h5>5. 常见评审意见对照表（遇到就知道怎么改）</h5><table><tr><th>意见</th><th>原因</th><th>改法</th></tr><tr><td>“证据不足”</td><td>结论没数据</td><td>补日志/截图/数值</td></tr><tr><td>“逻辑跳跃”</td><td>现象→结论缺过程</td><td>补排查步骤</td></tr><tr><td>“口径过大”</td><td>说得太满</td><td>改“数据指向…待验证”</td></tr><tr><td>“边界不清”</td><td>没说测了哪些</td><td>加“验证范围与局限”</td></tr></table>"}], "out": "FA 报告修订版 + 避坑清单"}, {"id": "d50", "title": "报告定稿 + 周复盘", "date": "Day 50 · 周五", "dot": "5", "tasks": ["完成报告定稿并通过领导评审", "FA 报告归档案例库（编号/日期/搜索标签）", "完成《12周计划》W10 验收点打勾", "周复盘：本次报告最难的环节是什么"], "tools": "FA报告模板、案例库", "resources": [], "lectures": [{"title": "报告定稿与复盘", "html": "<h5>1. 定稿标准（六段齐全 + 可追溯）</h5>\n<ul><li><b>六段齐全</b>：现象 / 数据 / 根因 / 对策 / 验证 / 预防；</li>\n<li><b>每个结论可追溯到数据</b>：说\"稳定\"就要有跑了多久的数据，说\"根因\"就要有交叉验证记录；</li>\n<li><b>边界明确</b>：验证范围、未验证项写清楚（哪些平台没测、哪些场景没覆盖——诚实是专业的一部分）；</li>\n<li><b>通过领导评审</b>：评审意见逐条处理并留痕。</li></ul>\n<h5>2. 定稿前的自查清单</h5>\n<ul><li>现象描述是否有客户原话 + 截图？</li>\n<li>数据部分是否包含：测试环境 / 工具版本 / 时长 / 判据 / 原始日志路径？</li>\n<li>根因是否为\"最简解释\"（Occam 剃刀——别过度设计）？</li>\n<li>对策是否区分临时/永久，指定了负责人和时限？</li>\n<li>验证部分是否真的验证过（不是计划）？</li></ul>\n<h5>3. 归档动作（让报告\"活起来\"）</h5>\n<ol><li>编号（如 FAE-2026-XXX）→ 入案例库；</li>\n<li>打搜索标签：<b>现象关键词 / 平台 / 型号 / 根因</b>（标签决定 3 个月后能不能被搜到）；</li>\n<li>同步 FAQ：如果这个客诉是高频问题，把标准回答沉淀成 FAQ 条目；</li>\n<li>通知相关人员：涉及研发/质量/销售的关键结论，同步到位并确认收到。</li></ol>\n<h5>4. 复盘四问（每次定稿后 10 分钟做掉）</h5>\n<ol><li>这次报告<b>最难的部分</b>是什么？（数据不够 / 逻辑组织 / 结论拿不准？）</li>\n<li>我<b>卡在哪一步</b>？为什么卡？（信息 / 工具 / 知识？）</li>\n<li>下次同类报告，我能<b>省掉哪一步</b>？（复用什么模板？提前要什么数据？）</li>\n<li>这个教训写进《FA 报告避坑清单》了吗？（不写=白踩坑）</li></ol>\n<h5>5. FA 报告的价值（写给谁看要清楚）</h5>\n<p>客户看结论和可信度、研发看数据和机理、质量看对策和预防、领导看效率和资产——<b>一份报告四个读者</b>，各取所需，你才真的是在\"写报告\"而不是\"交作业\"。</p>\n<div class=\"tip\">💡 好报告的标准：\"结论可以先看，数据可以复查，边界的坦诚让所有人都敢签字。\"</div>"}], "out": "通过评审的 FA 报告 + W10复盘"}]}, {"id": "w11", "badge": "W11", "title": "风险预判与前期支持：新项目导入", "sub": "阶段 P3 · 从\"救火\"到\"防火\"", "accept": "能针对一个拟导入项目输出风险评估清单。", "tools": "QVL、项目进度跟踪表、历史案例库", "phase": "P3", "weekend": "周末加油站：把风险评估清单给导师评审；准备 W12 结业汇报材料；把 12 周成果目录过一遍。 可选：学习\"如何做年终汇报/结业PPT\"技巧", "days": [{"id": "d51", "title": "新项目导入流程学习", "date": "Day 51 · 周一", "dot": "1", "tasks": ["学习新项目导入全流程：需求→选型→样品→测试→认证→量产", "认识 FAE 在新项目中的角色：前期技术支持、风险评估、测试建议", "学习《项目进度跟踪表》字段与用法", "找一个历史\"导入期踩坑\"案例复盘"], "tools": "项目导入SOP、项目进度跟踪表", "resources": [{"type": "vid", "url": "https://www.bilibili.com/video/BV1aW4y1F7y5", "label": "▶ 风险评估报告怎么写（catfish2018 · 6965播放）"}], "lectures": [{"title": "新项目导入：风险评估清单", "html": "<h5>1. FAE 在新项目中的角色（从“救火”到“防火”）</h5>\n<p>在客户选型/导入阶段提前介入，输出<b>“前期技术支持意见 + 测试建议”</b>，把坑提前填掉。导入期发现问题的成本是量产期的十分之一——FAE 前期多花 1 小时，可能省客户 1 周停产。<b>防火者比救火者更值钱</b>，这决定了你是普通 FAE 还是资深 FAE。</p>\n<h5>2. 新项目流程六段（FAE 在每个节点的动作）</h5>\n<table><tr><th>阶段</th><th>FAE 要做什么</th><th>产出物</th></tr>\n<tr><td>需求</td><td>理解客户场景（用途/量级/平台）</td><td>需求澄清清单</td></tr>\n<tr><td>选型</td><td>推荐内存组合 + 风险说明</td><td>选型建议</td></tr>\n<tr><td>样品</td><td>提供样品 + 基础验证</td><td>样品测试记录</td></tr>\n<tr><td>测试</td><td>QVL 覆盖 + 压力/兼容测试</td><td>测试报告</td></tr>\n<tr><td>认证</td><td>配合客户规格书要求（温度/可靠）</td><td>认证支持记录</td></tr>\n<tr><td>量产</td><td>批次监控 + 售后支持准备</td><td>量产 FAQ 前置</td></tr></table>\n<h5>3. 前期调研清单（客户问你要不要支持时先查这些）</h5>\n<ul><li>目标平台：CPU 代际/主板/BIOS 版本——查 QVL 与历史兼容记录；</li>\n<li>客户场景负载：游戏/渲染/服务器 7x24——决定测试方案；</li>\n<li>内存规格预期：容量/频率/时序/电压——对照 JEDEC 与产品成本；</li>\n<li>认证要求：客户规格书里有没有特殊项（温度/ESD/可靠性）；</li>\n<li>量产节奏：什么时候要、量产多少——决定验证窗口。</li></ul>\n<h5>4. 前期支持话术</h5>\n<p>“我们建议在贵司目标平台做一轮 X 测试，预计 Y 天完成，这是为了防止 Z 风险”——管理预期 + 给时间表 + 说清为什么。<b>只说不测是空话，只测不说是失职</b>。</p>\n<div class=\"tip\">💡 记忆锚点：“需求→选型→样品→测试→认证→量产”，FAE 六段都参与才叫项目支持，只在量产期出现叫救火。</div>"}], "out": "项目导入流程图（标注FAE动作）"}, {"id": "d52", "title": "风险维度学习", "date": "Day 52 · 周二", "dot": "2", "tasks": ["学习风险维度：平台兼容、BIOS版本、颗粒组合、散热、频率时序、物料批次", "用历史案例库找出 3 个典型\"新项目风险\"案例", "学习\"提前识别\"方法：对照QVL、查历史相似组合、问研发已知问题", "建立个人《风险维度检查表》"], "tools": "历史案例库、QVL", "resources": [], "lectures": [{"title": "新项目风险维度：提前排雷", "html": "<h5>1. FAE 在新项目中的位置（防火 > 救火）</h5>\n<p>客户选型/导入阶段，FAE 的活儿是<b>提前识别风险</b>，避免量产了才爆雷（那时成本高、口碑差）。一份提前一天的风险清单，价值超过十份事后报告。</p>\n<h5>2. 风险维度检查表（8 个维度起步）</h5>\n<table><tr><th>维度</th><th>具体看什么</th><th>风险信号</th></tr>\n<tr><td>平台兼容</td><td>CPU IMC/Gear、主板 QVL、BIOS 版本</td><td>QVL 无该条、BIOS 太旧</td></tr>\n<tr><td>颗粒组合</td><td>颗粒厂商/位数/单双 Rank、混插风险</td><td>多源颗粒混用、单双 Rank 混插</td></tr>\n<tr><td>频率/时序</td><td>目标档位是否留余量、XMP 依赖</td><td>标称贴着 IMC 上限、必须开 OC</td></tr>\n<tr><td>散热</td><td>机箱风道、马甲、高温降频</td><td>闷箱/无风道/马甲差</td></tr>\n<tr><td>供电</td><td>PMIC、主板内存供电能力</td><td>低端板供电弱、多插条</td></tr>\n<tr><td>物料批次</td><td>投产批次稳定性、变更管理</td><td>颗粒批次变更未通知</td></tr>\n<tr><td>软件生态</td><td>OS/BIOS/驱动兼容</td><td>新 OS、Beta BIOS</td></tr>\n<tr><td>认证要求</td><td>客户规格书特殊要求（温度/可靠性）</td><td>规格超出常规（如宽温）</td></tr></table>\n<h5>3. 风险评估输出格式（一页纸）</h5>\n<pre>\n风险项 / 发生概率（高/中/低） / 影响程度（高/中/低）\n       / 当前状态（已验证OK/需测试确认/未知）\n       / 建议对策（谁负责、何时验证）\n</pre>\n<p>概率 × 影响 = 优先级：高概率高影响 = 立即验证；低概率低影响 = 记录待观察。</p>\n<h5>4. 提前识别的方法</h5>\n<ul><li>对照 QVL 查历史：同平台更过哪些内存？有哪些坑？</li>\n<li>查历史案例库：相似组合出过什么兼容问题？</li>\n<li>问研发已知问题：平台/BIOS 有没有已知内存 bug？</li>\n<li>先小批量试：样品阶段就把高风险项测掉。</li></ul>\n<div class=\"tip\">💡 风险清单不是文件，是思维方式：客户一说“我们要上 X 平台+这条内存”，你脑子里自动开始过 8 个维度——到这种程度才算 FAE。</div>"}], "out": "风险维度检查表（≥8维度）"}, {"id": "d53", "title": "输出风险评估清单", "date": "Day 53 · 周三", "dot": "3", "tasks": ["选定一个拟导入项目（真实或模拟）", "按检查表逐项评估：风险项/概率/影响/对策建议", "区分\"已验证OK\"与\"需测试确认\"两类结论", "输出《风险评估清单》（一页纸版）"], "tools": "风险评估模板、项目资料", "resources": [{"type": "vid", "url": "https://www.bilibili.com/video/BV1aW4y1F7y5", "label": "▶ 风险评估报告怎么写（catfish2018 · 6965播放）"}], "lectures": [{"title": "新项目导入：风险评估清单", "html": "<h5>1. FAE 在新项目中的角色（从“救火”到“防火”）</h5>\n<p>在客户选型/导入阶段提前介入，输出<b>“前期技术支持意见 + 测试建议”</b>，把坑提前填掉。导入期发现问题的成本是量产期的十分之一——FAE 前期多花 1 小时，可能省客户 1 周停产。<b>防火者比救火者更值钱</b>，这决定了你是普通 FAE 还是资深 FAE。</p>\n<h5>2. 新项目流程六段（FAE 在每个节点的动作）</h5>\n<table><tr><th>阶段</th><th>FAE 要做什么</th><th>产出物</th></tr>\n<tr><td>需求</td><td>理解客户场景（用途/量级/平台）</td><td>需求澄清清单</td></tr>\n<tr><td>选型</td><td>推荐内存组合 + 风险说明</td><td>选型建议</td></tr>\n<tr><td>样品</td><td>提供样品 + 基础验证</td><td>样品测试记录</td></tr>\n<tr><td>测试</td><td>QVL 覆盖 + 压力/兼容测试</td><td>测试报告</td></tr>\n<tr><td>认证</td><td>配合客户规格书要求（温度/可靠）</td><td>认证支持记录</td></tr>\n<tr><td>量产</td><td>批次监控 + 售后支持准备</td><td>量产 FAQ 前置</td></tr></table>\n<h5>3. 前期调研清单（客户问你要不要支持时先查这些）</h5>\n<ul><li>目标平台：CPU 代际/主板/BIOS 版本——查 QVL 与历史兼容记录；</li>\n<li>客户场景负载：游戏/渲染/服务器 7x24——决定测试方案；</li>\n<li>内存规格预期：容量/频率/时序/电压——对照 JEDEC 与产品成本；</li>\n<li>认证要求：客户规格书里有没有特殊项（温度/ESD/可靠性）；</li>\n<li>量产节奏：什么时候要、量产多少——决定验证窗口。</li></ul>\n<h5>4. 前期支持话术</h5>\n<p>“我们建议在贵司目标平台做一轮 X 测试，预计 Y 天完成，这是为了防止 Z 风险”——管理预期 + 给时间表 + 说清为什么。<b>只说不测是空话，只测不说是失职</b>。</p>\n<div class=\"tip\">💡 记忆锚点：“需求→选型→样品→测试→认证→量产”，FAE 六段都参与才叫项目支持，只在量产期出现叫救火。</div>"}], "out": "风险评估清单 V1"}, {"id": "d54", "title": "前期技术支持意见 + 测试建议", "date": "Day 54 · 周四", "dot": "4", "tasks": ["基于风险评估输出\"前期技术支持意见\"（选型/平台建议）", "输出\"测试建议\"：QVL覆盖测试、压力测试计划、平台组合矩阵", "与测试/研发确认测试建议可执行", "把意见整理成《项目前期技术支持报告》草稿"], "tools": "测试规范、项目资料", "resources": [], "lectures": [{"title": "前期技术支持意见 + 测试建议", "html": "<h5>1. 输出物结构（前期技术支持意见 + 测试建议）</h5>\n<ol><li><b>选型/平台建议</b>：基于客户场景（游戏/渲染/服务器 7x24/信创）推荐合适的内存组合，写明理由；</li>\n<li><b>风险点说明</b>：高风险项列出证据——历史案例、QVL 缺口、平台已知问题；</li>\n<li><b>测试建议</b>：QVL 覆盖测试、压力测试计划、平台矩阵（Intel/AMD/多代）；</li>\n<li><b>时间表</b>：测试排期、验证节点、风险对策窗口（留出 buffer）。</li></ol>\n<h5>2. 测试建议怎么写才\"有用\"（不是走过场）</h5>\n<ul><li>具体到<b>测什么工具、跑多久、什么平台组合、判据是什么</b>——新人才拿起来就能执行；</li>\n<li>覆盖<b>客户真实负载场景</b>：游戏 = 长时间游戏 + 高负载压测；渲染 = 多线程内存带宽；服务器 = 7x24 稳定性 + ECC（如有）；</li>\n<li>留出<b>边界测试</b>：目标档位超频 +1 档测余量（判断颗粒体质余量）；</li>\n<li>明确<b>PASS/FAIL 判据</b>：MemTest86 多少 Pass、BurnInTest 多久无错、温度上限多少。</li></ul>\n<h5>3. 测试矩阵示例（可直接套用）</h5>\n<table><tr><th>平台</th><th>测试项</th><th>工具</th><th>时长/判据</th></tr>\n<tr><td>Intel 12/13/14代</td><td>开机+基础带宽</td><td>CPU-Z/AIDA64</td><td>频率/时序达标的无报错</td></tr>\n<tr><td>AMD AM4/AM5</td><td>FCLK 稳定性</td><td>AIDA64 压力</td><td>1h 无 WHEA 错误</td></tr>\n<tr><td>目标整机</td><td>长时间稳定性</td><td>MemTest86 + BurnInTest</td><td>MT86 2Pass / BurnIn 8h</td></tr>\n<tr><td>高低温</td><td>温度边界</td><td>高低温箱/HWiNFO</td><td>55℃/85℃ 温区稳定</td></tr></table>\n<h5>4. 与客户沟通：把技术\"翻译\"成人话</h5>\n<p>\"我们建议在贵司目标平台做一轮 X 测试，预计 Y 天完成，这是为了防止 Z 风险\"——<b>管理预期 + 给时间表 + 说清为什么</b>，客户才愿意等。避免只说\"建议测一下\"（客户不知道要多久、为什么、有什么风险）。</p>\n<h5>5. 前期介入的价值（FAE 的\"防火\"思维）</h5>\n<p>在客户选型/导入阶段提前介入，把坑提前填掉：<b>导入期发现问题的成本是量产期的十分之一</b>。FAE 前期多花 1 小时，可能省客户 1 周停产。</p>\n<div class=\"tip\">💡 考核点：能当场输出一份\"具体到工具/时长/判据\"的测试矩阵，而不是泛泛说\"建议压力测试\"——这就是专业度差距。</div>"}], "out": "前期技术支持报告（草稿）"}, {"id": "d55", "title": "项目会参与 + 周复盘", "date": "Day 55 · 周五", "dot": "5", "tasks": ["参加新项目导入会议（如条件允许）", "在会上汇报风险评估要点（练习表达）", "根据反馈更新风险评估清单 V2", "完成《12周计划》W11 验收点打勾 + 周复盘"], "tools": "项目会材料、反馈记录", "resources": [], "lectures": [{"title": "项目会参与：不只是旁听", "html": "<h5>1. 会前准备（决定你能不能在会上有价值）</h5>\n<ul><li><b>读项目资料</b>：需求文档、规格书、历史反馈——至少扫 20 分钟，知道项目在讲什么；</li>\n<li><b>准备 1-2 个技术问题/风险点</b>想主动提出（带着思考上会，不是带着耳朵）；</li>\n<li>明确自己要在会上同步什么（如风险评估要点）——没被点到名也要主动说。</li></ul>\n<h5>2. 会中动作（FAE 不是旁听生）</h5>\n<ul><li><b>记录会议纪要</b>（议题/结论/待办/责任人/期限）——说的就记，别等会后补；</li>\n<li><b>听不懂的术语记下来会后查</b>——30 分钟会你至少能带 2 个问题回来；</li>\n<li>有机会就<b>汇报风险评估</b>（哪怕 2 分钟）——锻炼表达，也让别人看到你的专业；</li>\n<li>观察各方立场：销售关心时间、研发关心数据、生产关心批次——你是连接点；</li>\n<li>被提问不确定的：先记下，说\"我确认后答复\"，别当场编。</li></ul>\n<h5>3. 会后（闭环才算参与）</h5>\n<ul><li>按会议纪要推进自己的待办（当天排进日程）；</li>\n<li>更新《风险评估清单》→ V2（会议信息补进风险项）；</li>\n<li>复盘：这次会上我有没有输出价值？提出过什么？下次怎么更好？</li></ul>\n<h5>4. 项目会上的 FAE 定位</h5>\n<p>你是客户端与技术侧之间的翻译官：帮研发理解客户真实需求，帮客户理解技术边界。<b>会上最有价值的一句话是\"这个风险我建议提前验证，我排了测试 X\"</b>——给建议 + 给动作，而不是只提问题。</p>\n<div class=\"tip\">💡 参会前的自问：我在这条项目线里的角色是什么？这一周我为项目贡献了什么？答不上来 = 还在做\"旁听生\"。</div><h5>5. 会议中暴露问题的处理</h5><ul><li>发现技术风险当场不纠结：记录“风险待确认”会后验证；</li><li>被问到技术不确定项：说“我确认后答复”比当场编强；</li><li>自己负责的待办要大声确认截止时间；</li><li>会后 24h 内发纪要给参会人——这是专业度的体现。</li></ul>"}], "out": "风险评估清单 V2 + 周复盘"}]}, {"id": "w12", "badge": "W12", "title": "综合验收与案例归档：结业汇报", "sub": "阶段 P3 · 12周终点，上岗起点", "accept": "验收清单全部达标（见Sheet五），完成结业汇报。", "tools": "验收清单、案例库、结业PPT", "phase": "P3", "weekend": "🎉 结业周末：正式向深化期冲刺！阅读 M4-M6 深化期计划，与导师确认深化期 KPI 与第一个独立客诉目标。 给自己一个复盘仪式：把 12 周最有成就感的 3 件事写下来，作为下阶段起点", "days": [{"id": "d56", "title": "验收清单逐项自评", "date": "Day 56 · 周一", "dot": "1", "tasks": ["对照《上岗验收清单》逐项自评，标注达标/待补", "不足项制定 48 小时补齐计划", "整理三大交付物：知识笔记/测试证据/案例库", "把自评结果同步导师，请求抽测范围提示"], "tools": "验收清单、12周文档", "resources": [{"type": "vid", "url": "https://www.bilibili.com/video/BV1c7411z7Zt", "label": "▶ 工作型PPT制作入门（Office讲师陈飞 · 2.0万播放）"}, {"type": "vid", "url": "https://www.bilibili.com/video/BV168411H73G", "label": "▶ 文献汇报PPT该怎么做（做科研的大师兄 · 14.0万播放）"}], "lectures": [{"title": "结业验收与汇报：让努力被看见", "html": "<h5>1. 验收清单自评（对照逐项打勾，别只会说\"我学了\"）</h5>\n<p>知识口试 / 实物指认 / XMP 实操 / MT86 判读 / 故障根因 / NTF 证据链 / 客诉闭环 / FA 报告 / 案例库 / 安全规范——每一项都要能拿出<b>证据</b>：口试答对、实操录像、判读报告、闭环案例号。</p>\n<h5>2. 结业汇报结构（一页一主题，数据说话）</h5>\n<ol><li><b>成长历程</b>：起点 → 关键节点 → 现在（2-3 张照片/截图即可，别放流水账）；</li>\n<li><b>能力成果（有证据）</b>：完成 XX 任务 / 独立处理 XX 单客诉 / 产出 XX 篇讲义 FA 报告——全部带数字；</li>\n<li><b>典型案例（1-2 个讲深）</b>：选最有技术含量的一单，按\"现象→排查→根因→对策\"讲透，包含数据；</li>\n<li><b>下一步计划</b>：M4-M6 深化方向 + 具体目标（可量化）。</li></ol>\n<h5>3. 答应领导/导师的\"汇报句式\"</h5>\n<ul><li>\"我解决了 X，靠的是 Y 方法，留下 Z 资产\"——x3 针对三个能力维度各说一次；</li>\n<li>\"这个案例让我学会了...\"——体现成长，不只是做事；</li>\n<li>\"下一步我要补...\"——表现规划能力。</li></ul>\n<h5>4. 汇报技巧（细节决定观感）</h5>\n<ul><li><b>先讲结论再展开</b>：PPT 第一页就有结论，听众不用猜；</li>\n<li>数据可视化：进度条/对比图/时间轴 > 大段文字；</li>\n<li>准备 1 页\"被追问页\"：领导可能问的刁钻问题，答案预先写好（颗粒型号含义？判读步骤？）；</li>\n<li>领导抽测时：<b>会的说透，不会的坦诚 + 给补课计划</b>——硬编答案被拆穿比坦诚更伤。</li></ul>\n<h5>5. 汇报前自测三问</h5>\n<p>① 3 分钟能讲完核心吗（电梯演讲）？② 每个数字都有出处吗？③ 被问到\"你最大失误是什么\"能答好吗？（这道题考察自我认知，别答\"没有\"）</p>\n<div class=\"tip\">💡 汇报不是\"总结过去\"，是\"推销未来\"：让领导相信你 M4-M6 能独立扛事，才拿到深化期的资源。</div>"}], "out": "验收自评表"}, {"id": "d57", "title": "TOP 案例归档 + 知识库更新", "date": "Day 57 · 周二", "dot": "2", "tasks": ["挑选 TOP 案例（≥5例最有价值的）正式归档", "按统一规范：编号/现象/根因/对策/证据路径/搜索标签", "知识库更新：笔记/速查卡/测试模板归位到标准目录", "更新 QVL 与项目进度跟踪表（如有变化）"], "tools": "案例库、知识库目录、QVL", "resources": [], "lectures": [{"title": "案例归档 + 知识库更新：让经验不丢", "html": "<h5>1. 案例库规范（每例 <200 字，只留最可复用的部分）</h5>\n<pre>\n案例编号：FAE-2026-XXX\n现象：<一句话，客户原话>>\n平台：<主板/CPU/OS/内存型号/批次>\n根因：<一句话，能验证的结论>\n证据：<日志/截图路径，指向原始文件>\n对策：<临时+永久>\n教训：<踩过的坑 / 可复用的排查思路>\n状态：<已闭环/复核中>\n</pre>\n<h5>2. 选 TOP 案例的标准（不是所有案例都值得归档）</h5>\n<ul><li><b>有代表性</b>：该故障类型第一次遇到，或同类问题的高频代表；</li>\n<li><b>有完整证据链</b>：现象→排查→根因→验证全链路清晰，能当培训教材；</li>\n<li><b>有教训</b>：自己踩过坑的案例最值钱——把\"当时差点走错的方向\"写进去，比正确路径更有教育意义。</li></ul>\n<h5>3. 案例库组织（检索友好 ≥ 收藏整齐）</h5>\n<ul><li>按<b>故障现象 / 平台 / 内存型号 / 排查方法</b>打标签（检索靠标签，不靠记忆）；</li>\n<li>速查卡归一类、案例归一类、模板归一类——三样东西分开，用时各取所需；</li>\n<li>命名统一：`FAE-2026-XXX_现象关键词`，一眼可扫；</li>\n<li>每月更新一次 QVL 与项目跟踪表（案例中发现的兼容性结论要回流到 QVL）。</li></ul>\n<h5>4. 归档的\"30 秒原则\"</h5>\n<p>客诉闭环当天顺手归档（趁热），别攒到周末——<b>隔了 3 天细节就模糊，隔一周就更不想写了</b>。写不写得好是能力问题，写不写是态度问题。</p>\n<h5>5. 知识库的\"活\"与\"死\"</h5>\n<p>归档只是第一步：<b>每月回访一次</b>——哪些案例被重复问到？说明 FAQ 没覆盖；哪些案例过时了？更新或下架。知识库要像代码一样维护，不是存完就完事。</p>\n<div class=\"tip\">💡 一个好案例 = 未来的你 + 新来的同事 都能 5 分钟看懂并复用。写案例时问自己：\"如果我失忆了，靠这条能恢复这个经验吗？\"</div><h5>5. TOP 案例的“深加工”（不只是存，要能复用）</h5><ul><li><b>选 1 个讲深</b>：把最有代表性的案例写成 1 页分享稿（背景/排查/结论/教训）；</li><li><b>提炼套路</b>：从案例里抽“下次遇到同类怎么走”一条，进排查手册；</li><li><b>设置检索词</b>：给案例加 5-8 个检索标签，3 个月后能一秒找到；</li><li><b>同步 FAQ</b>：如果客户还会问同类问题，FAQ 提前写好。</li></ul>"}], "out": "案例库归档完成（≥5例）"}, {"id": "d58", "title": "结业汇报 PPT 制作", "date": "Day 58 · 周三", "dot": "3", "tasks": ["制作结业汇报 PPT 结构：成长历程→能力成果→典型案例→下一步", "用\"考核表式清爽\"风格：一页一主题、数据可视化", "精选 1-2 个典型案例讲深讲透（含数据）", "写讲稿 / 排练第一遍"], "tools": "PPT模板、案例数据", "resources": [{"type": "vid", "url": "https://www.bilibili.com/video/BV1c7411z7Zt", "label": "▶ 工作型PPT制作入门（Office讲师陈飞 · 2.0万播放）"}, {"type": "vid", "url": "https://www.bilibili.com/video/BV168411H73G", "label": "▶ 文献汇报PPT该怎么做（做科研的大师兄 · 14.0万播放）"}], "lectures": [{"title": "结业验收与汇报：让努力被看见", "html": "<h5>1. 验收清单自评（对照逐项打勾，别只会说\"我学了\"）</h5>\n<p>知识口试 / 实物指认 / XMP 实操 / MT86 判读 / 故障根因 / NTF 证据链 / 客诉闭环 / FA 报告 / 案例库 / 安全规范——每一项都要能拿出<b>证据</b>：口试答对、实操录像、判读报告、闭环案例号。</p>\n<h5>2. 结业汇报结构（一页一主题，数据说话）</h5>\n<ol><li><b>成长历程</b>：起点 → 关键节点 → 现在（2-3 张照片/截图即可，别放流水账）；</li>\n<li><b>能力成果（有证据）</b>：完成 XX 任务 / 独立处理 XX 单客诉 / 产出 XX 篇讲义 FA 报告——全部带数字；</li>\n<li><b>典型案例（1-2 个讲深）</b>：选最有技术含量的一单，按\"现象→排查→根因→对策\"讲透，包含数据；</li>\n<li><b>下一步计划</b>：M4-M6 深化方向 + 具体目标（可量化）。</li></ol>\n<h5>3. 答应领导/导师的\"汇报句式\"</h5>\n<ul><li>\"我解决了 X，靠的是 Y 方法，留下 Z 资产\"——x3 针对三个能力维度各说一次；</li>\n<li>\"这个案例让我学会了...\"——体现成长，不只是做事；</li>\n<li>\"下一步我要补...\"——表现规划能力。</li></ul>\n<h5>4. 汇报技巧（细节决定观感）</h5>\n<ul><li><b>先讲结论再展开</b>：PPT 第一页就有结论，听众不用猜；</li>\n<li>数据可视化：进度条/对比图/时间轴 > 大段文字；</li>\n<li>准备 1 页\"被追问页\"：领导可能问的刁钻问题，答案预先写好（颗粒型号含义？判读步骤？）；</li>\n<li>领导抽测时：<b>会的说透，不会的坦诚 + 给补课计划</b>——硬编答案被拆穿比坦诚更伤。</li></ul>\n<h5>5. 汇报前自测三问</h5>\n<p>① 3 分钟能讲完核心吗（电梯演讲）？② 每个数字都有出处吗？③ 被问到\"你最大失误是什么\"能答好吗？（这道题考察自我认知，别答\"没有\"）</p>\n<div class=\"tip\">💡 汇报不是\"总结过去\"，是\"推销未来\"：让领导相信你 M4-M6 能独立扛事，才拿到深化期的资源。</div>"}], "out": "结业 PPT V1"}, {"id": "d59", "title": "汇报排练 + 自测", "date": "Day 59 · 周四", "dot": "4", "tasks": ["向导师/同事完整排练一次，收集提问", "演练领导可能抽测的问题（口述D4/D5、根因清单、测试判读）", "修改 PPT 与讲稿（控时在 10-15 分钟）", "提前调试会议室设备/备份文件"], "tools": "排练反馈、抽测题库", "resources": [{"type": "vid", "url": "https://www.bilibili.com/video/BV1c7411z7Zt", "label": "▶ 工作型PPT制作入门（Office讲师陈飞 · 2.0万播放）"}, {"type": "vid", "url": "https://www.bilibili.com/video/BV168411H73G", "label": "▶ 文献汇报PPT该怎么做（做科研的大师兄 · 14.0万播放）"}], "lectures": [{"title": "结业验收与汇报：让努力被看见", "html": "<h5>1. 验收清单自评（对照逐项打勾，别只会说\"我学了\"）</h5>\n<p>知识口试 / 实物指认 / XMP 实操 / MT86 判读 / 故障根因 / NTF 证据链 / 客诉闭环 / FA 报告 / 案例库 / 安全规范——每一项都要能拿出<b>证据</b>：口试答对、实操录像、判读报告、闭环案例号。</p>\n<h5>2. 结业汇报结构（一页一主题，数据说话）</h5>\n<ol><li><b>成长历程</b>：起点 → 关键节点 → 现在（2-3 张照片/截图即可，别放流水账）；</li>\n<li><b>能力成果（有证据）</b>：完成 XX 任务 / 独立处理 XX 单客诉 / 产出 XX 篇讲义 FA 报告——全部带数字；</li>\n<li><b>典型案例（1-2 个讲深）</b>：选最有技术含量的一单，按\"现象→排查→根因→对策\"讲透，包含数据；</li>\n<li><b>下一步计划</b>：M4-M6 深化方向 + 具体目标（可量化）。</li></ol>\n<h5>3. 答应领导/导师的\"汇报句式\"</h5>\n<ul><li>\"我解决了 X，靠的是 Y 方法，留下 Z 资产\"——x3 针对三个能力维度各说一次；</li>\n<li>\"这个案例让我学会了...\"——体现成长，不只是做事；</li>\n<li>\"下一步我要补...\"——表现规划能力。</li></ul>\n<h5>4. 汇报技巧（细节决定观感）</h5>\n<ul><li><b>先讲结论再展开</b>：PPT 第一页就有结论，听众不用猜；</li>\n<li>数据可视化：进度条/对比图/时间轴 > 大段文字；</li>\n<li>准备 1 页\"被追问页\"：领导可能问的刁钻问题，答案预先写好（颗粒型号含义？判读步骤？）；</li>\n<li>领导抽测时：<b>会的说透，不会的坦诚 + 给补课计划</b>——硬编答案被拆穿比坦诚更伤。</li></ul>\n<h5>5. 汇报前自测三问</h5>\n<p>① 3 分钟能讲完核心吗（电梯演讲）？② 每个数字都有出处吗？③ 被问到\"你最大失误是什么\"能答好吗？（这道题考察自我认知，别答\"没有\"）</p>\n<div class=\"tip\">💡 汇报不是\"总结过去\"，是\"推销未来\"：让领导相信你 M4-M6 能独立扛事，才拿到深化期的资源。</div>"}], "out": "结业 PPT V2 + 排练记录"}, {"id": "d60", "title": "结业汇报 + 验收通过", "date": "Day 60 · 周五", "dot": "5", "tasks": ["完成结业汇报（领导/团队面前）", "通过验收清单全部达标（领导确认）", "输出 12 周复盘总结 + 下阶段计划（M4-M6）", "感谢导师/团队，同步 M4-M6 目标"], "tools": "验收清单、结业PPT、下阶段计划", "resources": [{"type": "vid", "url": "https://www.bilibili.com/video/BV1c7411z7Zt", "label": "▶ 工作型PPT制作入门（Office讲师陈飞 · 2.0万播放）"}, {"type": "vid", "url": "https://www.bilibili.com/video/BV168411H73G", "label": "▶ 文献汇报PPT该怎么做（做科研的大师兄 · 14.0万播放）"}], "lectures": [{"title": "结业验收与汇报：让努力被看见", "html": "<h5>1. 验收清单自评（对照逐项打勾，别只会说\"我学了\"）</h5>\n<p>知识口试 / 实物指认 / XMP 实操 / MT86 判读 / 故障根因 / NTF 证据链 / 客诉闭环 / FA 报告 / 案例库 / 安全规范——每一项都要能拿出<b>证据</b>：口试答对、实操录像、判读报告、闭环案例号。</p>\n<h5>2. 结业汇报结构（一页一主题，数据说话）</h5>\n<ol><li><b>成长历程</b>：起点 → 关键节点 → 现在（2-3 张照片/截图即可，别放流水账）；</li>\n<li><b>能力成果（有证据）</b>：完成 XX 任务 / 独立处理 XX 单客诉 / 产出 XX 篇讲义 FA 报告——全部带数字；</li>\n<li><b>典型案例（1-2 个讲深）</b>：选最有技术含量的一单，按\"现象→排查→根因→对策\"讲透，包含数据；</li>\n<li><b>下一步计划</b>：M4-M6 深化方向 + 具体目标（可量化）。</li></ol>\n<h5>3. 答应领导/导师的\"汇报句式\"</h5>\n<ul><li>\"我解决了 X，靠的是 Y 方法，留下 Z 资产\"——x3 针对三个能力维度各说一次；</li>\n<li>\"这个案例让我学会了...\"——体现成长，不只是做事；</li>\n<li>\"下一步我要补...\"——表现规划能力。</li></ul>\n<h5>4. 汇报技巧（细节决定观感）</h5>\n<ul><li><b>先讲结论再展开</b>：PPT 第一页就有结论，听众不用猜；</li>\n<li>数据可视化：进度条/对比图/时间轴 > 大段文字；</li>\n<li>准备 1 页\"被追问页\"：领导可能问的刁钻问题，答案预先写好（颗粒型号含义？判读步骤？）；</li>\n<li>领导抽测时：<b>会的说透，不会的坦诚 + 给补课计划</b>——硬编答案被拆穿比坦诚更伤。</li></ul>\n<h5>5. 汇报前自测三问</h5>\n<p>① 3 分钟能讲完核心吗（电梯演讲）？② 每个数字都有出处吗？③ 被问到\"你最大失误是什么\"能答好吗？（这道题考察自我认知，别答\"没有\"）</p>\n<div class=\"tip\">💡 汇报不是\"总结过去\"，是\"推销未来\"：让领导相信你 M4-M6 能独立扛事，才拿到深化期的资源。</div>"}], "out": "结业汇报完成 + 验收通过记录"}]}, {"id": "m4", "badge": "M4", "title": "深化期第一月：独立承接常规业务", "sub": "在岗深化 · 把 12 周所学变成日常生产力", "accept": "独立承接常规客诉业务，闭环效率与准确率达标。", "tools": "维护QVL/案例库、跟踪每个客诉全流程、周度效率复盘", "phase": "M", "weekend": "", "days": [{"id": "d61", "title": "独立接单周（第1-2周）", "date": "M4 月初", "dot": "1", "tasks": ["独立承接 2-3 单常规客诉（不再依赖导师默认）", "每单走全流程：信息收集→排查→对策→闭环→归档", "建立个人客诉效率基线：首响时间/闭环周期/一次判准率", "每周五做客诉效率复盘，找出耗时环节"], "tools": "客户支持流程SOP、客诉跟踪表", "resources": [], "lectures": [{"title": "M4 独立接单：从跟跑到独跑", "html": "<h5>1. 独立 vs 跟单的差别（心态先转过来）</h5>\n<p>跟单时导师兜底，独立时<b>你要对结果负责</b>。差别在三个维度：<b>主动信息收集</b>（没人提醒你问全）、<b>自主排期</b>（没人帮你定 deadline）、<b>对外沟通</b>（客户直接找你）。第一单独立最慌——正常，慌说明你知道要负责了。</p>\n<h5>2. 独立接单 SOP（照做不迷路）</h5>\n<ol><li>接单登记（客诉单全字段——信息不全当场补齐）；</li>\n<li>信息收集模板发客户（一次问全，避免挤牙膏式追问）；</li>\n<li>建立个人跟进表（进度/下一步/截止日期）；</li>\n<li>每 1-2 天同步销售/客户（哪怕只说\"正在验证 X，预计 Y\"）；</li>\n<li>排查→对策→验证→闭环→归档（走完八步闭环，不跳步）。</li></ol>\n<h5>3. 效率基线（从第一单开始记录）</h5>\n<p>记录四个指标：<b>首响时间</b>（接单到第一次回复）、<b>信息收集耗时</b>、<b>闭环周期</b>（接单到结案）、<b>一次判准率</b>（初判方向被验证的比例）。一个月后看趋势——你就知道自己的瓶颈在信息收集、测试还是沟通。</p>\n<h5>4. 独立接单的沟通原则</h5>\n<ul><li>定期主动同步，不让客户追着问（主动=专业）；</li>\n<li>结论前先给\"已确认的信息+下一步\"——客户要的是确定性；</li>\n<li>内部该问就问：带着\"我已查到哪、卡在哪\"去问导师/研发，而不是空手问。</li></ul>\n<div class=\"warn\">⚠️ 独立≠单干：拿不准的该找导师/研发就问，但带着\"我已查到哪、卡在哪\"去问，而不是空手问。独立是承担责任，不是拒绝协作。</div>\n<div class=\"tip\">💡 第一单的\"第 0 步\"最重要：信息收集表发出去 + 跟进表建好——这两件事做完，单子已经稳了一半。</div><h5>5. 首单最容易犯的 3 个错（提前避坑）</h5><ul><li><b>不建跟进表</b>：全靠记忆 → 忘同步/漏动作 → 客户不满；</li><li><b>信息不全就上手测</b>：先问全再测，别测完才发现方向错；</li><li><b>不敢同步坏消息</b>：进展卡住也要说“卡在 X，正在 Y”，比沉默强。</li></ul><p>每次独立接单后对照这 3 条复盘，1-2 单后就顺了。</p>"}], "out": "客诉效率基线表 + ≥3单闭环记录"}, {"id": "d62", "title": "QVL 与案例库维护（第3周）", "date": "M4 月中", "dot": "2", "tasks": ["按新平台/新BIOS版本维护 QVL 表（每月更新）", "案例库新增 ≥2例/月，覆盖不同故障类型", "把\"可复用的排查套路\"提炼进标准化手册草稿", "向团队同步一次本月知识点（10分钟小分享）"], "tools": "QVL、案例库、知识库", "resources": [{"type": "vid", "url": "https://www.bilibili.com/video/BV1VhnF6yEDQ", "label": "▶ 爆肝测试100套组合·内存不兼容原因（和微论件 · 11.2万播放）"}, {"type": "vid", "url": "https://www.bilibili.com/video/BV1ua411L78Y", "label": "▶ 内存条兼容性·玄学问题（ZoveyChen · 11.8万播放）"}, {"type": "off", "url": "https://www.asus.com/support/", "label": "📄 华硕内存支持(QVL)"}, {"type": "off", "url": "https://www.msi.com/support", "label": "📄 微星内存支持列表"}], "lectures": [{"title": "QVL 解读：怎么查、怎么看、边界在哪", "html": "<h5>1. QVL 是什么（内存合格供应商清单）</h5>\n<p>QVL（Qualified Vendor List）＝主板厂商测试认证过的内存型号清单，通常以 Excel/网页形式提供，按型号/颗粒/容量/频率/状态列出。<b>QVL 是兼容性客诉的第一参考</b>：客户买的条子不在 QVL 里，就要解释“没认证≠不能用，但风险更高”。</p>\n<h5>2. QVL 表格各列怎么读</h5>\n<table><tr><th>列</th><th>含义</th><th>FAE 看什么</th></tr>\n<tr><td>Vendor/厂商</td><td>内存品牌/模组厂</td><td>是否常在合作名录</td></tr>\n<tr><td>Part Number</td><td>模组型号（PN）</td><td>与客户条子标签完全一致</td></tr>\n<tr><td>Capacity/容量</td><td>单条容量</td><td>8/16/32 是否匹配</td></tr>\n<tr><td>Frequency/速率</td><td>标称频率档（含 XMP）</td><td>注意 JEDEC vs XMP 档</td></tr>\n<tr><td>Timing/时序</td><td>标称时序</td><td>对比客户实际跑的</td></tr>\n<tr><td>Status/状态</td><td>Verified/Tested 等</td><td>“已验证” vs “待验证”差异</td></tr></table>\n<h5>3. 怎么查 QVL（三个入口）</h5>\n<ul><li>主板官网支持页 → 内存/兼容性列表；</li>\n<li>华硕：ASUS 官网按主板型号搜 “Memory QVL”；</li>\n<li>微星：MSI 官网 → 支持 → 兼容性报告；</li>\n<li>整机厂（联想/戴尔等）→ 服务支持 → 内存兼容列表（整机指定型号更严）。</li></ul>\n<h5>4. 边界与话术（不在 QVL ≠ 不能用）</h5>\n<p>QVL 是主板厂<b>测过的样本</b>，不是“唯一可用清单”：新出的条子可能还没测到。FAE 话术：</p>\n<ul><li>“该型号暂未在 QVL 中，属于未验证状态，建议先做一轮兼容性测试”</li>\n<li>“QVL 内型号更稳，若量产建议选 QVL 型号降低风险”</li>\n<li>“不在 QVL ≠ 不兼容，但出了问题风险自担，我们可协助测试验证”</li></ul>\n<h5>5. QVL 的三个坑</h5>\n<ul><li>只看容量不看颗粒/版本（同 PN 不同颗粒批次可能行为不同）；</li>\n<li>把 XMP 档当成 JEDEC 保证（XMP 超频不保证）；</li>\n<li>拿别的厂商 QVL 当本厂（每家的测试条件不同）。</li></ul>\n<div class=\"tip\">💡 QVL 客诉三连问：条子在不在名单？在 → 按名单配置核对；不在 → 未验证风险说明 + 协助测试；在但有问题 → 走兼容性深入排查。</div>"}, {"title": "案例库：让每一单客诉都变成资产", "html": "<h5>1. 案例库是什么（FAE 最值钱的个人资产）</h5>\n<p>案例库 = 把每一单客诉的\"现象/根因/对策/验证\"沉淀成可检索的记录。它是 FAE 最值钱的个人资产：<b>案例越多，排查越快，答辩越有底气</b>。面试/晋升时，「你处理过哪些案例、怎么处理的」比任何证书都有说服力。</p>\n<h5>2. 每例 <200 字的推荐格式（精简到可复用）</h5>\n<pre>\n案例编号：FAE-2026-XXX\n现象：一句话（客户视角）\n平台：主板/CPU/OS/内存型号\n根因：一句话（可验证）\n证据：日志/截图路径\n对策：临时 + 永久\n状态：已闭环/复核中\n</pre>\n<h5>3. 什么案例值得记（不是所有都记）</h5>\n<ul><li>第一次遇到的故障类型（新增认知）；</li>\n<li>排查过程走弯路的（<b>教训最值钱</b>——把\"当时差点往错误方向走\"写进去）；</li>\n<li>证据链完整、能当培训材料的（可分享给新人）；</li>\n<li>客户高频问题（同问必记——直接进 FAQ）。</li></ul>\n<h5>4. 归档节奏（别攒，顺手就记）</h5>\n<ul><li>客诉闭环当天顺手记一例（30 秒的事，趁热写细节才清楚）；</li>\n<li>月底统一补标签和索引（现象/平台/方法三类标签）；</li>\n<li>目标：<b>12 周 ≥10 例，一年 ≥30 例</b>——数字不到就说明你复盘不够；</li>\n<li>定期回访：哪些案例被反复问到？说明 FAQ 没覆盖；哪些过时了？更新或下架。</li></ul>\n<div class=\"tip\">💡 考核要求\"建立案例库 ≥10 例\"——现在每天闭环一单就入库，到 W12 自然达标。写案例时问自己：\"如果我失忆了，靠这条能恢复这个经验吗？\"</div><h5>5. 案例库的进阶用法（从记录到武器库）</h5><ul><li><b>检索标签体系</b>：现象关键词 + 平台 + 内存型号 + 方法——3 个月后还能搜到才是好归档；</li><li><b>案例反哺</b>：同类型案例 ≥3 个 → 提炼成 FAQ/排查手册章节；</li><li><b>年度盘点</b>：年底挑 TOP 案例做内部分享/晋升素材；</li><li><b>新人培训</b>：给新人读 3 个案例再讲出来，比讲 3 小时 PPT 有效。</li></ul>"}], "out": "QVL更新记录 + 案例库增量 + 小分享记录"}, {"id": "d63", "title": "疑难客诉预备（第4周）", "date": "M4 月末", "dot": "3", "tasks": ["识别手头\"疑似NTF\"案例，按 NTF 方法论重新过一遍", "学习疑难案例的升级路径：什么时候上报导师/研发", "月度总结：本月经手客诉全景复盘 + M5 目标制定", "完成 M4 验收：独立承接常规业务、闭环效率达标"], "tools": "NTF方法论、月度复盘模板", "resources": [{"type": "vid", "url": "https://www.bilibili.com/video/BV1PYkrBcE9H", "label": "▶ 如何高情商处理客户投诉（海纳集团视频号 · 7031播放）"}, {"type": "vid", "url": "https://www.bilibili.com/video/BV19b4y1d7rg", "label": "▶ 处理顾客投诉五步曲（梁老师889 · 2032播放）"}], "lectures": [{"title": "客诉处理：从接单到闭环", "html": "<h5>1. 八步闭环（每一步都要有产出物）</h5>\n<p><b>信息收集→初判分级→复现测试→根因分析→临时对策→根因对策→验证→归档</b>。不要跳步：客户催得急也要把证据链走完，否则后患无穷。</p>\n<table><tr><th>步骤</th><th>关键动作</th><th>产出物</th></tr>\n<tr><td>①信息收集</td><td>按模板问全：机型/平台/BIOS/内存型号/现象/概率/环境/操作</td><td>信息收集表（一次问全）</td></tr>\n<tr><td>②初判分级</td><td>判断停线/重大/常规，定响应时效</td><td>问题分级 + 响应节点</td></tr>\n<tr><td>③复现测试</td><td>客户环境复现 + 本司平台复现（MemTest86/BurnInTest）</td><td>复现记录（截图/日志/视频）</td></tr>\n<tr><td>④根因分析</td><td>最小化/交叉替换/批次比对/电气测量，锁定层级</td><td>根因假设 + 证据</td></tr>\n<tr><td>⑤临时对策</td><td>先给客户能用的：换槽/降频/单条/关XMP</td><td>临时对策单</td></tr>\n<tr><td>⑥根因对策</td><td>联动研发/质量：换货/固件/工艺/来料管控</td><td>永久对策 + 责任方</td></tr>\n<tr><td>⑦验证</td><td>对策有效性验证（复测通过 + 客户确认）</td><td>验证报告</td></tr>\n<tr><td>⑧归档</td><td>编号入案例库，写清现象→根因→对策→可复用的排查思路</td><td>案例库条目</td></tr></table>\n<h5>2. 分级与响应时效（先响应，再解决）</h5>\n<ul><li><b>产线停线</b>：最高级，1 小时内响应，电话 + 群同步，24h 内给临时对策；</li>\n<li><b>客户升级/大客户</b>：当日响应，48h 内给初步结论；</li>\n<li><b>常规单</b>：1 个工作日内响应。</li></ul>\n<p>第一时间回复<b>\"已收到，正在排查，预计 X 时间给结论\"</b>——不是等有结论才回。客户的焦虑来自沉默，回复=\\\"确定性缓冲\\\"。</p>\n<h5>3. 客诉单要填的字段（对照你的模板逐一确认）</h5>\n<p>客户/机型/平台/BIOS版本/内存型号与SN/数量/故障现象（原话）/出现概率（必现/偶发/频率）/触发条件（开机/压力/冷机/热机）/环境（温度/电压/机箱风道）/客户期望（退货/换货/分析报告/赔偿）/紧急度。缺字段=后面必返工。</p>\n<h5>4. 临时对策 vs 永久对策（边界要分清）</h5>\n<p>临时对策是<b>给客户先能用</b>：换槽/降频/单条/关 XMP/清 CMOS；永久对策是<b>消除根因</b>：换货/固件/工艺/来料管控。\"权宜可用 ≠ 根因解决\"——临时对策单上要写清适用范围与有效期，避免客户把临时当永久。</p>\n<h5>5. 内部协同与对外口径</h5>\n<p>FAE 是窗口：销售/研发/客户三方信息都从你这里对齐。<b>对外口径统一</b>，别在客户群里互相矛盾——不确定的事先内部确认再回复；同时把客户的原始诉求完整带回内部（含情绪、期望、决策人）。</p>\n<h5>6. 客户预期管理话术（背熟直接可用）</h5>\n<ul><li>催结果：\"根因还在交叉验证，我先把已确认的部分同步给您，预计 X 确认完整结论\"；</li>\n<li>想退货：\"换货流程已启动，同时我建议先试临时对策避免影响生产，两条线并行\"；</li>\n<li>质疑结论：\"我用了 A/B 交叉和压力测试，数据如下...如果还有疑虑我们可以一起复现\"。</li></ul>\n<div class=\"tip\">💡 考核/面试点：能说出\"八步闭环\"还不够，要能随手举出每一\"步的产出物——纸上写不出来的流程不叫会。</div>"}, {"title": "疑难案例升级路径：什么时候上报", "html": "<h5>1. 升级的判断标准（满足任一条就升级，不要硬扛）</h5>\n<ul><li><b>时间红线</b>：超过 3 个工作日仍无法收敛方向；</li>\n<li><b>批量风险</b>：同一批次/同型号多根不良反应（不是孤例，可能是产线/物料问题）；</li>\n<li><b>客户升级/产线停线</b>：紧急度拉满，单靠 FAE 节奏不够；</li>\n<li><b>超出装备能力</b>：需要示波器/ATE/失效分析（FA）设备才能推进；</li>\n<li><b>结论影响大</b>：可能要判赔/退货/改设计，需要领导/研发拍板。</li></ul>\n<h5>2. 升级不等于认怂——是\"项目化推进\"</h5>\n<p>把疑难案例当作一个小项目管理：<b>目标（定位根因）/ 里程碑（每周结论）/ 资源（需要谁）/ 风险（卡在哪）</b>。升级 = 向组织申请资源，不是把问题甩出去。</p>\n<h5>3. 上报前的\"三句话\"准备（先说清楚再去敲门）</h5>\n<ol><li><b>已查到哪</b>：现象/平台/复现条件/已排除项（证明你做过功课）；</li>\n<li><b>卡在哪</b>：是信息不全？设备不够？还是结论互相矛盾？</li>\n<li><b>需要什么支持</b>：研发看板子？FA 做切片？还是客户补测？</li></ol>\n<p>带上<b>证据包</b>（日志/截图/复现视频/交叉替换表）再找研发/导师——空手求助和带料求助，得到的响应完全不同。</p>\n<h5>4. 升级流程动作规范</h5>\n<ol><li>同步销售 + 客户进展节奏（升级了 ≠ 通知变少，恰恰要更勤）；</li>\n<li>建立<b>升级单/疑难清单</b>，写明负责人、卡点、需要的支持、承诺时间；</li>\n<li>每周滚动更新状态，即使没有新进展也写上\"本周验证了 X 排除 Y\"；</li>\n<li>闭环后反向沉淀：升级卡点 → 进《疑难案例清单》，防止下次重复卡。</li></ol>\n<h5>5. 跟研发协作的话术</h5>\n<ul><li>\"我已经做了 X 和 Y 排除，现在剩 Z 需要您这边帮看\"（带已查记录）；</li>\n<li>\"客户现场可配合复现，时间您定，我协调\"（降低对方协作成本）；</li>\n<li>\"这个现象和您之前看过的 A 案例像，我对比了数据...\"（用研发语言沟通）。</li></ul>\n<div class=\"tip\">💡 判断升级时机的口诀：\"三天没进展、批量有风险、客户在升级、装备不够用\"——四条占一条就启动升级流程。</div>"}], "out": "M4 月报 + 疑难案例清单"}]}, {"id": "m5", "badge": "M5", "title": "深化期第二月：主导 NTF 与疑难闭环", "sub": "在岗深化 · 啃最硬的骨头", "accept": "主导 1 个以上疑难 NTF 闭环，输出完整证据链。", "tools": "疑难案例牵头、跨部门协调、NTF方法论实战、结论可复现", "phase": "M", "weekend": "", "days": [{"id": "d64", "title": "NTF 主导周（第1-2周）", "date": "M5 月初", "dot": "1", "tasks": ["认领 1 个疑难/NTF 案例，担任主导人", "搭建完整复现环境；设计压力复测/场景复现方案", "交叉验证 + 批次/版本对比，逐步缩小范围", "保持与销售/客户/研发的节奏同步"], "tools": "NTF方法论、复现实验模板、版本/批次对照表", "resources": [{"type": "vid", "url": "https://www.bilibili.com/video/BV1gaFez8EFT", "label": "▶ 电脑不定时死机卡住重启怎么办（程工修笔记本 · 5683播放）"}], "lectures": [{"title": "NTF 方法论：找不到故障时的破案纪律", "html": "<h5>1. 什么是 NTF 以及为什么存在</h5>\n<p>NTF（No Trouble Found）＝客户报告故障，但标准流程<b>测不出/复现不了</b>。常见原因：环境相关、偶发硬件（温度/时序临界）、软件/驱动被误归为内存。<b>NTF 不是“客户错”的信号，是“现有方法不够”的信号</b>。</p>\n<h5>2. NTF 方法论五板斧（破案纪律）</h5>\n<ol><li><b>交叉验证</b>：换人/换机/换工具，排除操作和设备误差（先确认不是自己测错）；</li>\n<li><b>复现环境搭建</b>：还原客户条件（同平台/同负载/同温度）——不还原就永远复现不了；</li>\n<li><b>压力复测</b>：延长时间、提高温度、加大负载——临界问题在压力下显形；</li>\n<li><b>批次对比</b>：同型号不同批次交叉测，看是不是批次性问题；</li>\n<li><b>版本比对</b>：BIOS/驱动/固件版本前后对比，排除软件引入。</li></ol>\n<h5>3. 每板斧的执行标准（不是口号）</h5>\n<table><tr><th>板斧</th><th>怎么做</th><th>产出证据</th></tr>\n<tr><td>交叉</td><td>两人独立同条件测</td><td>双份独立日志</td></tr>\n<tr><td>复现</td><td>环境表：平台/负载/温度/操作</td><td>复现记录</td></tr>\n<tr><td>复测</td><td>≥24h 长测 + 高温（55/85℃）</td><td>时长/温度/错误数</td></tr>\n<tr><td>批次</td><td>同规格不同批号各取样品</td><td>批次-结果对照</td></tr>\n<tr><td>版本</td><td>新老 BIOS/驱动对照</td><td>版本-现象对照</td></tr></table>\n<h5>4. NTF 报告的结构（证据链完整才算闭环）</h5>\n<ol><li>客户反馈原话（现象/条件/概率）；</li>\n<li>复现尝试记录（方法/时长/结果）；</li>\n<li>五板斧结果表（都做了哪些、各什么结论）；</li>\n<li>结论与边界：在 X 条件下未复现；可能方向 Y；建议 Z（更换/监控/加严测试）；</li>\n<li>后续动作：持续性监控、客户侧日志收集、案例归档。</li></ol>\n<h5>5. 心态（NTF 是 FAE 的成人礼）</h5>\n<ul><li>客户报“有问题”你没复现 → 不是客户错，是条件没还原；</li>\n<li>不要编“可能没问题”硬结案 → 说“未复现+边界”；</li>\n<li>NTF 处理得好 = 释放专业性：透明度、方法、边界，客户看在眼里。</li></ul>\n<div class=\"tip\">💡 NTF 的破案纪律：先排除自己 → 再还原条件 → 加压等它显形 → 用对比安证据 → 边界说清楚。五板斧走完，NTF 不再是黑箱。</div>"}, {"title": "NTF 专项：从\"复现不了\"到\"证据链完整\"", "html": "<h5>1. NTF 是什么（No Trouble Found / 无法复现）</h5>\n<p>NTF = 客户报告了故障，但按标准流程测不出来/复现不了。字面“没找到问题”，实质是<b>“现有方法抓不到，需要换思路”</b>。FAE 面对 NTF 的第一心态：不是“客户胡说”，而是“我还没找到方法”。</p>\n<h5>2. NTF 的三大来源</h5>\n<ul><li><b>环境相关</b>：客户侧温度/供电/负载波动，测试环境太干净；</li>\n<li><b>偶发硬件</b>：临界失效（时序边界/虚焊/颗粒退化）只在特定条件出错；</li>\n<li><b>软件/驱动</b>：系统层问题被误报为内存问题（测内存反而正常）。</li></ul>\n<h5>3. NTF 五板斧（方法论骨架）</h5>\n<ol><li><b>交叉验证</b>：换人换机换工具，排除操作/设备误差；</li>\n<li><b>复现环境搭建</b>：按客户条件还原（温度/负载/软件）；</li>\n<li><b>压力复测</b>：加时间加强度（长测/高低温/大负载）；</li>\n<li><b>批次对比</b>：同批次不同批次的条子对比，看是否是批次性问题；</li>\n<li><b>版本比对</b>：BIOS/驱动/固件版本前后对比，排除软件引入。</li></ol>\n<h5>4. 每板斧的证据产出</h5>\n<table><tr><th>板斧</th><th>做什么</th><th>证据</th></tr>\n<tr><td>交叉验证</td><td>同条件双人复测</td><td>两份独立日志</td></tr>\n<tr><td>复现环境</td><td>还原客户条件</td><td>环境记录表 + 结果</td></tr>\n<tr><td>压力复测</td><td>24h 长测 + 高温</td><td>时长/温度/错误数</td></tr>\n<tr><td>批次对比</td><td>同规格不同批</td><td>批次号 + 各自结果</td></tr>\n<tr><td>版本比对</td><td>新老版本对比</td><td>版本列表 + 现象变化</td></tr></table>\n<h5>5. 心态与沟通</h5>\n<ul><li>NTF ≠ 客户撒谎：先默认“有效反馈”，用数据找答案；</li>\n<li>给客户的同步：“我们正在用 X 方法复现，目前测了 N 小时无异常，已加严到 Y 条件”——透明度是关键；</li>\n<li>真闭不了环：明确“未复现 + 建议措施”（更换/持续监控），不编结论。</li></ul>\n<div class=\"tip\">💡 NTF 的终极答案不是“没问题”，而是“在什么条件下没问题、什么条件下可能有问题”——把边界说清楚，就是专业闭环。</div>"}], "out": "NTF 主导记录 + 阶段性证据"}, {"id": "d65", "title": "疑难闭环周（第3-4周）", "date": "M5 月中", "dot": "2", "tasks": ["收敛结论：真不良/假性不良/人为/环境，证据链完整", "输出 NTF 报告（如涉及FA，按FA模板出报告）", "主导跨部门确认：研发/测试/PQE/生产对结论认同", "闭环后复盘：方法论哪些环节最有效、哪些要优化"], "tools": "FA/NTF报告模板、跨部门协同SOP", "resources": [], "lectures": [{"title": "M5 NTF 主导：把\"疑难\"变成\"可解释\"", "html": "<h5>1. 主导者的责任（你首先是项目负责人）</h5>\n<p>疑难/NTF 案例的主导人 = 项目负责人：<b>定义问题、安排实验、协调研发/测试/PQE、对客户交代</b>。你不是\"跑测试的\"，你是\"推进闭环的\"——测试只是手段，闭环才是目标。</p>\n<h5>2. 闭环周节奏（4 周标准节奏，可并行）</h5>\n<ul><li><b>第1周</b>：问题定义 + 复现环境搭建 → 跑复测（先确认能不能复现，不能复现进 NTF 流程）；</li>\n<li><b>第2周</b>：交叉验证 + 批次/版本对比 → 缩小范围（收集证据）；</li>\n<li><b>第3周</b>：写 NTF 报告/FA 报告（证据链完整：现象→实验→结论）；</li>\n<li><b>第4周</b>：跨部门确认结论 → 客户沟通 → 闭环复盘（沉淀经验）。</li></ul>\n<h5>3. 跨部门协调要点（每个部门要的东西不一样）</h5>\n<ul><li>给<b>研发</b>的是\"可定位的线索\"：电压异常曲线、特定地址报错、复现步骤——不是\"它坏了\"；</li>\n<li>给<b>测试</b>的是\"明确实验条件\"：工具（MT86/BurnInTest）、参数（内存占比/时长）、环境（温度）；</li>\n<li>给 <b>PQE</b> 的是\"判定依据\"：规格书条款、批次数据、检验记录；</li>\n<li>保持一张<b>问题状态表</b>全员可见：当前假设/已排除/待验证/负责人——避免各做各的。</li></ul>\n<h5>4. 主导者的工作习惯</h5>\n<ul><li>每天更新状态表（哪怕只写\"今天验证了 X 排除 Y\"）；</li>\n<li>每周给客户/销售一次确定性同步（进展 + 下一步 + 预期时间）；</li>\n<li>结论不确定时明确说\"还在验证 X\"，不编进度；</li>\n<li>证据链不全不闭环——NTF 最大的敌人是\"没法解释\"，而唯一解药是证据。</li></ul>\n<div class=\"tip\">💡 主导疑难案例，你和\"跟跑\"最大的区别：跟跑等安排，主导排安排。一个 4 周闭环做下来，你的项目管理和跨部门能力会明显上一个台阶。</div><h5>5. 主导 NT 后的复盘动作</h5><ol><li>复盘卡点：哪一步最耗时？是复现、证据还是协调？</li><li>把新方法回填《排查手册》/FAQ（沉淀资产）；</li><li>把案例讲给团队（内部分享 15 分钟）；</li><li>记录“下一次我可以更快做什么”——经验要转成流程。</li></ol>"}], "out": "NTF闭环报告 1 份（含证据链）"}, {"id": "d66", "title": "方法论沉淀（月末）", "date": "M5 月末", "dot": "3", "tasks": ["把 NTF 闭环中的新套路写进《标准化排查手册》", "FAQ 新增 2-3 条（来自本月的客户高频问题）", "月度复盘：疑难案例带给我什么新能力", "完成 M5 验收：NTF 主导闭环 + 准确率达标"], "tools": "排查手册、FAQ、月报模板", "resources": [], "lectures": [{"title": "M5 方法论沉淀：从解决一个问题到解决一类问题", "html": "<h5>1. 为什么要沉淀（从\"会做\"到\"会教\"）</h5>\n<p>一个人解决 10 个问题不算强，把 10 个问题的方法变成可复用的套路才算。沉淀物 = 别人照做也能 80% 复现你的思路。这也是 FAE 从执行者到专家的分水岭：<b>你能解决多少问题，是你的极限；你能让多少人解决多少问题，是你的资产</b>。</p>\n<h5>2. 沉淀产品（三类，缺一不可）</h5>\n<ul><li><b>排查手册</b>：故障映射表升级、路径图更新、新增案例分支（积累的案例要回流到方法里）；</li>\n<li><b>FAQ</b>：把本月的客户高频 Q（含话术）写进去——让新人/销售能直接抄；</li>\n<li><b>模板</b>：NTF 报告/客诉周报模板补丁（实际用下来的改进）。</li></ul>\n<h5>3. 沉淀的质量标准（检验它\"活\"不活）</h5>\n<p><b>拿给新人看，新人能看懂并执行 → 达标</b>。如果只有你自己能看懂，那只是笔记不是手册。两个检验角度：</p>\n<ul><li>新人照做能不能到 80%？（步骤是否够细、判据是否清楚）；</li>\n<li>你 3 个月后回来看能不能秒懂？（当时的\"显然\"对未来的你是\"谜\"）。</li></ul>\n<h5>4. 沉淀的节奏（不让积累烂在脑子里）</h5>\n<ul><li><b>每单闭环当天</b>：200 字复盘入案例库；</li>\n<li><b>每周五</b>：本周新增套路回填手册/FAQ；</li>\n<li><b>每月末</b>：手册版本 +1，发团队评审（版本要留痕）；</li>\n<li><b>每季度</b>：挑一次主题做内部分享（逼自己结构化输出）。</li></ul>\n<div class=\"tip\">💡 沉淀的最高境界：当你离开岗位 3 个月，团队能靠你的手册/FAQ 正常运转——这就是\"把能力变成组织能力\"。</div><h5>5. 沉淀的进阶心法</h5><ul><li>方法论要“去场景化”：从“这条内存虚焊怎么查”抽象成“偶发硬件问题怎么查”；</li><li>沉淀不是写论文：能用图表就用图，能 3 步写完不写 8 步；</li><li>定期“使用检验”：你真的用手册解决了新问题吗？没用到的章节删掉；</li><li>沉淀成果主动交付（分享/评审）——文档不被人看就是死的。</li></ul>"}], "out": "M5 月报 + 手册/FAQ 增量"}]}, {"id": "m6", "badge": "M6", "title": "深化期第三月：沉淀手册 · 分享带教", "sub": "在岗深化 · 让能力变成团队的资产", "accept": "产出 1 套可复用资料，内部分享并尝试带教。", "tools": "标准化排查手册、FAQ、团队KPI对齐、半年述职", "phase": "M", "weekend": "", "days": [{"id": "d67", "title": "标准化排查手册 V1（第1-2周）", "date": "M6 月初", "dot": "1", "tasks": ["整理《标准化排查手册》V1：故障映射表→处置流程→模板引用", "整理《FAQ》V1：覆盖高频客诉问题（含话术模板）", "用\"新人视角\"测试手册：让没经验的人能看懂执行", "建立手册版本管理与更新机制"], "tools": "排查手册框架、FAQ模板", "resources": [], "lectures": [{"title": "M6 排查手册 V1：把个人经验变成团队资产", "html": "<h5>1. 手册结构建议（新人拿到就能上手）</h5>\n<ol><li><b>故障现象 → 候选根因（≥4 条 + 排序）→ 验证方法</b>：以现象为入口，不是以根因为条目（新人按现象查）；</li>\n<li><b>排查路径图（标准七层）</b>：信息收集 → 外观/接触 → 最小化 → 交叉替换 → BIOS/软设置 → 工具压测 → 深入分析；</li>\n<li><b>常用工具速查</b>：MT86/BurnInTest/HWiNFO 的最常用参数、判读方法、耗时预期；</li>\n<li><b>报告模板引用</b>：FA/测试/邮件模板的链接（不重复贴，指向标准文档）；</li>\n<li><b>案例索引</b>：按现象/平台检索案例库（附链接）。</li></ol>\n<h5>2. 写作要点（决定手册能不能被用起来）</h5>\n<ul><li>用<b>新人视角</b>检查：假设读者只会基本操作——操作步骤写到\"双击图标\"级别；</li>\n<li>每条结论给<b>判断依据</b>（为什么先查这个，而不是背顺序）——懂得原理才能灵活应变；</li>\n<li>每条验证方法给<b>预期结果</b>和<b>下一步分支</b>（如果 PASS 走 A，FAIL 走 B）；</li>\n<li>版本管理：V1 标日期、维护人，评审后发团队——后续变更走评审，别一两个人悄悄改。</li></ul>\n<h5>3. 写好手册的\"三查\"</h5>\n<ul><li><b>查完整</b>：十大客诉场景（无法开机/蓝屏/容量错/性能差/死机/不识别/NTF/混插/高温/报错）每个都有章节吗？</li>\n<li><b>查可执行</b>：每步都知道\"用什么工具、看什么参数、多久、判据是什么\"吗？</li>\n<li><b>查边界</b>：哪些情况要升级、哪些能自主处理，手册里有分界线吗？</li></ul>\n<h5>4. 手册与 FAQ/案例库的分工</h5>\n<table><tr><th>资产</th><th>定位</th><th>举例</th></tr>\n<tr><td>排查手册</td><td>方法论 + 路径（怎么想）</td><td>七层排查 SOP</td></tr>\n<tr><td>案例库</td><td>具体实例（以前遇到过）</td><td>某批次虚焊案例</td></tr>\n<tr><td>FAQ</td><td>高频问题标准答（怎么答）</td><td>\"内存条要插哪两个槽\"</td></tr></table>\n<div class=\"tip\">💡 手册的最终检验：\"今天来一个实习生，能拿你的手册独立处理常规客诉吗？\"能，手册就成功了。不能，继续改。</div>"}, {"title": "FAQ 怎么写才有人看", "html": "<h5>1. FAQ 的价值（省的是团队重复回答的时间）</h5>\n<p>FAQ = 把高频客诉问题与标准回答沉淀下来，让新人/销售/客户都能自助。你每写一条 FAQ，就省了未来 N 次重复回答——<b>FAE 的时间应该花在疑难上，而不是高频重复上</b>。</p>\n<h5>2. 一条好 FAQ 的结构（5 要素）</h5>\n<ol><li><b>问题</b>：客户原话（不是技术术语）——写\"内存只有2400\"，不写\"频率不达标\"；</li>\n<li><b>背景</b>：什么平台/什么现象高频出现（帮读者快速判断\"是不是我遇到的\"）；</li>\n<li><b>标准回答</b>：可直接复制的话术（客户问，直接抄着发）；</li>\n<li><b>排查步骤</b>：若回答不够，附验证步骤（工具/参数/判据）；</li>\n<li><b>相关案例号</b>：指向案例库深入资料（FAQ 是入口，案例库是详情）。</li></ol>\n<h5>3. 示例（高频开场）</h5>\n<pre>\nQ：刚装的内存为什么任务管理器显示频率只有 2400？\n背景：DDR4/DDR5 新装条，常见于未开 XMP。\n标准回答：XMP/EXPO 默认关闭时按 JEDEC 保守档运行，\n  4800/2400 是正常的。请进 BIOS 开启 XMP/EXPO 后\n  重新查看频率，需要我发设置截图吗？\n排查：BIOS→Memory Profile→XMP1→保存重启→CPU-Z 确认\n案例：FAE-2026-008\n</pre>\n<h5>4. FAQ 维护纪律</h5>\n<ul><li>每单客诉闭环时<b>顺手上架/更新</b>（30 秒的事，别等月底）；</li>\n<li>按\"平台+现象\"打标签，方便检索；</li>\n<li>每月评审：哪些过时了、哪些还没覆盖（新平台新现象要补）；</li>\n<li>FAQ 也是给销售的武器——销售能自助回答的问题，就不会半夜找你。</li></ul>\n<div class=\"tip\">💡 FAQ V1 不求全，先从最近 10 单客诉里挑 5 条最高频的写起。写 5 条 > 想写 50 条。</div><h5>5. FAQ 质量的三个“别”</h5><ul><li>别写术语标题（“内存频率不达标”不如“内存怎么只有2400”）；</li><li>别写两句话结论（“开XMP就好”）——要带步骤和截图；</li><li>别写“见附件”（没人看附件）——把关键内容直接放正文。</li></ul><p>FAQ 写完后做“陌生人测试”：让同事不看资料能不能照着做？能，才是合格 FAQ。</p>"}], "out": "排查手册 V1 + FAQ V1（可复用资料）"}, {"id": "d68", "title": "内部分享（第3周）", "date": "M6 月中", "dot": "2", "tasks": ["做 1 次内部分享（技术分享会/新人培训），分享手册+典型案例", "收集听众反馈，迭代手册", "尝试带教 1 个新人/实习生（带教记录）", "与导师对齐：离\"独当一面 FAE\"还差什么"], "tools": "分享PPT、反馈收集表", "resources": [{"type": "vid", "url": "https://www.bilibili.com/video/BV18z421Y7SY", "label": "▶ 如何做一次公开技术分享（axb · 1653播放）"}, {"type": "vid", "url": "https://www.bilibili.com/video/BV1Tr4y1H7qA", "label": "▶ 培养演讲力·精彩演讲（成信听书 · 2.4万播放）"}], "lectures": [{"title": "内部分享与带教：让经验流动起来", "html": "<h5>1. 为什么要内部分享</h5>\n<p>分享＝把你踩过的坑、总结的方法变成团队的资产。对公司是知识沉淀，对你是<b>专业影响力的积累</b>——很多公司晋升资深/主管，看的除了业绩还有\"有没有人因为你的分享而少踩坑\"。分享是 FAE 从\"干活的人\"变成\"有影响力的人\"的分水岭。</p>\n<h5>2. 技术分享的结构（30 分钟标准版）</h5>\n<ol><li><b>背景/痛点</b>：这个坑是怎么遇到的（客户一句话/一次偶发/一个奇怪现象）——有代入感才有人听；</li>\n<li><b>排查过程</b>：错误尝试也要讲——别人只有看到你走过的弯路才知道为什么；</li>\n<li><b>结论与方法</b>：可复用的套路（路径图/清单/话术），给\"下一步直接能抄\"的；</li>\n<li><b>提问与答疑</b>：提前准备 2-3 个常见追问（别人会问什么先想好）。</li></ol>\n<h5>3. 分享的表达技巧</h5>\n<ul><li>一页一个观点，别堆信息；</li>\n<li>用真实数据/截图/日志，讲细节才有说服力；</li>\n<li>讲\"为什么这么做\"比讲\"这么做\"重要——授人以渔；</li>\n<li>结尾给 1 个\"立刻能用\"的产出（清单/模板/速查卡）。</li></ul>\n<h5>4. 带教新人的要点（M6 尝试带教）</h5>\n<ul><li><b>让新人先做再看</b>：暴露问题才学得快——别什么都替他做完；</li>\n<li>给\"怎么做\"也给<b>\"为什么\"</b>：不带原理的操作教不出能应变的人；</li>\n<li><b>带教记录</b>：每周 10 分钟同步，及时纠偏，别等月末才发现方向错；</li>\n<li>示范 vs 代劳：遇到问题先问\"你怎么看？\"再给建议。</li></ul>\n<h5>5. 分享素材从哪来（零成本积累）</h5>\n<p>你的<b>案例库</b>就是素材池：每闭环一单客诉写 200 字复盘 → 攒一个月就是一次内部分享的骨架。不要等\"准备分享\"才开始积累，平时每单都在积累。</p>\n<div class=\"tip\">💡 分享后主动收集反馈：哪些大家最感兴趣？哪些没听懂？——下一次分享的起点，就是这次的反馈。</div><h5>5. 带教的常见误区</h5><ul><li>替新人做：学不到东西，你还更累（先让他试）；</li><li>只给结论不给过程：下个问题还是不会（讲为什么）；</li><li>不接受错误：新人怕犯错就问你，形成依赖（错误是最好的教材，复盘即可）；</li><li>没有反馈记录：带教效果无法评估（每周 10 分钟同步留痕）。</li></ul>"}], "out": "分享记录 + 带教记录"}, {"id": "d69", "title": "半年复盘 + 述职（月末）", "date": "M6 月末", "dot": "3", "tasks": ["半年总结：12周+3月成果全景汇总（数据化）", "对齐团队 KPI：闭环效率/准确率/知识库产出", "制定下半年计划：升资深FAE的目标分解", "完成 M6 验收：1套可复用资料 + 内部分享 + 带教尝试"], "tools": "半年述职模板、KPI表", "resources": [], "lectures": [{"title": "M6 述职：把 6 个月做成 3 页纸", "html": "<h5>1. 述职报告结构（3 页纸，别写论文）</h5>\n<ol><li><b>数据总览</b>：处理客诉 X 单、闭环率 Y%、NTF 主导 N 单、案例库 M 例——第一页就是硬数字；</li>\n<li><b>能力成长</b>：从\"不会测\"到\"独立主导\"的 3 个里程碑（各配一个证据：报告/案例/数据）；</li>\n<li><b>资产产出</b>：排查手册/FAQ/模板/内部分享——让公司看到你沉淀了东西；</li>\n<li><b>不足与计划</b>：最想补的 2 个短板 + 下半年目标（可量化）。</li></ol>\n<h5>2. 述职技巧（决定观感）</h5>\n<ul><li><b>用数据说话，不用形容词</b>：\"很多\"→具体数字；\"进步很大\"→环比提升多少；</li>\n<li>讲 1-2 个<b>代表性案例</b>（过程+结果+方法论），别罗列流水账；</li>\n<li>主动提\"我需要什么支持\"（培训/工具/平台）——比被动等安排强，领导喜欢有想法的；</li>\n<li>准备\"被追问页\"：数字的出处、案例的细节、不足的解法，预先想好。</li></ul>\n<h5>3. 述职报告模板（可直接套）</h5>\n<pre>\n一、数字：客诉 X 单 / 闭环率 Y% / NTF 主导 N / 案例库 M\n二、成长：3 个里程碑（事件+证据）\n   M4：独立接单（首单闭环记录）\n   M5：NTF 主导（闭环报告）\n   M6：手册+分享+带教（产出物）\n三、资产：手册 V1 / FAQ / 模板 / 分享 2 次\n四、不足与计划：短板 A → 下半年动作 B → 目标 C（可量化）\n</pre>\n<h5>4. 述职后的动作（不是交完就结束）</h5>\n<p>根据反馈更新下半年计划；把述职中暴露的短板列入学习清单；确认 M4-M6 验收全部打勾；和导师约定下次检查点。</p>\n<div class=\"tip\">💡 述职不是\"汇报过去\"，是\"争取资源\"：领导听完要能说\"这人值得培养\"。所以重点不是苦劳，是你创造的资产和下一步的野心。</div><h5>5. 述职中的数据来源（平时就要攒）</h5><ul><li>客诉数/闭环率：跟进表自动统计；</li><li>NTF/疑难：案例库状态字段；</li><li>手册/FAQ/模板：文档版本历史；</li><li>内部分享：分享记录（时间/主题/人次）。</li></ul><p>没有日常记录，述职时只能靠回忆——<b>述职准备第一天就该开始，而不是述职前一周</b>。</p>"}], "out": "半年述职报告 + 可复用资料包"}]}];
